begin;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21201, 2, 209, 1201, 'hadith', 'عن أبي موسى الأشعري، رضي الله عنه، قال: دخلت على النبي صلى الله عليه وسلم، وطرف السواك على لسانه. ((متفق عليه)) . وهذا لفظ مسلم.', 'I came to the Prophet (ﷺ) once and noticed the tip of Miswak (tooth-stick) on his tongue..', 'أبي موسى الأشعري رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', null, 'رياض الصالحين 1201', 'Riyad as-Salihin 1201', 'ریاض الصالحین 1201', null, null, null, null, 'sunnah.com', null, false, null, false),
(21202, 2, 209, 1202, 'hadith', 'عن عائشة رضي الله عنها ان النبي صلى الله عليه وسلم : قال: «السواك مطهرة للفم مرضاة للرب».', 'The Prophet (ﷺ) said, "The Miswak (tooth-stick) cleanses and purifies the mouth and pleases the Rubb.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', null, 'رياض الصالحين 1202', 'Riyad as-Salihin 1202', 'ریاض الصالحین 1202', 'رواه النسائي، وابن خذيمة في صحيحه بأسانيد صحيحة', null, null, null, 'sunnah.com', null, false, null, false),
(21203, 2, 209, 1203, 'hadith', 'عن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم قال: «الفطرة خمس، أو خمس من الفطرة: الختان، والاستحداد، وتقليم الأظفار، ونتف الإبط، وقص الشارب» ((متفق عليه)) (24)', 'The Prophet (ﷺ) said, "There are five acts which conform to the pure nature: Circumcision, removing of the pubic hair, clipping the nails, plucking the underarm hair and trimming the moustache.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 1203', 'Riyad as-Salihin 1203', 'ریاض الصالحین 1203', null, null, null, null, 'sunnah.com', null, false, null, false),
(21204, 2, 209, 1204, 'hadith', 'عن عائشة رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم : «عشر من الفطرة: قص الشارب، وإعفاء اللحية، والسواك، واستنشاق الماء، وقص الأظفار، وغسل البراجم، ونتف الإبط، وحلق العانة، وانتقاص الماء» ((قال الراوي: ونسيت العاشرة إلا أن تكون المضمضة، قال: وكيع- وهو أحد رواته-)) . (25) ((رواه مسلم)).(( (26)', 'The Messenger of Allah (ﷺ) said, "There are ten demands of pure nature: trimming the moustache, letting the beard grow, using Miswak (tooth-stick), snuffing up water into the nose (in ablution), paring the nails, washing the bases of the finger joints; plucking the underarm hair, removing of the pubic hair and removing impurities with water from the affected part after a call of nature."The subnarrator said: I forgot the tenth but it might possibly be the rinsing of the mouth (in ablution)..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1204', 'Riyad as-Salihin 1204', 'ریاض الصالحین 1204', null, 'تخبر عائشة رضي الله عنها عن النبي صلى الله عليه وسلم بجُملة من سنن الفطرة. 
و"الفِطْرة" هي الخِلْقَة التي خلق الله عباده عليها، وجعلهم مفطورين عليها، وأنها من الخير والمراد بذلك الفِطَر السليمة؛ لأن الفطر المُنْحَرفة لا عبرة بها؛ لقول النبي صلى الله عليه وسلم : "كل مَولود يُولد على الفِطْرة فأبواه يهودانه أو ينصرانه أو يُمَجِّسَانه".
فأولها: "قَصُّ الشَارِب" حَفُّه حتى تبدو الشَفَة، لما في ذلك من النظافة، والتحرز مما يخرج من الأنف، فإن شعر الشارب إذا تدلى على الشفة باشر به ما يتناوله من مأكول ومشروب، مع تشويه الخِلقة بوفرته، وإن استحسنه من لا يعبأ به.
فينبغي للمسلم أن يَتَعاهد شاربه بالقص أو الحَفِّ ولا يتركه أكثر من أربعين يومًا؛ لما رواه مسلم عن أنس رضي الله عنه : "وُقِّت لنا في قص الشارب، وتقليم الأظفار، ونتف الإبط، وحلق العانة، أن لا نترك أكثر من أربعين ليلة". 
"وإعفاء اللحية"واللحية: ما نبت على الذقن واللحيين، والمقصود من إعفائها: تركها مُوَفَّرَةً لا يتعرض لها بحلق ولا بتقصير، لا بقليل ولا بكثير؛ لأن الإعفاء مأخوذ من الكثرة أو التوفير، فاعفوها وكثروها، كقوله تعالى: (حتى عَفَوا)، وقد جاءت الأحاديث الكثيرة عن رسول الله صلى الله عليه وسلم بالأمر بإعفائها بألفاظ متعددة؛ فقد جاء بلفظ : "وفروا" وبلفظ: "أرخوا" وبلفظ: "أعفوا"، وكلها تدل على الأمر بإبقائها وتوفيرها وعدم التعرض لها، وعلى هذا لا يجوز للمسلم أن يحلق لحيته بحال من الأحوال، فإن فعل فقد خالف طريق النبي صلى الله عليه وسلم وعصى أمره ووقع في مشابهة المشركين. 
"والسِّواك": يعني: أن السواك من خصال الفطرة التي رغَّب بها الشرع، فهو "مَطْهَرة للفم مرضاة للرب" ولهذا يشرع كل وقت ويتأكد عند الوضوء والصلاة والانتباه من النوم وتغير الفم وصفرة الأسنان ونحوها.
"وَاسْتِنْشَاقُ الماء" يعني: أن استنشاق الماء من الفطرة؛ لأنه تنظيف، وإزالة لما في الأنف من الأوساخ التي قد تسبب له الأذية والضرر.
والاستنشاق يكون في الوضوء ويكون في غير الوضوء كلما احتجت إلى تنظيف الأنف فاستنشق الماء ونظف أنفك، وهذا يختلف باختلاف الناس، من الناس من لا يحتاج إلى هذا إلا في الوضوء ومن الناس من يحتاج إليه كثيرًا.
ومن ذلك أيضًا: أي من سنن الفطرة المضمضة ، فإنها من الفطرة؛ فالفم والأنف يتوارد عليهما كثير من الأوساخ، فكان من الفطرة الاعتناء بهما. 
"وقص الأظفار" يعني من خصال الفطرة : تقليم الأظفار، والمراد بذلك أظفار اليدين والرجلين، فلا تترك أكثر من أربعين يوماً؛ للحديث السابق.
"وغَسْل البَرَاجِم" أي غَسْل مَفَاصِل الأصابع الظاهرة والباطنة؛ لأنها مواضع تجتمع فيها الأوساخ؛ لتجعدها وانكماشها، فقد لا يصلها الماء، وإذا تُعوهدت بأن تُدلك، وأن تُمَرَّ عليها اليد الثانية، فإن الماء يَصل إليها، فكان من الفطرة الاعتناء بها. 
ويلحق بالبراجم كُلُّ موضع من البدن اجتمع فيه وسَخٌ بِعَرَق أو غيره كصِمَاخ الأذن والمغَابِن -بواطن الأفخاذ- وغيرها مما يغلب عليه الاستتار. 
"ونَتْف الإبْط" يعني: من خصال الفطرة نتف الإبْط، وهو سحبه وشده من أصوله، وذلك أنه في مكان يكثر فيه العرق، وتجتمع فيه الأوساخ، وتتغير معه الرائحة، ولا يترك أكثر من أربعين يومًا؛ لما تقدم من حديث أنس رضي الله عنه ، والأفضل نَتْفه إن قَوي عليه، وإذا كان النتف يشق، فلا بأس من الحَلق أو استعمال الكريمات المزيلة؛ لأن الغرض إزالتها وتنظيف المحل، وقد حصل.
"وحَلْق العَانة" أي :أن من خِصال الفطرة إزالة شَعر العانة، وهو الشعر الخَشِن النابت حول القُبُل، من الرجل والمرأة، فمن الفطرة إزالته، سواء بالحلق أو النتف أو القص أو باستعمال المستحضرات الحديثة؛ لأن المقصود التنظيف، وقد حصل به المطلوب، ولا يترك أكثر من أربعين يومًا لما تقدم من حديث أنس رضي الله عنه . 
"وانْتِقَاصُ الماء" يعني من الفطرة انتقاص الماء، وفُسر: بالاستنجاء، ويؤيد هذا المعنى رواية أبي داود وابن ماجه عن عمار بن ياسر رضي الله عنه عن النبي صلى الله عليه وسلم : "من الفطرة: المضمضة، والاستنشاق.. والانتضاح"، والاستنجاء: إزالة الخارج من السبيلين بطاهر، كالماء والحَجَر والخرق والمناديل، ونحو ذلك مما له خاصية الإزالة. 
"قال الراوي: ونسِيْت العاشرة إلا أن تكون المضمضة" فهذا شك من الراوي. 
وحاصله أن هذه الأشياء كلها، تُكْمل ظاهر الإنسان وتطهره وتنظفه، وتدفع عنه الأشياء الضارة والمستقبحة.', 'أن هذه الخصال من السنة القديمة التي اختارها الانبياء واتفقت عليها الشرائع القديمة، وهي أمور تقتضيها النظافة والطبيعة الإنسانية.
اعتناء الشريعة بالنظافة.
الأخذ من اللحية مخالف للفطرة التي فُطِرَ الناس عليها.
يدل مفهوم الحديث على عدم مشروعية حلق الشارب.
مشروعية الاستنجاء بالماء.
أن نسيان الراوي لبعض أفراد الحديث لا يقدح في صحة الحديث، إذا كان أًصل الحديث ثابتًا.', 'الفطرة : في اللغة الابتداء والاختراع، المراد هنا: الجِبِلَّةُ التي خلق الله الناس عليها، وجبلهم على فعلها.
إعفاء اللحية : تركها لا يقص منها شيء.
الاستنشاق : إيصال الماء إلى أعلى الأنَف.
العانة : الشعر النابت أسفل البطن حول الفرج.
اسنتقاص الماء : الاستنجاء.
البراجم : عُقَد الأصَابِع.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3730', false),
(21205, 2, 209, 1205, 'hadith', 'عن ابن عمر رضي الله عنهما، عن النبي صلى الله عليه وسلم قال: «أحفوا الشوارب وأعفوا اللحى».', 'The Prophet (ﷺ) said, "Trim the moustaches and let the beard grow.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1205', 'Riyad as-Salihin 1205', 'ریاض الصالحین 1205', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21206, 2, 209, 1206, 'hadith', 'عن ابن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم قال: «بني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمدًا عبده ورسوله، إقام الصلاة، وإيتاء الزكاة، وحج البيت، وصوم رمضان».', 'The Messenger of Allah (ﷺ) said, "(The structure of) Islam is built on five (pillars): Testification of ''La ilaha illallah'' (none has the right to be worshipped but Allah), that Muhammad (ﷺ) is his slave and Messenger, the establishment of Salat, the payment of Zakat, the pilgrimage to the House of Allah (Ka''bah), and Saum during the month of Ramadan.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1206', 'Riyad as-Salihin 1206', 'ریاض الصالحین 1206', 'متفق عليه', 'شَبَّهَ النبيُّ صلى الله عليه وسلم الإسلامَ بِبِناءٍ مُحْكَمٍ بأركانه الخمسة الحاملة لذلك البُنيان، وبقية خصال الإسلام كتتمة البنيان، 
وأولُ هذه الأركان: الشهادتان؛ شهادة أن لا إله إلا الله وأنَّ محمدًا رسول الله، وهما ركن واحد؛ لا تنفك إحداهما عن الأخرى، ينطق العبد بهما معترفًا بوحدانية الله واستحقاقه للعبادة وحده دون ما سواه، وعاملًا بمقتضاها، ومؤمنًا برسالة محمد صلى الله عليه وسلم مُتَّبِعًا له. 
والركن الثاني: إقامة الصلاة، وهي الصلوات الخمس المفروضات في اليوم والليلة: الفجر، والظهر، والعصر، والمغرب، والعشاء، بشروطها وأركانها وواجباتها. 
والركن الثالث: إخراج الزكاة المفروضة، وهي عبادة ماليَّة واجبة في كل مال بَلَغَ قَدْرًا مُحَدّدًا في الشرع، تُعطى لمستحقيها. 
والركن الرابع: الحج، وهو قَصْدُ مكة لإقامة المَناسك، تَعبُّدًا لله عز وجل. 
والركن الخامس: صوم رمضان، وهو الإمساك عن الأكل والشرب وغيرهما من المفطرات بِنِيَّةِ التعبُّد لله، من طلوع الفجر إلى غروب الشمس.', 'تلازم الشهادتين، فلا تصح أحدهما إلا بالأخرى؛ لذا جعلهما ركنًا واحدًا.
الشهادتان هما أساس الدين، فلا يُقبل قولٌ ولا عملٌ إلا بهما.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65000', false),
(21207, 2, 209, 1207, 'hadith', 'عن طلحة بن عبيد الله، رضي الله عنه قال: جاء رجل إلى رسول الله صلى الله عليه وسلم، من أهل نجد، ثائر الرأس نسمع دوي صوته، ولا نفقه ما يقول، حتى دنا من رسول الله صلى الله عليه وسلم فإذا هو يسأل عن الإسلام، فقال الرسول صلى الله عليه وسلم : "خمس صلوات في اليوم والليلة" قال: هل علي غيرهن؟ قال: "لا، إلا أن تطوع" فقال رسول الله صلى الله عليه وسلم : "وصيام شهر رمضان" قال هل على غيره؟ قال: "لا إلا أن تطوع" قال: وذكر له رسول الله صلى الله عليه وسلم، الزكاه فقال: هل علي غيرها؟ قال: "لا، إلا أن تطوع" فأدبر الرجل وهو يقول: والله لا أزيد على هذا ولا أنقص منه، فقال رسول الله صلى الله عليه وسلم : "أفلح إن صدق".', 'A person with dishevelled hair, one of the people of Najd, came to the Messenger of Allah (ﷺ). We heard the humming of his voice but could not fully understand what he was saying, till he approached close to the Messenger of Allah (ﷺ). Then I came to know that he was asking about Islam. The Messenger of Allah (ﷺ) said: "There are five (obligatory) Salat during the day and the night." He said: "Am I obliged to perform any other (Salat) besides these?" The Messenger of Allah (ﷺ) said, "No, but whatever you observe voluntarily." He (ﷺ) added, "There is the Saum of Ramadan." The inquirer asked: "Am I obliged to do anything besides this?" The Messenger of Allah (ﷺ) said, "No, but whatever you do out of your own free will. You may observe voluntary fasting." And the Messenger of Allah (ﷺ) told him about the Zakat (obligatory charity). The inquirer asked: "Am I obliged to pay anything besides this?" The Messenger of Allah (ﷺ) said, "No, but whatever you pay voluntarily out of your own free will." That man turned back saying: "By Allah! I will neither make any addition to this nor will I decrease anything from it." (Upon hearing this) the Messenger of Allah (ﷺ) remarked, "He is successful if he proves truthful (to what he is saying).".', 'طلحة بن عبيد الله رضي الله عنه', 'Talhah bin ''Ubaidullah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1207', 'Riyad as-Salihin 1207', 'ریاض الصالحین 1207', 'متفق عليه', 'جاء رجلٌ من أهل نَجْدٍ إلى النبي صلى الله عليه وسلم وكان شعره مُنْتَفِشًا، وصوته مرتفعًا، ولا يُفقه ما يقول، حتى اقترب من النبي صلى الله عليه وسلم، فسأل عن فرائض الإسلام؟ 

فبدأ النبيُّ صلى الله عليه وسلم بالصلاة، وأخبره أنَّ الله قد افترض عليه خمسَ صلوات في كل يوم وليلة.

فقال: هل يلزمني شيء من الصلوات غير هذه الخَمس؟ 

فقال: لا، إلا إذا تطوَّعت من صلوات النوافل. 

ثم قال صلى الله عليه وسلم: ومما أوجبه الله عليك صوم شهر رمضان.

فقال الرجل: هل يلزمني شيء من الصيام غير صوم رمضان؟ 

فقال: لا، إلا أن تتطوّع بصوم. 

ثم ذكر له صلى الله عليه وسلم الزكاة.

فقال الرجل: هل يلزمني شيء من الصدقات بعد زكاة الفرض؟ 

قال: لا، إلا أن تتطوّع. 

وبعد أن سمع الرجل من النبي صلى الله عليه وسلم هذه الفرائض ولّى مدبرًا وأقسم بالله تعالى أنه سيلتزم بها من غير زيادة ولا نقصان، فقال صلى الله عليه وسلم على إثر ذلك: إذا صَدَقَ الرجل على ما حَلفَ عليه فإنه يكون من المُفلحين.', 'سماحةُ الشريعة الإسلامية وتيسيرها على المكلفين.
حسن معاملته صلى الله عليه وسلم لهذا الرجل، فقد مَكَّنَه من الاقتراب منه وسؤاله.
البدء في الدعوة إلى الله تعالى بالأهم فالأهم.
الإسلام عقيدة وعمل، فلا ينفع عمل من غير إيمان، ولا ينفع إيمان من غير عمل.
أهمية هذه الأعمال وأنها من أركان الإسلام.
صلاة الجمعة داخلة في الصلوات الخمس الواجبة؛ لأنها بدلًا عن صلاة ظهر يوم الجمعة لمن وجبت عليه.
بدأ النبيُّ صلى الله عليه وسلم تعليمه بآكد فرائض الإسلام وهي أركانه بعد الشهادتين؛ لأنه كان مسلمًا، ولم يذكر الحج؛ لأنه قبل فرضهِ، أو لأنه لم يأتِ وقته.
الإنسان إذا اقتصر على الواجب في الشرع فإنه مُفلح، ولكن لا يعني هذا أنه لا يُسن أن يأتي بالتطوع؛ لأن التطوع تكمل به الفرائض يوم القيامة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3700', false),
(21208, 2, 209, 1208, 'hadith', 'عن ابن عباس رضي الله عنه، أن النبي صلى الله عليه وسلم بعث معاذًا رضي الله عنه إلى اليمن فقال: «ادعهم إلى شهادة أن لا إله إلا الله وأني رسول الله، فإن هم أطاعوا لذلك فأعلمهم أن الله تعالى افترض عليهم خمس صلوات في كل يوم وليلة، فإن هم أطاعوا لذلك فأعلمهم أن الله افترض عليهم صدقة تؤخذ من أغنيائهم، وترد على فقرائهم».', 'The Prophet (ﷺ) appointed Mu''adh (May Allah be pleased with him) as governor of Yemen, and at the time of his departure, he instructed him thus: "First of all, call the people to testify ''La ilaha illallah'' (there is no true god except Allah) and that I (Muhammad) am the Messenger of Allah, and if they accept this (declaration of Faith), then tell them that Allah has enjoined upon them five Salat during the day and night; and if they obey you, tell them that Allah has made the payment of Zakat obligatory upon them. It should be collected from their rich and distributed among their poor.".', 'ابن عباس رضي الله عنه', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1208', 'Riyad as-Salihin 1208', 'ریاض الصالحین 1208', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21209, 2, 209, 1209, 'hadith', 'عن ابن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : «أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأن محمدًا رسول الله، ويقيموا الصلاة، ويؤتوا الزكاة، فإذا فعلوا ذلك، عصموا مني دماءهم وأموالهم إلا بحق الإسلام وحسابهم على الله».', 'The Messenger of Allah (ﷺ) said, "I have been commanded to fight people till they testify ''La ilaha illallah'' (there is no true god except Allah) that Muhammad (ﷺ) is his slave and Messenger, and they establish Salat, and pay Zakat; and if they do this, their blood (life) and property are secured except when justified by law, and it is for Allah to call them to account.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1209', 'Riyad as-Salihin 1209', 'ریاض الصالحین 1209', 'متفق عليه', 'يُخْبِرُ النبيُّ صلى الله عليه وسلم أنَّ اللهَ أمرَه بمقاتلة المشركين حتى يشهدوا بأن لا معبود بحق إلا الله وحده لا شريك له، ويشهدوا لمحمد صلى الله عليه وسلم بالرسالة، والعمل بمقتضى هذه الشهادة من المحافظة على الصلوات الخمس في اليوم والليلة، ويعطوا الزكاة المفروضة لمستحقيها. 
فإذا فعلوا هذه الأمورَ فإنَّ الإسلام يَعْصِمُ دماءَهم وأموالَهم، فلا يَحِلُّ قتلُهم إلا إذا ارتكبوا جريمة أو جناية يستحقون عليها القتل بموجب أحكام الإسلام، ثم يوم القيامة يتولى الله تعالى حسابَهم حيث يعلم سرائرَهم.', 'الأحكام إنما تَجْرِي على الظواهر، والله يتولَّى السرائر.
أهمية الدعوة إلى التوحيد وأنه أول ما يُبدأ به في الدعوة.
لا يعني هذا الحديث إكراه المشركين على الدخول في الإسلام، بل هم مُخَيَّرون بين الدخول في الإسلام أو دفع الجزية؛ فإنْ أبوا إلا مَنع الدعوة إلى الإسلام، فليس إلا المقاتلة بموجب أحكام الإسلام.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4211', false),
(21210, 2, 209, 1210, 'hadith', 'عن أبي هريرة رضي الله عنه، قال: لما توفي رسول الله، وكان أبو بكر، رضي الله عنه، وكفر من كفر من العرب، فقال عمر رضي الله عنه: كيف يقاتل الناس وقد قال رسول الله صلى الله عليه وسلم : «أمرت أن أقاتل الناس حتى يقولوا لا إله إلا الله، فمن قالها، فقد عصم مني ماله ونفسه إلا بحقه وحسابه على الله» ؟! فقال أبو بكر: والله لأقاتلن من فرق بين الصلاة والزكاة، فإن الزكاة حق المال. والله لو منعوني عقال كانوا يؤدونه إلى رسول الله صلى الله عليه وسلم، لقاتلتهم على منعه، قال: عمر رضي الله عنه: فوالله ما هو إلا أن رأيت الله قد شرح صدر أبي بكر للقتال، فعرفت أنه الحق.', 'When the Messenger of Allah (ﷺ) passed away, Abu Bakr (May Allah be pleased with him) was appointed as his successor (caliph). Amongst the Arabs some men apostatised. Abu Bakr (May Allah be pleased with him) resolved to fight them. ''Umar bin Al-Khattab (May Allah be pleased with him) said to Abu Bakr: "How can you fight them when the Messenger of Allah (ﷺ) has declared: ''I have been commanded to fight people till they testify La ilaha illallah (there is no true god except Allah); and if they do it, their blood (life) and property are secured except when justified by law, and it is for Allah to call them to account." Upon this Abu Bakr (May Allah be pleased with him) said: "By Allah, I would definitely fight him who makes distinction between Salat and the Zakat, because it is an obligation upon the rich to pay Zakat. By Allah I will fight them even to secure the piece of rope which they used to give to the Messenger of Allah (ﷺ)." ''Umar (May Allah be pleased with him) said: "I realized that Allah opened the heart of Abu Bakr (May Allah be pleased with him) for fighting those who refused to pay Zakat, and I fully recognized that Abu Bakr', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1210', 'Riyad as-Salihin 1210', 'ریاض الصالحین 1210', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21211, 2, 209, 1211, 'hadith', 'عن أبي أيوب رضي الله عنه، أن رجلا قال للنبي صلى الله عليه وسلم : أخبرني بعمل يدخلني الجنة قال: «تعبد الله لا تشرك به شيئًا، وتقيم الصلاة، وتؤتي الزكاة، وتصل الرحم».', 'A man said to the Prophet (ﷺ): "Direct me to a deed which may admit me to Jannah." Upon this he (the Messenger of Allah (ﷺ)) said, "Worship Allah and never associate anything with Him in worship, establish Salat, pay Zakat, and strengthen the ties of kinship.".', 'أبي أيوب رضي الله عنه', 'Abu Ayyub (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1211', 'Riyad as-Salihin 1211', 'ریاض الصالحین 1211', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21212, 2, 209, 1212, 'hadith', 'عن أبي هريرة رضي الله عنه، أن أعرابيًا أتي النبي صلى الله عليه وسلم فقال: يا رسول الله دلني على عمل إذا عملته، دخلت الجنة. قال: "تعبد الله ولا تشرك به شيئًا، وتقيم الصلاة، وتؤتي الزكاة المفروضة، وتصوم رمضان" قال: والذي نفسي بيده، لا أزيد على هذا. فلما ولى قال النبي صلى الله عليه وسلم : "من سره أن ينظر إلى رجل من أهل الجنة فلينظر إلى هذا".', 'A bedouin came to the Prophet (ﷺ) and said: "O Messenger of Allah! Direct me to a deed by which I may be entitled to enter Jannah." The Prophet (ﷺ) said, "Worship Allah, and never associate anything with Him, establish Salat, pay the Zakat which has been enjoined upon you, and observe Saum of Ramadan." He (the bedouin) said: "By Him in Whose Hand my soul is, I will never add anything to these (obligations)." When he turned his back, the Prophet (ﷺ) said, "He who wants to see a man from the dwellers of Jannah, let him look at him (bedouin).".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1212', 'Riyad as-Salihin 1212', 'ریاض الصالحین 1212', 'متفق عليه', 'قَدِمَ رجلٌ مِن أهلِ الباديةِ على النبيِّ صلى الله عليه وسلم لِيَدُلَّه على عَملٍ يُدخله الجنة، 
فأجابه النبي صلى الله عليه وسلم بأنَّ دخول الجنة والنجاة من النار يَتَوَقَّفانِ على أداء أركان الإسلام، من عبادة الله وحده، وأن لا تشرك به شيئًا. 
وتقيم الصلوات الخمس التي أوجبها الله على عباده في كل يوم وليلة. 
وتعطي زكاة المال التي أوجبها الله عليك، وتدفعها لمستحقها. 
وتحافظ على صيام شهر رمضان في وقته. 
قال الرجل والذي نفسي بيده لا أزيد على العمل المفروض الذي سمعته منك شيئًا من الطاعات، ولا أنقص منه. 
فلما انصرف قال النبي صلى الله عليه وسلم: 
مَن سرَّه أن يَنظرَ إلى رجل من أهل الجنة فلينظر إلى هذا الأعرابي.', 'توحيد الله تعالى بالعبادة أول ما يُبدأ به في الدعوة إلى الله.
الاكتفاء بتعليم الواجبات على مَن كان حديثَ عهدٍ بإسلام.
الدعوة إلى الله تعالى لا بُد فيها من التدرُّج.
حرص الرجل على تَعلُّم أمر دينه.
إذا اقتصر المسلم على الواجبات فإنه يفلح، ولكن لا يعني هذا التساهل بالتطوعات؛ لأن التطوع يُكمل به النقص بالفرائض.
تخصيص بعض العبادات بالذكر دليل على أهميتها والحض عليها، ولا يعني عدم وجوب غيرها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3689', false),
(21213, 2, 209, 1213, 'hadith', 'عن جرير بن عبد الله، رضي الله عنه، قال: بايعت النبي، صلى الله عليه وسلم، على إقام الصلاة، وإيتاء الزكاة، والنصح لكل مسلم.', 'I pledged allegiance to the Prophet (ﷺ) to establish Salat, to pay the Zakat and to have the welfare of every Muslim at heart..', 'جرير بن عبد الله رضي الله عنه', 'Jarir bin ''Abdullah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1213', 'Riyad as-Salihin 1213', 'ریاض الصالحین 1213', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21214, 2, 209, 1214, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "ما من صاحب ذهب، ولا فضة، لا يؤدي منها حقها إلا إذا كان يوم القيامة صفحت له صفائح من نار، فأحمي عليها في نار جهنم فيكوى بها جنبه، وجبينه، وظهره، كلما بردت أعيدت له في يوم كان مقداره خمسين ألف سنة، حتى يقضى بين العباد فيرى سبيله، إما إلى الجنة، وإما إلى النار" قيل: يا رسول الله فالإبل؟ قال: "ولا صاحب إبل لا يؤدي منها حقها، ومن حقها حلبها يوم وردها، إلا إذ كان يوم القيامة بطح لها بقاع قرقر أوفر ما كانت، لا يفقد منها فصيلا واحدًا، تطؤه بأخفافها، وتعضه بأفواهها كلما مر عليه أُولاها، رد عليه أُخراها، في يوم كان مقداره خمسين ألف سنة، حتى يقضى بين العباد، فيرى سبيله، إما إلى الجنة، وإما إلى النار" قيل: يا رسول الله فالبقر والغنم؟ قال: "ولا صاحب بقر ولا غنم لا يؤدي منها حقها إلا إذا كان يوم القيامة، بطح لها بقاع قرقر، لا يفقد منها شيئًا ليس فيها عقصاء، ولا جلحاء، ولا عضباء، تنطحه بقرونها، وتطؤه بأظلافها، كلما مر عليه أُولاها، رد عليه أُخراها، في يوم كان مقداره خمسين ألف سنة حتى يقضى بين العباد، فيرى سبيله، إما إلى الجنة، وإما إلى النار" . قيل: يا رسول الله فالخيل؟ قال: "الخيل ثلاثة: هي لرجل وزر، وهي لرجل ستر، وهي لرجل أجر، فأما التي هي له وزر فرجل ربطها رياء وفخرًا ونواء على أهل الإسلام، فهي له وزر، وأما التي هي له ستر، فرجل ربطها في سبيل الله، ثم لم ينسَ حق الله في ظهورها، ولا رقابها فهي له ستر، وأما التي هي له أجر، فرجل ربطها في سبيل الله لأهل الإسلام في مرج، أو روضة، فما أكلت من ذلك المرج أو الروضة من شيء إلا كتب له عدد ما أكلت حسنات، وكتب له عدد أرواثها وأبوالها حسنات، ولا تقطع طولها فاستنت شرفًا أو شرفين إلا كتب الله له عدد آثارها، وأرواثها حسنات، ولا مر بها صاحبها على نهر فشربت منه، ولا يريد أن يسقيها إلا كتب الله له عدد ما شربت حسنات" والإيتار قبل النوم إنما يستحب لمن لا يثق باستيقاظ آخر الليل، فإن وثق فآخر الليل أفضل.', 'The Messenger of Allah (ﷺ) said, "Any person who possesses gold or silver and does not pay what is due on it (i.e., the Zakat); on the Day of Resurrection, sheets of silver and gold would be heated for him in the fire of Hell and with them his flank, forehead and back will be branded. When they cool down, they will be heated again and the same process will be repeated during the day the measure whereof will be fifty thousand years. (This would go on) until Judgement is pronounced among (Allah''s) slaves, and he will be shown his final abode, either to Jannah or to Hell." It was asked, "How about someone who owns camels and does not pay what is due on him (i.e., their Zakat)?" He (ﷺ) replied, "In the same way the owner of camels who does not discharge what is due in respect of them (their due includes their milking on the day when they are taken to water) will be thrown on his face or on his back in a vast desert plain on the Day of Resurrection and they will trample upon him with their hoofs and bite him with their teeth. As often as the first of them passes him, the last of them will be made to return during a day the measure whereof will be fifty thousand years, until Judgement is pronounced among (Allah''s) slaves, he will be shown his final abode either to Jannah or to Hell." It was (again) asked: "O Messenger of Allah, what about cows (cattle) and sheep?" He (ﷺ) said, "If anyone who possesses cattle and sheep and does not pay what is due on them (i.e., their Zakat); on the Day of Resurrection, he will be thrown on his face in a vast plain desert. He will find none of the animals missing with twisted horns, without horns or with a broken horn, and they will gore him with their horns and trample upon him with their hoofs. As often as the first of them passes him, the last of them will be made to return to him during a day the measure whereof will be fifty thousand years, until Judgement is pronounced among (Allah''s) slaves; and he will be shown his final abode either to Jannah or to Hell." It was asked: "O Messenger of Allah, what about the horses?" Upon this he (ﷺ) said, "The horses are of three types. One, which is a burden for the owner; another which is a shield, and another one which makes its owner entitled to reward. The one for whom these are a burden is the person who rears them for show or for pride or for causing injury to the sentiments of the Muslims. They will be a cause of torment for their owners. The one for whom these are a shield is the person who rears them for the sake of Allah but does not forget the Right of Allah concerning their backs and their necks (i.e., he lets a needy ride on them), and so they are a shield for him. Those which bring reward to the one who rears them in pastures and gardens are the ones that are used in the Cause of Allah (Jihad) by the Muslims. Whatever they eat from the meadows and the gardens will be recorded on his behalf as good deeds so much so that their droppings and urine will be counted for an equal number of good deeds for him. Even when they break their tying rope and every height from which they climb and every hoofprint which they leave will be counted as a good deed on behalf of the owner. When their owner leads them through a stream from which they drink, though he does not intend to quench their thirst, yet Allah would record for him the quantity (of water) of what they would drink on his behalf as good deeds." It was asked: "O Messenger of Allah, what about the donkeys?" Upon this he (ﷺ) said, "Nothing has been revealed to me in regard to the donkeys in particular except this one Verse of a comprehensive nature: "So whosoever does good equal to the weight of an atom (or a small ant) shall see it. And whosoever does evil equal to the weight of an atom (or a small ant) shall see it."'' (99: 8,9)..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1214', 'Riyad as-Salihin 1214', 'ریاض الصالحین 1214', null, 'بَيَّنَ النبيُّ صلى الله عليه وسلم أصنافًا من المال، وجزاء مَن لم يُؤدِّ زكاتها يوم القيامة، ومنها: 

الأول: الذهب والفضة وما في حكمهما من أموال وعروض تجارة، وهو ما وجبت فيه الزكاة فلم تُؤَدَّ، فإذا كان يوم القيامة صُهِرت وسُكِبت على هيئة الألواح، وأوقد عليها في نار جهنم، وعُذِّب بها صاحبها، فيكوى بها جَنْبُه وجَبْهَتُه وظَهره، كلما بَرَدتْ أُعيد إحماؤها، ويستمر على هذه الحال من العذاب طوال يوم القيامة الذي مِقْدار يومِهِ خمسين ألف سنة، حتى يَحْكُم الله بين الخلق، فيكون من أهل الجنة أم من أهل النار. 

الثاني: مالك الإبل التي لا يُؤدِّي فَرْض زكاتِها وحقِّها، ومنه حَلْبُها لِمَن يَحْضُرُها من المساكين، فيُؤتَى بهذه الإبل عَظَيمةً سمينةً وأكثر ما كانت في عَدَدِها، ويُبسَط ويُلقى ويُمَدّ لها صاحبُها يوم القيامة على أرض واسعة مستوية، تَطَأَه بأرجلها، وتعضُّه بأسنانها، كلّما مَرَّ عليه آخرُها رُدّ عليه أولُها، ويستمر على هذه الحال من العذاب طوال يوم القيامة الذي مقدار يومه خمسين ألف سنة، حتى يحكم الله بين الخلق، فيكون من أهل الجنة أم من أهل النار. 

الثالث: مالك البقر والغنم -من الضّأن والماعِز- التي لا يؤدِّي صاحبها زكاتها المفروضة، فيؤتى بها أَوْفَرَ ما كانت عَدَدًا لا ينقص منها شيء، فيبسط ويُلقى ويُمَدّ لها صاحبها يوم القيامة على أرض واسعة مستوية، ليس فيها مُلْتَوية القَرنين، ولا ما لا قَرْن لها، ولا مكسورة القرن، بل هي على أَكْمَل أوصافِها، فتَنْطَحُه بقرونها، وتطأه بأرجلها، كلما مر عليه آخرها رد عليه أولها، 
ويستمر على هذه الحال من العذاب طوال يوم القيامة الذي مقدار يومه خمسين ألف سنة، حتى يحكم الله بين الخلق، فيكون من أهل الجنة أم من أهل النار. 

الرابع: مقتني الخيل، وهو على ثلاثة أصناف: 

الأول: هي له وِزْر، وهو من اتَّخَذَهَا رياءً وفخرًا وحربًا على أهل الإسلام. 

الثاني: هي له سِتْر، وهو من اتخذها للجهاد في سبيل الله، ثم أحسن إليها فقام بِعَلْفِها وسائر مُؤَنِها، ومنه إِطْراق فَحْلِها. 

الثالث: هي له أَجْر، وهو مَن اتَّخَذَها للجهاد في سبيل الله لأهل الإسلام، وهي في مَرْجٍ ورَوضة للرَّعْي، فما أَكَلت إلا كُتِب له عَدد ما أكلت حسنات، وكتب له عدد أرواثها وأبوالها حسنات، ولا تقطع طولها، وهو الحِبْل الذي تُربَط فيه، وجَرَت ورَكَضَت في العالي من الأرض؛ إلا كُتب الله له عدد آثارها وأرواثها حسنات، ولا مَرّ بها صاحبُها على نهر فشربت منه ولا يريد أن يسقيها، إلا كتب الله له عدد ما شربت حسنات. 

ثم سئل صلى الله عليه وسلم عن الحمير أهي مثل الخيل؟ 

فقال: بأنه لم ينزل فيها تشريع يَخُصُّها إلا هذه الآية القليلة النظير، وهي عامة لجميع الأنواع من طاعة ومعصية؛ وهي قوله تعالى: {فمن يعمل مثقال ذرة خيرًا يره، ومن يعمل مثقال ذرة شرًا يره}. [الزلزلة: 8]، فمن عمل في اقتناء الحمير طاعة رأى ثواب ذلك، وإن عمل معصية رأى عقاب ذلك، وهذا شامل لكل الأعمال.', 'وجوب إيتاء الزكاة، والوعيد الشديد على منعِها.
عدم كفر مانع الزكاة تكاسلًا، لكنه على خطر شديد.
الإنسان يُؤجَر على التفاصيل التي تقع في فعل الطاعة، إذا قصد أصلَها، وإن لم يقصد تلك التفاصيل.
في المال حقٌّ سِوى الزكاة.
من الحق في الإبل حَلْبُها لمن يحضرها من المساكين عند موضع شربها الماء؛ ليكون أسهل على المحتاج من قصد المنازل، وأرفق بالماشية، قال ابن بطال: في المال حَقَّان: فرض عين وغيره، فالحَلْب من الحقوق التي هي من مكارم الأخلاق.
من الحق الواجب في الإبل والبقر والغنم إطراق فحلها إذا طلبت عاريته.
حكم الحُمُر وكل ما لم يرد به نص: أنه داخل في قوله تعالى: (فمن يعمل مِثقال ذرة خيرًا يَره، ومن يعمل مِثقال ذرة شرًا يره).
في الآية الترغيب في فعل الخير ولو قليلًا، والترهيب من فعل الشر ولو حقيرًا.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6611', false),
(21215, 2, 209, 1215, 'hadith', 'عن أبي هريرة رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم : "قال الله عز وجل: كل عمل ابن آدم له إلا الصيام، فإنه لي وأنا أجزي به. والصيام جُنة فإذا كان يوم صوم أحدكم فلا يرفث ولا يصخب، فإن سابه أحد أو قاتله، فليقل: إني صائم. والذي نفس محمد بيده لخُلوف فم الصائم أطيب عند الله من ريح المسك. "للصائم فرحتان يفرحهما: إذا أفطر فرح بفطره، وإذا لقي ربه فرح بصومه" ((متفق عليه)) .((وهذا لفظ رواية البخاري. وفي رواية له: يترك طعامه، وشرابه، وشهوته، من أجلي، الصيام لي وأنا أجزي به، والحسنة بعشر أمثالها. وفي رواية لمسلم: "كل عمل ابن آدم يضاعف: الحسنة بعشر أمثالها إلى سبعمائة ضعف. قال الله تعالى: (إلا الصوم فإنه لي وأنا أجزي به: يدع شهوته وطعامه من أجلي. للصائم فرحتان: فرحة عند فطره، وفرحة عند لقاء ربه. ولخلوف فيه أطيب عند الله من ريح المسك).', 'The Messenger of Allah (ﷺ) said, "Allah the Exalted and Majestic said: ''Every act of the son of Adam is for him, except As-Siyam (the fasting) which is (exclusively) for Me, and I will reward him for it.'' Fasting is a shield. When anyone of you is observing fast, he should neither indulge in obscene language nor should he raise his voice; and if anyone reviles him or tries to quarrel with him, he should say: ''I am fasting.'' By Him in Whose Hand the soul of Muhammad is, the breath of one observing Saum is sweeter to Allah than the fragrance of musk. The one who fasts, experiences two joys: he feels pleasure when he breaks the fast. He is joyful by virtue of his fast when he meets his Rubb.".In a narration by Al-Bukhari, the Messenger of Allah (ﷺ) said, "Allah says: ''(The person observing Saum) has abstained from food and drink, and sexual pleasures for My sake; fasting is for Me, and I will bestow its reward. Every good deed has ten times its reward''."In a narration by Muslim, the Messenger of Allah (ﷺ) said, "The reward of every (good) deed of a person is multiplied from ten to seven hundred times. Allah (SWT) says: ''The reward of observing Saum is different from the reward of other good deeds; Saum is for Me, and I Alone will give its reward. The person observing Saum abstains from food and drink only for My sake.'' The fasting person has two joyous occasions, one at the time of breaking his fast, and the other at the time of meeting his Rubb. Surely, the breath of one observing Saum is better smelling to Allah than the fragrance of musk."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1215', 'Riyad as-Salihin 1215', 'ریاض الصالحین 1215', null, 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنَّ الله تعالى يقول في الحديث القدسي: 

كل عمل ابن آدم يُضاعَف الحسنةُ بعشرِ أمثالها إلى سبعمائة ضعف، إلا الصيام؛ فإنه لي حيث لا يقع فيه الرياء، وأنا أجزي به فأَنْفَرِد بِعلِم مِقدار ثوابه وتضعيف حسناته. 

ثم قال: (والصيام جُنّة) ووقاية وسِتْر وحِصْن حَصِيْن مِن النار؛ لأنه إمساك عن الشهوات والوقوع بالآثام، والنارُ مَحْفُوفة بالشهوات. 

(فإذا كان يوم صوم أحدكم فلا يرفث) بالجماع ومُقَدِّماته، ولا بالكلام الفاحش مطلقًا. 

(ولا يَصخب) بالخِصَام والصِّياح. 

(فإنْ سابّه أحد أو قاتله) في رمضان فليقل: إني امرؤٌ صائم؛ لعله يكف عنه، فإنْ أصرَّ إلا المقاتلة حقيقة دَفَعَهُ بالأخفِّ فالأخف كالصَّائل. 

ثم حَلَف صلى الله عليه وسلم وأقسم بالذي نفسه بيده أنَّ تَغَيُّرَ رائحةِ فمِ الصائم بسبب الصيام أطيبُ عند الله يوم القيامة من ريح المِسْك عندكم، وأكثر ثوابًا من المسك المندوب إليه في الجُمَع ومجالس الذكر. 

وللصائم فرحتان يفرحهما: إذا أفطر فَرِح بفطره بزوال جوعه وعطشه حيث أُبِيْحَ له الفطر، وفَرِحَ بتمام صومه وخاتمة عبادته، وتخفيف من ربه، ومعونة على مستقبل صومه. 

(وإذا لقي ربه فرح بصومه) بجزائه وثوابه.', 'فضل الصيام وأنه يحفظ صاحبَه في الدنيا من الشهوات، وفي الآخرة من عذاب النار.
من آداب الصوم ترك الكلام الفاحش واللَّغَط، والصبر على أذَى الناس ومقابلة إساءتهم بالصبر والإحسان.
الصائم أو العابد إذا فَرِح بسبب إكمال عبادته والانتهاء منها لم ينقص ذلك من أجره في الآخرة.
الفرحة الكاملة هي بلقاء الله تعالى، عندما يُوَفَّى الصابرون والصائمون أجرهم بغير حساب.
إعلام الناس بالطاعة عند الحاجة والمصلحة ليس من الرياء لقوله: (إني صائم).
الصائم الكامل صومه هو الذي صامت جوارحه عن الآثام، ولسانه عن الكذب والفحش، وقول الزور، وبطنه عن الطعام والشراب.
تأكيد النهي عن الصَّخَب والخِصام والصِّياح حالَ الصوم، وإلا فَغَيْرُ الصائم مَنهيٌّ عن ذلك أيضًا.
هذا الحديث مما يرويه النبي صلى الله عليه وسلم عن ربه، ويسمى بالحديث القدسي أو الإلهي، وهو الذي لفظه ومعناه من الله، غير أنه ليست فيه خصائص القرآن التي امتاز بها عما سواه، مِن التَّعَبُّد بتلاوته والطهارة له والتَّحَدِّي والإعجاز وغير ذلك.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3546', false),
(21216, 2, 209, 1216, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال:" من أنفق زوجين في سبيل الله نودي من أبواب الجنة :يا عبد الله هذا خير، فمن كان من أهل الصلاة دعي من باب الصلاة، ومن كان من أهل الجهاد دعي من باب الجهاد، ومن كان من أهل الصيام دعي من باب الريان، ومن كان من أهل الصدقة دعي من باب الصدقة " قال أبو بكر، رضي الله عنه :بأبي أنت وأمي يا رسول الله ما على من دعي من تلك الأبواب من ضرورة، فهل يدعى أحد من تلك الأبواب كلها؟ قال: " نعم وأرجو أن تكون منهم.', 'The Messenger of Allah (ﷺ) said, "He who spends a pair in the way of Allah will be called from the gates of Jannah: ''O slave of Allah! This gate is better for you'' and one who is constant in Salat (prayer), will be called from the Gate of Salat; and whoever is eager in fighting in the Cause of Allah, will be called from the Gate of Jihad; and who is regular in observing Saum will be called from Ar-Raiyan Gate. The one who is generous in charity will be called from the Gate of Charity." Abu Bakr (May Allah be pleased with him) said: "O Messenger of Allah (ﷺ)! May my mother and father be sacrificed for you! Those who are called from these gates will stand in need of nothing. Will anybody be called from all of those gates?" He replied, "Yes, and I hope that you will be one of them.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1216', 'Riyad as-Salihin 1216', 'ریاض الصالحین 1216', 'متفق عليه', 'من تصدق بشيئين من أي شيء مثل المأكولات أو الملبوسات أو المركوبات أو النقود، ابتغاء رضوان الله نادته الملائكة من أبواب الجنَّة مُرَحِّبة بقدومه إليها، وهي تقول: لقد قدمت خيرا ًكثيراً تثاب عليه اليوم ثَوابا ًكبيراً.
فالمكثرون من الصلاة ينادون من باب الصلاة، ويدخلون منه، والمكثرون من الصدقة ينادون من باب الصدقة، ويدخلون منه، والمكثرون من الصوم تستقبلهم الملائكة عند باب الرَّيَّان داعية لهم بالدخول منه، ومعنى الرَّيان: الذي يَروي من العطش؛ لأن الصائمين يمتنعون عن الماء فيصابون بالعطش ولاسيما في أيام الصيف الطويلة الحارة، فيجازون على عطشهم بالري الدائم في الجنة التي يدخلون إليها من ذلك الباب.
فلما سمع أبو بكر رضي الله عنه هذا الحديث، قال: يا رسول الله: "بأبي أنت وأمي" من دخل من هذه الأبواب لا نقص عليه ولا خسارة، ثم قال: "فهل يُدْعى أحدٌ من تلك الأبواب كلها"، فقال صلى الله عليه وسلم : "نعم وأرجو أن تكون منهم".', 'بيان فضل أبي بكر الصديق -رضي الله عنه-، وأنه تجتمع له أعمال البر، فيدعى من جميع أبواب الجنة تكريمًا له.
جواز الثناء على الإنسان في وجهه، إذا لم يَخَفْ عليه العُجب.
بيان أن للجنة أبواباً تقوم عليها الملائكة.
من العباد من يُدعى من كل هذه الأبواب.
جواز فِدَاء النبي -صلى الله عليه وسلم- بالأب والأم.', 'أنْفَق زوْجَيْن : أي: أنفق شيئين من أي صنف من أصناف المال من نوع واحد.
الرَّيَّانِ : اسم باب من أبواب الجنَّة، خُصَّ الصائمون بالدخول منه.
ضَرورة : نقص خسارة.
أرْجُو أن تكون منهم : أتوقع أن تكون منهم، قال العلماء: الرجاء من الله ومن نبيه -صلى الله عليه وسلم- واقع، وإنما قال النبي -صلى الله عليه وسلم-: "أرْجُو" تأدبًا مع الله -تعالى-.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4187', false),
(21217, 2, 209, 1217, 'hadith', 'عن سهل بن سعد رضي الله عنه عنه عن النبي صلى الله عليه وسلم قال: «إن في الجنة بابًا يقال له: الريان، يدخل منه الصائمون يوم القيامة لا يدخل منه أحد غيرهم يقال: أين الصائمون؟ فيقومون لا يدخل منه أحد غيرهم، فإذا دخلوا أغلق فلم يدخل منه أحد».', 'The Prophet (ﷺ) said, "In Jannah there is a gate which is called Ar-Raiyan through which only those who observe Saum (fasting) will enter on the Day of Resurrection. None else will enter through it. It will be called out, "Where are those who observe fasting?" So they will stand up and proceed towards it. When the last of them will have entered, the gate will be closed and then no one will enter through that gate.".', 'سهل بن سعد رضي الله عنه', 'Sahl bin Sa''d (May Allah be pleased with him):', 'صحيح', 'رياض الصالحين 1217', 'Riyad as-Salihin 1217', 'ریاض الصالحین 1217', 'متفق عليه', 'أخبر النبي صلى الله عليه وسلم أن بابًا من أبواب الجنة يسمى: ‌باب ‌الريان، يدخل منه الصائمون يوم القيامة، لا يدخل منه أحد غيرهم، ينادى: أين الصائمون، فيقومون ويدخلون، لا يدخل منه أحد غيرهم، فإذا دخل آخرهم أغلق، فلم يدخل منه أحد بعد.', 'قال النووي: في هذا الحديث فضيلة الصيام وكرامة الصائمين.
أفرد الله للصائمين بابًا من أبواب الجنة الثمانية، إذا دخلوه أغلق.
بيان أن للجنة أبوابًا.
قال السندي: قوله: (أين الصائمون)، أي المكثرون الصيام كالعادل والظالم، يقال لمن يعتاد ذلك، لا لمن يفعل ذلك مرة.
(الريان) يعني الذي يروي؛ لأن الصائمين يعطشون ولاسيما في أيام الصيف الطويلة الحارة؛ فيجازون بتسمية هذا الباب بما يختص بهم، باب الريان، وقيل الريان فعلان كثير الري ضد العطش، سمى به؛ لأنه جزاء الصائمين على عطشهم وجوعهم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3738', false),
(21218, 2, 209, 1218, 'hadith', 'عن أبي سعيد الخدري، رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم « ما من عبد يصوم يومًا في سبيل الله إلا باعد الله بذلك اليوم وجهه عن النار سبعين خريفًا».', 'The Messenger of Allah (ﷺ) said, "Every slave of Allah who observes Saum (fasting) for one day for the sake of Allah, Allah will draw his face farther from Hell-fire to the extent of a distance to be covered in seventy years.".', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1218', 'Riyad as-Salihin 1218', 'ریاض الصالحین 1218', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21219, 2, 209, 1219, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: من صام رمضان إيمانًا واحتسابًا، غفر له ما تقدم من ذنبه ".', 'The Prophet (ﷺ) said, "He who observes fasting during the month of Ramadan with Faith while seeking its reward from Allah, will have his past sins forgiven.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1219', 'Riyad as-Salihin 1219', 'ریاض الصالحین 1219', 'متفق عليه', 'يُخبِرُ النبيُّ صلى الله عليه وسلم أنَّ مَن صام شهر رمضان إيمانًا بالله، وتصديقًا بفَرْضِيَّةِ الصيام وما أعدَّ الله تعالى للصائمين مِن جَزيل الأجور والثواب، قاصدًا به وجهَ الله تعالى لا رياء ولا سُمْعَة، غُفرتْ له ذنوبُه الماضية.', 'فضل الإخلاص وأهميته في صيام رمضان وغيره من الأعمال الصالحة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4196', false),
(21220, 2, 209, 1220, 'hadith', 'وعنه رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إذا جاء رمضان فتحت أبواب الجنة، وغلقت أبواب النار، وصفدت الشياطين».', 'The Messenger of Allah (ﷺ) said, "When Ramadan begins, the gates of Jannah are opened, the gates of Hell are closed, and the devils are chained.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1220', 'Riyad as-Salihin 1220', 'ریاض الصالحین 1220', 'متفق عليه', 'أخبرَ النبيُّ صلى الله عليه وسلم أنه إذا دخل شهر رمضان حصلت ثلاثة أمور: 

الأول: تفتح أبواب الجنة فلم يغلق منها باب. 

الثاني: تغلق أبواب النيران فلم يفتح منها باب.  

الثالث: تشد الشياطين ومردة الجن بالسلاسل، فلا يخلصون إلى ما كانوا يخلصون إليه في غير رمضان.

وكل ذلك تعظيم لهذا الشهر، وترغيب للعاملين بكثرة الطاعات من صلاة وصدقة وذكر وقراءة للقرآن وغير ذلك؛ وبالابتعاد عن الذنوب والمعاصي.', 'فضل شهر رمضان.
بشارة للصائمين فيه بأن هذا الشهر المبارك موسم عبادة وخير.
في تصفيد الشياطين في رمضان إشارة إلى رفع عذر المكلف وكأنه يقال له: قد كُفّت الشياطين عنك فلا تعتذر بهم في ترك الطاعة ولا في فعل المعصية.
قال القرطبي: فإن قيل: كيف نرى الشرور والمعاصي واقعة في رمضان كثيرًا فلو صفدت الشياطين لم يقع ذلك؟ فالجواب: أنها إنما تقل عن الصائمين الصوم الذي حوفظ على شروطه وروعيت آدابه، أو المصفد بعض الشياطين وهم المردة لا كلهم كما تقدم في بعض الروايات، أو المقصود تقليل الشرور فيه، وهذا أمر محسوس، فإن وقوع ذلك فيه أقل من غيره، إذ لا يلزم من تصفيد جميعهم أن لا يقع شر ولا معصية؛ لأن لذلك أسبابًا غير الشياطين كالنفوس الخبيثة والعادات القبيحة والشياطين الإنسية.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10107', false),
(21221, 2, 209, 1221, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال: "صوموا لرؤيته، وأفطروا لرؤيته، فإن غَبِيَ عليكم فأكملوا عدة شعبان ثلاثين" ((متفق عليه وهذا لفظ البخاري)). وفي رواية مسلم: "فإن غم عليكم فصوموا ثلاثين يومًا".', 'The Messenger of Allah (ﷺ) said, "Observe Saum (fast) on sighting the crescent and terminate it on sighting it (the new moon), but if the sky is cloudy before you, then complete the number (thirty days) of the month.".', null, 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 1221', 'Riyad as-Salihin 1221', 'ریاض الصالحین 1221', null, null, null, null, 'sunnah.com', null, false, null, false),
(21222, 2, 209, 1222, 'hadith', 'عن ابن عباس رضي الله عنهما: قال: كان رسول الله صلى الله عليه وسلم أجود الناس، وكان أجود ما يكون في رمضان حين يلقاه جبريل وكان جبريل يلقاه في كل ليلة من رمضان فيدارسه القرآن فَلَرَسول الله صلى الله عليه وسلم حين يلقاه جبريل أجود بالخير من الريح المرسلة".', 'The Messenger of Allah (ﷺ) was the most generous of the men; and he was the most generous during the month of Ramadan when Jibril visited him every night and recited the Qur''an to him. During this period, the generosity of Messenger of Allah (ﷺ) waxed faster than the rain bearing wind..', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1222', 'Riyad as-Salihin 1222', 'ریاض الصالحین 1222', 'متفق عليه', 'كَانَ النبيُّ صلى الله عليه وسلم أعظم الناس كَرمًا، وكان يَكثر كرمُه في شهر رمضان حيث كان يُعطي ما ينبغي لمَن ينبغي، والسبب في زيادة كرمه أمران: 

الأول: الْتِقاؤه بجبريل عليه السلام.

والأمر الآخر: مدارسة القرآن، وهو القراءة عن ظهر قلب.

فيدارسه جبريل عليه السلام جميع ما نزل من القرآن، ولَرَسُول الله صلى الله عليه وسلم أكرم وأكثر عطاءً وفعلًا للخير، وأسرع نفعًا للخلق من الريح الطيبة التي يرسلها الله بالغيث والرحمة.', 'بيان جُود النبي صلى الله عليه وسلم وسَعَة كرمه وخاصة في رمضان، فإنه شهر الطاعات ومواسم الخيرات.
الحث على الجود في كل وقت، وتستحب الزيادة في شهر رمضان.
الإكثار من البذل والعطاء والإحسان وقراءة القرآن في شهر رمضان.
من أسباب حفظ العلم مدارسته مع طلاب العلم والعلماء.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6179', false),
(21223, 2, 209, 1223, 'hadith', 'عن عائشة رضي الله عنها قالت: كان رسول الله صلى الله عليه وسلم إذا دخل العشر أحيا الليل وأيقظ أهله، وشد المئزر".', 'When the last ten nights (of Ramadan) would begin, the Messenger of Allah (ﷺ) would keep awake at night (for prayer and devotion), awaken his family and prepare himself to be more diligent in worship..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1223', 'Riyad as-Salihin 1223', 'ریاض الصالحین 1223', 'متفق عليه', 'كَانَ النبيُّ صلى الله عليه وسلم إذا دخل العشر الأواخر من رمضان أحيا الليل كلَّه بأنواع الطاعات، وأيقظ أهلَه للصلاة، واجتهد في العبادة زيادة على عادته، وتَفَرَّغ لها واعتزل نساءه.', 'الترغيب باغتنام الأوقات الفاضلة بالأعمال الصالحة.
قال النووي: ففي هذا الحديث: أنه يستحب أنْ يُزاد من العبادات في العشر الأواخر من رمضان، واستحباب إحياء لياليه بالعبادات.
ينبغي على العبد أن يكون حريصًا على أهلِه بأمرِهم بالعبادة، ويَصْطَبِر عليهم.
فعل الخيرات يحتاج إلى حَزْم وصبر ومصابرة.
قال النووي: اختلف العلماء في معنى (شدّ المِئزر) فقيل: هو الاجتهاد في العبادات زيادة على عادته صلى الله عليه وسلم في غيره، ومعناه: التشمير في العبادات، يقال: شَدَدْتُ لهذا الأمر مِئزري، أي: تَشَمَّرتُ له وتَفَرّغت، وقيل: هو كناية عن اعتزال النساء للاشتغال بالعبادات.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4944', false),
(21224, 2, 209, 1224, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «لا يتقدمن أحدكم رمضان بصوم يوم أو يومين، إلا أن يكون رجل كان يصوم صومه، فليصم ذلك اليوم».', 'The Prophet (ﷺ) said, "Do not observe Saum (fasting) for a day or two days preceding Ramadan. However, if a person is in the habit of observing Saum on a particular day (which may fall on these dates), he may fast on that day.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1224', 'Riyad as-Salihin 1224', 'ریاض الصالحین 1224', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21225, 2, 209, 1225, 'hadith', 'عن ابن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم « لا تصوموا قبل رمضان صوموا لرؤيته وأفطروا لرؤيته، فإن حالت دونه فأكملوا ثلاثين يومًا» ((رواه الترمذي وقال حديث حسن صحيح.', 'The Messenger of Allah (ﷺ) said, "Do not observe Saum (fasting) before the advent of Ramadan. Observe Saum at sighting of the crescent of Ramadan and terminate it at sighting the crescent (of Shawwal). If the sky is overcast, complete (the month as) thirty (days).".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', null, 'رياض الصالحين 1225', 'Riyad as-Salihin 1225', 'ریاض الصالحین 1225', null, null, null, null, 'sunnah.com', null, false, null, false),
(21226, 2, 209, 1226, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم «إذا بقي نصف من شعبان فلا تصوموا».', 'The Messenger of Allah (ﷺ) said, "When there comes the middle of Sha''ban, don''t observe Saum (fasting).".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1226', 'Riyad as-Salihin 1226', 'ریاض الصالحین 1226', 'رواه الترمذي وقال حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21227, 2, 209, 1227, 'hadith', 'عن أبي اليقظان عمار بن ياسر، رضي الله عنهما قال: «من صام اليوم الذي يشك فيه فقد عصي أبا القاسم، صلى الله عليه وسلم».', 'He who observes the fast on a doubtful day, has in fact disobeyed Abul-Qasim, (i.e., Messenger of Allah (ﷺ))..', 'أبي اليقظان عمار بن ياسر رضي الله عنهما', '''Ammar bin Yasir (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1227', 'Riyad as-Salihin 1227', 'ریاض الصالحین 1227', 'رواه أبو داود والترمذي وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21228, 2, 209, 1228, 'hadith', 'عن طلحة بن عبيد الله رضي الله عنه أن النبي صلى الله عليه وسلم كان إذا رأى الهلال قال: «اللهم أهله علينا بالأمن والإيمان والسلامة والإسلام، ربي وربك الله، هلال رشد وخير».', 'At the sight of the new moon (of the lunar month), the Prophet (ﷺ) used to supplicate: "Allahumma ahillahu ''alaina bil-amni wal-iman, was-salamati wal-Islam, Rabbi wa Rabbuk-Allah, Hilalu rushdin wa khairin (O Allah, let this moon appear on us with security and Iman; with safety and Islam. (O moon!) Your Rubb and mine is Allah. May this moon be bringing guidance and good).".', 'طلحة بن عبيد الله رضي الله عنه', 'Talhah bin Ubaidullah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1228', 'Riyad as-Salihin 1228', 'ریاض الصالحین 1228', 'رواه الترمذي وقال: حديث حسن', 'يخبر طلحة بن عبيدالله رضي الله عنه أن النبي صلى الله عليه وسلم كان إذا رأى الهلال من الليلة الأولى أوالثانية أوالثالثة، قال هذا الدعاء الجليل، الذي يشتمل على سؤال الله تعالى أن يطلعه بالأمن من المخاوف الدينية والدنيوية، ودوام الإيمان وثباته، ودفع ما يزيغ عنه، كما يشتمل على سؤال الله تعالى السلامة والإسلام، منبِّها بذكر الأمن والسلامة على طلب دفع كل مضرة، وبالإيمان والإسلام على جلب كل منفعة، ثم يختتم هذا الدعاء مخاطبا الهلال بقوله: "ربي وربك الله"، إشارة إلى تنزيه الخالق عن مشاركة غيره له في تدبير خلقه، داعيًا الله تعالى أن يكون هلال هدى وخير.', 'مشروعية هذا الدعاء عند رؤية الهلال.
الأمن والسلامة نعم من الله يجب شكرها، ودعاء الله بأن تبقى وتتجدد.
في هذا الدعاء تنزيه للخالق عن مشارك له في تدبير خلقه، ورد على من عبد غير الله من الشمس والقمر.
تنبيه على أنَّ الدعاء مستحب عند ظهور الآيات وتقلب الحالات، ولكن ليس له أن يلتزم دعاءً لم يدل عليه دليل.', 'أَهِلَّه : أظهره وبيّنه.
هلال رشد : هلال هدى.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6177', false),
(21229, 2, 209, 1229, 'hadith', 'عن أنس، رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «تسحروا فإن في السحور بركة».', 'The Messenger of Allah (ﷺ) said, "Eat Suhur (predawn meal). Surely, there is a blessing in Suhur.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1229', 'Riyad as-Salihin 1229', 'ریاض الصالحین 1229', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21230, 2, 209, 1230, 'hadith', 'عن زيد بن ثابت رضي الله عنه قال: تسحرنا مع رسول الله صلى الله عليه وسلم ثم قمنا إلى الصلاة قيل كم كان بينهما؟ قال: خمسون آية.', 'We took Suhur (predawn meal) with the Messenger of Allah (ﷺ) and then we stood up for (Fajr) Salat (prayer). It was asked: "How long was the gap between the two?" He replied: "The time required for the recitation of fifty Ayat.".', 'زيد بن ثابت رضي الله عنه', 'Zaid bin Thabit (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1230', 'Riyad as-Salihin 1230', 'ریاض الصالحین 1230', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21231, 2, 209, 1231, 'hadith', 'عن ابن عمر رضي الله عنهما قال: كان لرسول الله صلى الله عليه وسلم مؤذنان: بلال وابن أم مكتوم. فقال رسول الله صلى الله عليه وسلم « إن بلالا يؤذن بليل فكلوا واشربوا حتى يؤذن ابن أم مكتوم» قال ولم يكن بينهما إلا أن ينزل هذا ويرقى هذا.', 'The Messenger of Allah (ﷺ) had two Mu''adhdhin: Bilal and Ibn Umm Maktum (May Allah be pleased with them). The Messenger of Allah (ﷺ) said, "Bilal proclaims Adhan .', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1231', 'Riyad as-Salihin 1231', 'ریاض الصالحین 1231', 'متفق عليه', 'ذكر ابن عمر رضي الله عنه أنه كان لرسول الله صلى الله عليه وسلم مؤذنان في مسجده في المدينة في وقت واحد، وإلا فقد كان له غيرهما؛ أذن له أبو محذورة بمكة، ورتَّبه لأذانها، وسعد القَرَظ أذن للنبي صلى الله عليه وسلم بقباء، والمؤذنان هما بلال بن رباح وابن أم مكتوم رضي الله عنهما، والأعمى نعت له.', 'استحباب اتخاذ مؤذنين للمسجد الواحد.

استحباب أن يؤذن أحدهما قبل طلوع الفجر، والآخر عند طلوعه، كما كان بلال وابن أم مكتوم رضي الله عنهما يفعلان ذلك.

استحباب أذان واحد بعد واحد، أي كما كان يفعله مؤذنا رسول الله صلى الله عليه وسلم.

جواز كون الأعمى مؤذنًا، إذا كان معه بصير يرشده للأوقات.

جواز وصف الإنسان بعيب فيه إذا كان للتعريف أو مصلحة تترتب عليه، لا على قصد التنقيص.


جواز شهادة الأعمى.

جواز العمل بخبر الواحد.

جواز الاعتماد على الصوت دون الرؤية إذا كان عارفا به.

جواز نسبة الرجل إلى أمه إذا اشتهر بذلك، واحتيج إليه.', '--', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65388', false),
(21232, 2, 209, 1232, 'hadith', 'عن عمرو بن العاص رضي الله عنه أن رسول الله قال: "فصل ما بين صيامنا وصيام أهل الكتاب أكلة السحر.', 'The Messenger of Allah (ﷺ) said, "The difference between our observance of Saum (fasting) and that of the people of the Scriptures is Suhur (predawn meal in Ramadan).".', 'عمرو بن العاص رضي الله عنه', '''Amr bin Al-''As (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1232', 'Riyad as-Salihin 1232', 'ریاض الصالحین 1232', 'رواه مسلم', 'يخبر النبي -عليه الصلاة والسلام- في هذا الحديث عن الفارق المميز بين صيامنا وصيام اليهود والنصارى، وهو الطعام الذي يأكله المسلمون وقت السحور، لأنَّ أهل الكتاب لا يتسحرون، والمسلمون يستحب لهم السحور؛ مخالفة لأهل الكتاب وتحقيقاً للسنة وفيه بركة وخير كما ثبت في السنة، وأهل الكتاب يصومون من نصف الليل، فيأكلون قبل منتصف الليل ولا يأكلون في السحر، والتمييز بين المسلمين والكفار أمر مطلوب في الشرع.', 'السحور من خصائص الأمة الإسلامية، والله تفضل به وبغيره من الرخص رأفة ورحمة بها.
مخالفة أهل الكتاب مقصد من مقاصد الشرع، وهدف من أهداف البعثة النبوية تمييزاً لهذه الأمة الإسلامية.', 'فصل : فاصل وفارق.
أهل الكتاب : اليهود والنصارى.
أكلة السحر : السحور، وأكلة بفتح الهمزة، عبارة عن المرة الواحدة من الأكل كغدوة، والمراد هنا الطعام الذي يؤكل وقت السُّحور.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6105', false),
(21233, 2, 209, 1233, 'hadith', 'عن سهل بن سعد رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لا يزال الناس بخير ما عجلوا الفطر».', 'The Messenger of Allah (ﷺ) said, "People will continue to adhere to good as long as they hasten to break the Saum (fasting).".', 'سهل بن سعد رضي الله عنه', 'Sahl bin Sa''d (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1233', 'Riyad as-Salihin 1233', 'ریاض الصالحین 1233', 'متفق عليه', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنه لا يزال الناس بخير ما عَجَّلوا الفطر في الصيام بعد التَّحَقُّق من غروب الشمس؛ وذلك امتثالًا للسُّنَّة، والوقوف عند حدِّها.', 'قال النووي: فيه الحث على تعجيله بعد تحقُّق غروب الشمس، ومعناه لا يزال أَمْرُ الأمة مُنتظمًا وهم بخير ما داموا محافظين على هذه السنة، وإذا أخّروه كان ذلك علامة على فسادٍ يَقَعون فيه.
بقاء الخير في الناس بسبب اتباعهم للسنة، وفساد الأمور يتعلق بتغيُّر السنة.
مخالفة أهل الكتاب وأهل البدع، فإنهم يؤخِّرون الإفطار.
قال ابن حجر: وفيه بيان العلة في ذلك، قال المُهَلّب: والحكمة في ذلك أن لا يُزاد في النهار من الليل، ولأنه أرفق بالصائم وأقوى له على العبادة، واتفق العلماء على أنّ مَحَلّ ذلك إذا تحقق غروب الشمس بالرؤية أو بإخبار عَدْلَين، وكذا عدل واحد في الأرجح.
قال ابن حجر: تنبيه: من البدع المنكرة ما أُحْدِث في هذا الزمان من إيقاع الأذان الثاني قبل الفجر بنحو ثلث ساعة في رمضان، وإطفاء المصابيح التي جعلت علامة لتحريم الأكل والشرب على من يريد الصيام زعمًا ممن أحدثه أنه للاحتياط في العبادة، ولا يعلم بذلك إلا آحاد الناس، وقد جَرَّهم ذلك إلى أن صاروا لا يؤذِّنون إلا بعد الغروب بدرجة لتمكين الوقت زعموا، فأخروا الفطر، وعجلوا السحور، وخالفوا السنة، فلذلك قَلَّ عنهم الخير وكثر فيهم الشر، والله المستعان.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4438', false),
(21234, 2, 209, 1234, 'hadith', 'عن أبي عطية قال: دخلت أنا ومسروق على عائشة رضي الله عنها فقال لها مسروق: رجلان من أصحاب محمد صلى الله عليه وسلم كلاهما لا يألو عن الخير: أحدهما يعجل المغرب والإفطار، والآخر يؤخر المغرب والإفطار؟ فقالت: من يعجل المغرب والإفطار؟ قال: عبد الله - يعني ابن مسعود- فقالت: هكذا كان رسول الله صلى الله عليه وسلم يصنع".', 'Masruq and I visited ''Aishah (May Allah be pleased with her) and said: "O Mother of the Believers! There are two Companions of Muhammad (ﷺ) and neither of them holds back from doing good acts; but one of them hastens to break Saum (fasting) and hastens to perform the Maghrib prayer, while the other delays breaking Saum and delays performing Salat (prayer)." She asked, "Who is the one who hastens to break Saum and perform the Maghrib prayer?" Masruq said, "It is ''Abdullah (meaning ''Abdullah bin Mas''ud)." She said, "The Messenger of Allah (ﷺ) used to do so.".', 'أبي عطية قال: دخلت أنا ومسروق على عائشة رضي الله عنها', 'Abu Atiyyah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1234', 'Riyad as-Salihin 1234', 'ریاض الصالحین 1234', 'رواه مسلم', 'سأل أبو عطية ومسروق أم المؤمنين عائشة رضي الله عنها عن رجلين من أصحاب رسول الله صلى الله عليه وسلم أحدهما: يؤخر الفطر ويؤخر صلاة المغرب، والثاني: يعجل الفطر ويعجل صلاة المغرب، أيهما أصوب؟ فقالت عائشة: من هذا؟ أي: الذي يعجل؟ قالوا: ابن مسعود رضي الله عنه ، فقالت: هكذا كان النبي صلى الله عليه وسلم يفعل، يعني: يعجل الفطر ويعجل صلاة المغرب، فهذه سنة فعلية منه –صلى الله عليه وسلم- تدل على أن الأفضل تقديم الإفطار.', 'استحباب تعجيل صلاة المغرب والفطور، إذا تحقق غروب الشمس.
حرص الصحابة على الخير، وتسابقهم في أعمال البر والتقوى.
منقبة لعبد الله بن مسعود -رضي الله عنه- وتحريه لموافقة السنة.
الخير المعتبر شرعاً هو موافقة السنة.
قد تخفى السنة على آحاد الصحابة -رضي الله عنهم-.
استحباب سؤال أهل العلم عند الاختلاف.
من الآداب توقير الصحابة -رضي الله عنهم- وهذا ظاهر في قول التابعي: كلاهما لا يألو عن الخير.', 'لا يألو : لاَ يُقَصِّرُ في الخَيْرِ.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6013', false),
(21235, 2, 209, 1235, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم قال الله عز وجل: «أحب عبادي إلي أعجلهم فطرًا».', 'The Messenger of Allah (ﷺ) said, "Allah the Most High says: ''From amongst my slaves, the quicker the one is in breaking the Saum (fasting), the dearer is he to me."''.', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1235', 'Riyad as-Salihin 1235', 'ریاض الصالحین 1235', 'رواه الترمذي وقال حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21236, 2, 209, 1236, 'hadith', 'عن عمر بن الخطاب، رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إذا أقبل الليل من ههنا وأدبر النهار من ههنا، وغربت الشمس، فقد أفطر الصائم».', 'The Messenger of Allah (ﷺ) said: "When the night approaches from this side (i.e., the east) and the day retreats from that side (i.e., west) and the sun sets, then it is time for a person observing Saum (fasting) to break his fast.".', 'عمر بن الخطاب رضي الله عنه', '''Umar bin Al-Khattab (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1236', 'Riyad as-Salihin 1236', 'ریاض الصالحین 1236', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21237, 2, 209, 1237, 'hadith', 'عن أبي إبراهيم عبد الله بن أبي أوفى، رضي الله عنهما قال: سرنا مع رسول الله صلى الله عليه وسلم وهو صائم فلما غربت الشمس قال لبعض القوم: "يا فلان انزل فاجدح لنا، فقال: يا رسول الله لو أمسيت؟ قال: "انزل فاجدح لنا" قال: إن عليك نهارًا، قال: "انزل فاجدح لنا" قال: فنزل فجدح لهم فشرب رسول الله صلى الله عليه وسلم ثم قال: "إذا رأيتم الليل قد أقبل من ههنا، فقد أفطر الصائم" وأشار بيده قبل المشرق.', 'We were with the Messenger of Allah (ﷺ) on a journey and he was observing Saum (fasting). When the sun set, he (ﷺ) said to a person, "Dismount and prepare the ground roasted barley drink for us." Upon this he replied, "O Messenger of Allah, there is daylight still." The Messenger of Allah (ﷺ) said, "Get down and prepare barley drink for us." He said, "But it is still daytime." The Messenger of Allah (ﷺ) again said to him, "Get down and prepare barely drink for us." So he got down and prepared a barley liquid meal for him. The Prophet (ﷺ) drank that and then said, "When you perceive the night approaching from that side, a person observing Saum (fasting) should break the fast." And he (ﷺ) pointed towards the east with his hand..', 'أبي إبراهيم عبد الله بن أبي أوفى رضي الله عنهما', 'Abu Ibrahim ''Abdullah bin Abu Aufa (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1237', 'Riyad as-Salihin 1237', 'ریاض الصالحین 1237', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21238, 2, 209, 1238, 'hadith', 'عن سلمان بن عامر الضبي الصحابي، رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إذا أفطر أحدكم، فليفطر على تمر فإن لم يجد فليفطر على ماء فإنه طهور».', 'I heard the Prophet (ﷺ) saying, "When one of you breaks his Saum (fasting), let him break it on dates; if he does not have any, break his fast with water for it is pure.".', 'سلمان بن عامر الضبي الصحابي رضي الله عنه', 'Salman bin ''Amir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1238', 'Riyad as-Salihin 1238', 'ریاض الصالحین 1238', 'رواه أبو داود، والترمذي وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21239, 2, 209, 1239, 'hadith', 'عن أنس رضي الله عنه قال كان رسول الله صلى الله عليه وسلم يفطر قبل أن يصلي على رطبات، فإن لم تكن رطبات فتميرات فإن لم تكن تميرات حسا حسوات من ماء.', 'The Messenger of Allah (ﷺ) used to break his Saum (fasting) before performing Maghrib prayer with three fresh date-fruits; if there were no fresh date- fruits, he will eat three dry dates; and if there were no dry date- fruits; he would take three draughts of water..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1239', 'Riyad as-Salihin 1239', 'ریاض الصالحین 1239', 'رواه أبو داود والترمذي وقال: حديث حسن', 'يخبر أنس رضي الله عنه في هذا الحديث أن رسول الله صلى الله عليه وسلم كان يفطر -إذا كان صائماً-، على رطبات قبل أن يصلي المغرب، فإن لم يجد رطبات، فإنه يفطر على تمرات، فإن لم تكن عنده تمرات، شرب شربات من ماء، وبدايته -عليه الصلاة والسلام- بالتمر أو الماء مناسب لأن الصائم تكون معدته خالية فلا يبدأ بالطعام الدسم لئلا يتضرر.', 'يستحب للصائم أن يفطر على رطبات وتراً، فإن لم يجد فعلى تمرات، فإن لم يجد فعلى الماء، مع مراعاة الترتيب.
التزام سنة النبي -صلى الله عليه وسلم- فيه الخير الكثير، وقد ثبتت الحكمة من الإفطار على الرطب والتمر، فمن ذلك أنه يزيل فضلات المعدة، كما أن فيه كل العناصر الغذائية التي يحتاجها الجسم.', 'رطبات : الرطب هو ثمر النخل إذا أدرك ونضج قبل أن يصير تمرا.
فتميرات : بالتصغير، والتمر: البلح اليابس.
حسا : شرب بتمهل.
حسوات : جمع حَسوة، وهي المرة من الشرب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6185', false),
(21240, 2, 209, 1240, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إذا كان يوم صوم أحدكم فلا يرفث ولا يصخب، فإن سابه أحد أو قاتله، فليقل: إني صائم»', 'The Messenger of Allah (ﷺ) said, "When any one of you is observing Saum (fasting) on a day, he should neither indulge in obscene language nor should he raise the voice; and if anyone reviles him or tries to quarrel with him he should say: ''I am observing fast."''.', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1240', 'Riyad as-Salihin 1240', 'ریاض الصالحین 1240', null, 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنَّ الله تعالى يقول في الحديث القدسي: 

كل عمل ابن آدم يُضاعَف الحسنةُ بعشرِ أمثالها إلى سبعمائة ضعف، إلا الصيام؛ فإنه لي حيث لا يقع فيه الرياء، وأنا أجزي به فأَنْفَرِد بِعلِم مِقدار ثوابه وتضعيف حسناته. 

ثم قال: (والصيام جُنّة) ووقاية وسِتْر وحِصْن حَصِيْن مِن النار؛ لأنه إمساك عن الشهوات والوقوع بالآثام، والنارُ مَحْفُوفة بالشهوات. 

(فإذا كان يوم صوم أحدكم فلا يرفث) بالجماع ومُقَدِّماته، ولا بالكلام الفاحش مطلقًا. 

(ولا يَصخب) بالخِصَام والصِّياح. 

(فإنْ سابّه أحد أو قاتله) في رمضان فليقل: إني امرؤٌ صائم؛ لعله يكف عنه، فإنْ أصرَّ إلا المقاتلة حقيقة دَفَعَهُ بالأخفِّ فالأخف كالصَّائل. 

ثم حَلَف صلى الله عليه وسلم وأقسم بالذي نفسه بيده أنَّ تَغَيُّرَ رائحةِ فمِ الصائم بسبب الصيام أطيبُ عند الله يوم القيامة من ريح المِسْك عندكم، وأكثر ثوابًا من المسك المندوب إليه في الجُمَع ومجالس الذكر. 

وللصائم فرحتان يفرحهما: إذا أفطر فَرِح بفطره بزوال جوعه وعطشه حيث أُبِيْحَ له الفطر، وفَرِحَ بتمام صومه وخاتمة عبادته، وتخفيف من ربه، ومعونة على مستقبل صومه. 

(وإذا لقي ربه فرح بصومه) بجزائه وثوابه.', 'فضل الصيام وأنه يحفظ صاحبَه في الدنيا من الشهوات، وفي الآخرة من عذاب النار.
من آداب الصوم ترك الكلام الفاحش واللَّغَط، والصبر على أذَى الناس ومقابلة إساءتهم بالصبر والإحسان.
الصائم أو العابد إذا فَرِح بسبب إكمال عبادته والانتهاء منها لم ينقص ذلك من أجره في الآخرة.
الفرحة الكاملة هي بلقاء الله تعالى، عندما يُوَفَّى الصابرون والصائمون أجرهم بغير حساب.
إعلام الناس بالطاعة عند الحاجة والمصلحة ليس من الرياء لقوله: (إني صائم).
الصائم الكامل صومه هو الذي صامت جوارحه عن الآثام، ولسانه عن الكذب والفحش، وقول الزور، وبطنه عن الطعام والشراب.
تأكيد النهي عن الصَّخَب والخِصام والصِّياح حالَ الصوم، وإلا فَغَيْرُ الصائم مَنهيٌّ عن ذلك أيضًا.
هذا الحديث مما يرويه النبي صلى الله عليه وسلم عن ربه، ويسمى بالحديث القدسي أو الإلهي، وهو الذي لفظه ومعناه من الله، غير أنه ليست فيه خصائص القرآن التي امتاز بها عما سواه، مِن التَّعَبُّد بتلاوته والطهارة له والتَّحَدِّي والإعجاز وغير ذلك.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3546', false)
