insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21321, 2, 212, 1321, 'hadith', 'عن سهل بن حنيف رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «من سأل الله تعالى الشهادة بصدق بلغه الله منازل الشهداء وإن مات على فراشه».', 'The Messenger of Allah (ﷺ) said, "He who supplicates Allah sincerely for martyrdom, Allah will elevate him to the station of the martyrs, even if he dies on his bed.".', 'سهل بن حنيف رضي الله عنه', 'Sahl bin Hunaif (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1321', 'Riyad as-Salihin 1321', 'ریاض الصالحین 1321', 'رواه مسلم', 'يُخْبِرُ النبيُّ صلى الله عليه وسلم أنَّ مَن طَلَبَ الشهادةَ والقتلَ في سبيل الله، وكان صادقًا مخلصًا في نيته تلك لله عز وجل، أعطاه الله درجات الشهداء بنيته الصادقة وإن مات على الفِراش في غير الجهاد.', 'صدق النية مع فعل المستطاع سبب لبلوغ المقصود من الأجر والثواب، وإن لم يُبَاشر العمل المطلوب.
الترغيب في الجهاد وطلب الشهادة في سبيل الله عز وجل.
إكرام الله تعالى لهذه الأمة، فهو يعطيها بقليل من العمل أعلى الدرجات في الجنة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3157', false),
(21322, 2, 212, 1322, 'hadith', 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «من طلب الشهادة صادقًا أعطيها ولو لم تصبه».', 'The Messenger of Allah (ﷺ) said, "He who supplicates sincerely for martyrdom, it will be granted to him even though he is not killed on the battlefield.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1322', 'Riyad as-Salihin 1322', 'ریاض الصالحین 1322', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21323, 2, 212, 1323, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ما يجد الشهيد من مس القتل إلا كما يجد أحدكم من مس القرصة».', 'The Messenger of Allah (ﷺ) said, "The martyr experiences no more pain in being slain than one of you experiences from the stinging of an ant.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1323', 'Riyad as-Salihin 1323', 'ریاض الصالحین 1323', 'رواه الترمذي وقال: حديث حسن صحيح', 'معنى الحديث: أن الإنسان إذا استشهد في سبيل الله، فإن ما يُصيبه من مَسِّ القتل وفي رواية الدارمي: "من ألم القتل" لا يشعر به إلا كما يشعر أحدنا من قرصة النملة، وفي رواية الدارمي: "من ألم القرصة".
والمعنى: أن الشهيد لا يُكابد شدة الموت وسكراته،كما هو حال غيره من الناس، بل إن أشد ما يجده ويعانيه عند موته هو ما نجده من قَرْصة النملة فيما تحدثه من ألمٍ في سرعة زواله، فلا يشعر به،وهذا من فضل الله تعالى على الشهيد، فإنه لمَّا قَدَّم روحه في سبيل الله تعالى رخيصة، هَوَّن الله عليه ألم القتل.', 'عِناية الله بالشهيد حيث يُخَفف عنه آلامه فتزول سريعا، ولا يعقبها علة ولا سَقَم.', 'مَسّ القتل : ألمَه.
القَرْصَة : عَضَّة النَّملة، وأصل القَرْص: القَبْضُ بالإبهام والسَبَابة على جزء من الجسم قبضا مؤلماً.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3914', false),
(21324, 2, 212, 1324, 'hadith', 'عن عبد الله بن أبي أوفى رضي الله عنهما أن رسول الله صلى الله عليه وسلم في بعض أيامه التي لقي فيها العدو انتظر حتى مالت الشمس، ثم قام في الناس فقال: " أيها الناس، لا تتمنوا لقاء العدو، وسلو الله العافية، فإذا لقيتموه فاصبروا، واعلموا أن الجنة تحت ظلال السيوف" ثم قال: "اللهم منزل الكتاب ومجري السحاب، وهازم الأحزاب اهزمهم وانصرنا عليهم".', 'On one occasion the Messenger of Allah (ﷺ) was confronting the enemy. He waited until the sun had declined. Then he stood up to address the people and said, "O people! Do not wish for an encounter with the enemy. Pray to Allah to grant you safety; (but) when you encounter them, show patience, and know that Jannah is under the shades of the swords." Then he (ﷺ) said: "Allahumma munzilal-kitab, wa mujriyas- sahab, wa hazimal-Ahzab, ihzimhum wansurna alaihim (O Allah, Revealer of the Book, Disperser of the clouds, Defeater of the Confederates, put our enemy to rout and support us against them).".', 'عبد الله بن أبي أوفى رضي الله عنهما', '''Abdullah bin Abu Aufa (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1324', 'Riyad as-Salihin 1324', 'ریاض الصالحین 1324', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21325, 2, 212, 1325, 'hadith', 'عن سهل بن سعد رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم «ثنتان لا تردان، أو قلما تردان: الدعاء عند النداء وعند البأس حين يلحم بعضهم بعضًا».', 'The Messenger of Allah (ﷺ) said, "Supplications at two times are never turned down (or said, "Are seldom turned down"), a supplication after the Adhan has been proclaimed, and a supplication during the battle combating the enemy.".', 'سهل بن سعد رضي الله عنه', 'Sahl bin Sa''d (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1325', 'Riyad as-Salihin 1325', 'ریاض الصالحین 1325', 'رواه أبو داود بإسناد صحيح', 'في هذا الحديث بيان فضل الجهاد في سبيل الله حيث يستجيب الله تعالى لدعاء المجاهد وهو في المعركة، وفيه أيضاً بيان فضل الأذان حيث يستجيب الله تعالى لدعاء المسلم عند الأذان وحتى إقامة الصلاة.', 'استحباب الدعاء في هذين الوقتين لما لهما من فضيلة الإجابة.
أنَّ الدعاء من أقوى الأسباب في دفع المكروه وحصول المطلوب.
أهمية أداء صلاة الجماعة في المسجد.', 'ثنتان : دعوتان.
لا تردان : يُستجاب فيهما الدعوة.
قَلَّما : من القِلة.
النداء : الأذان.
البأس : الحرب.
حِينَ يُلْحِمُ بَعْضُهُ بَعْضًا : يقتربون ويلتصق لحم بعضهم ببعض.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5035', false),
(21326, 2, 212, 1326, 'hadith', 'عن أنس رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم إذا غزا قال: «اللهم أنت عضدي ونصيري، بك أحول وبك أجول وبك أصول، وبك أقاتل».', 'Whenever the Messenger of Allah (ﷺ) set out to participate in Jihad, he would supplicate: "Allahumma Anta ''adudi wa nasiri, bika ahulu, wa bika asulu, wa bika uqatilu (O Allah, You are my Supporter and my Helper. With Your help I get strength, and with Your help I bounce upon the enemy and defeat it, and with Your help I fight).".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1326', 'Riyad as-Salihin 1326', 'ریاض الصالحین 1326', 'رواه أبو داود، والترمذي وقال: حديث حسن', 'كان النبي صلى الله عليه وسلم إذا أراد غزوة أو شرع فيها، قال ما معناه: اللهم أنت ناصري ونَصيري، بك وحدك أنتقل من شأن إلى غيره، وبك وحدك أثب على أعداء الدين، وبك أقاتلهم.', 'النصر كلّه من عند الله، فعلى العبد أن يتوكل على الله، ولا يركن لنفسه طرفة عين؛ فذاك الخذلان والخسران.
أنَّ هذا الدعاء فيه كل مقومات الإيمان بالله والتوكل عليه.
المسلم يقاتل بالله ولله لتكون كلمة الله هي العليا.
ينبغي على المسلم الاقتداء بالنبي –صلى الله عليه وسلم– في اللجوء إلى الله ودعاءه وقت الشدة.
لا حول ولا قوة للعبد إلا بربه؛ لأن القوة لله جميعًا.', 'إذا غزا : أي: إذا شرع في الغزو.
عضدي : عوني ونصيري.
بك : أي: وحدك.
أحول : أقوى وأنتقل من مكان إلى مكان ومن حال إلى حال.
أصول : أحمل على العدو حتى أغلبه وأستأصله.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5024', false),
(21327, 2, 212, 1327, 'hadith', 'عن أبي موسى، رضي الله عنه أن النبي صلى الله عليه وسلم كان إذا خاف قومًا قال: اللهم إنا نجعلك في نحورهم، ونعوذ بك من شرورهم".', 'When the Prophet (ﷺ) had any fear of an enemy, he used to supplicate: "Allahumma inna naj''aluka fi nuhurihim, wa na''udhu bika min shururihim (O Allah! We put You in front of them, and we seek refuge in You from their evils).".', 'أبي موسى رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', 'إسناده صحيح', 'رياض الصالحين 1327', 'Riyad as-Salihin 1327', 'ریاض الصالحین 1327', 'رواه أبو داود بإسناد صحيح', 'قوله: "اللهم إنا نجعلك في نحورهم"، أي: أمامهم تدفعهم عنا وتمنعنا منهم، وخص النحر لأنه أسرع وأقوى في الدفع والتمكن من المدفوع، والعدو إنما يستقبل بنحره عن المناهضة للقتال أو للتفاؤل بنحرهم أو قتلهم، "ونعوذ بك من شرورهم"، ففي هذه الحال يكفيك الله شرهم، والمراد نسألك أن تصد صدورهم، وتدفع شرورهم، وتكفينا أمورهم، وتحول بيننا وبينهم.
كلمتان يسيرتان إذا قالهما الإنسان بصدق وإخلاص، فإن الله تعالى يدافع عنه، والله الموفق.', 'الدعاء بهذا الدعاء عند توقع شر ظالم أو غيره.
الالتجاء إلى الله تعالى، والاعتصام به عند كل نازلة.', 'نحورهم : جمع نحر، وهو أسفل الرقبة وأعلى الصدر بين الترقوتين.
نعوذ : أي نلتجئ إلى الله ونستنصر به.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5473', false),
(21328, 2, 212, 1328, 'hadith', 'عن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «الخيل معقود في نواصيها الخير إلى يوم القيامة».', 'The Messenger of Allah (ﷺ) said, "There is goodness in the forelocks of horses till the Day of Resurrection."', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1328', 'Riyad as-Salihin 1328', 'ریاض الصالحین 1328', 'متفق عليه', 'الخيل ملازم لها الخير إلى يوم القيامة، الثواب المترتب على ربطها وهو خير آجل، والمغنم الذي يكتسبه المجاهد من مال الأعداء وهو خير عاجل.', 'استحباب اقتناء الخيل وإعدادها.
الجهاد ماض إلى يوم القيامة ؛ لأنه ذكر -صلى الله عليه وسلم- بقاء الخير في نواصي الخيل إلى يوم القيامة.
فضيلة الجهاد في سبيل الله -تعالى-.
تفضيل الخيل على غيرها من الحيوانات.', 'معقود : مربوط.
نواصيها : المراد بالناصية هنا: الشعر المسترسل على الجبهة.
الأجر : الثواب المترتب على ربطها، وهو من الخير الآجل.
المغنم : هو المال المكتسب من مال الكفرة، وهو من الخير العاجل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3583', false),
(21329, 2, 212, 1329, 'hadith', 'عن عروة البارقي رضي الله عنه أن النبي صلى الله عليه وسلم قال: الخيل معقود في نواصيها الخير إلى يوم القيامة: الأجر والمغنم".', 'The Prophet (ﷺ) said, "Goodness is tied to the foreheads of horses until the Day of Resurrection, i.e., reward (in the Hereafter) and spoils.".', 'عروة البارقي رضي الله عنه', '''Urwah Al-Bariqi (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1329', 'Riyad as-Salihin 1329', 'ریاض الصالحین 1329', 'متفق عليه', 'الخيل ملازم لها الخير إلى يوم القيامة، الثواب المترتب على ربطها وهو خير آجل، والمغنم الذي يكتسبه المجاهد من مال الأعداء وهو خير عاجل.', 'استحباب اقتناء الخيل وإعدادها.
الجهاد ماض إلى يوم القيامة ؛ لأنه ذكر -صلى الله عليه وسلم- بقاء الخير في نواصي الخيل إلى يوم القيامة.
فضيلة الجهاد في سبيل الله -تعالى-.
تفضيل الخيل على غيرها من الحيوانات.', 'معقود : مربوط.
نواصيها : المراد بالناصية هنا: الشعر المسترسل على الجبهة.
الأجر : الثواب المترتب على ربطها، وهو من الخير الآجل.
المغنم : هو المال المكتسب من مال الكفرة، وهو من الخير العاجل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3583', false),
(21330, 2, 212, 1330, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «من احتبس فرسًا في سبيل الله إيمانًا بالله وتصديقًا بوعده، فإن شبعه، وروثه، وبوله في ميزانه يوم القيامة».', 'The Messenger of Allah (ﷺ) said, "He who keeps a horse for Jihad purposes, having faith in Allah and relying on His Promise, will find that its fodder, drink, droppings and urine will all be credited to him in his Scales on the Day of Resurrection.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1330', 'Riyad as-Salihin 1330', 'ریاض الصالحین 1330', 'رواه البخاري', 'أن مَن أوقَف فرسًا للجهاد في سبيل الله تعال وابتغاء مرضاته لكي يُحَارب عليه الغزاة، ابتغاء وجه الله تعالى، وتصديقاً بوعده الذي وعَدَ به، حيث قال: (وما تنفقوا من شيء في سبيل الله يوف إليكم) فإن الله يُثِيْبُه عن كل ما يأكله أو يشربه أو يخرجه من بول أو روث، حتى يَضعه له في كِفَّة حسناته يوم القيامة. 
وفي حديث أبي هريرة رضي الله عنه الطويل: "الخَيل ثلاثة: هي لرَجُلٍ وِزْرٌ، وهي لرَجُل سِتْر، وهي لِرَجُلٍ أجْرٌ . . ثم قال: وأما التي هي له أَجْرٌ، فرَجُل ربَطَها في سبيل الله لأهل الإسلام في مَرْج، أو رَوْضَةٍ فما أكلت من ذلك المَرْجِ أو الرَّوْضَةِ من شيء إلا كُتِبَ له عَدَدَ ما أكَلَتْ حسنات وكتب له عَدَد أرْوَاثِهَا وَأبْوَالِهَا حسنات، ولا تَقْطَعُ طِوَلَهَا فَاسْتَنَّتْ شَرَفاً أو شَرَفَيْنِ إلا كَتَب الله له عَدَد آثَارِهَا، وَأرْوَاثِهَا حسنات، ولا مَرَّ بها صَاحِبُها على نَهْر، فشَربَت منه، ولا يُريد أن يَسْقِيهَا إلا كَتَب الله له عَدَد ما شَرَبت حسنات" متفق عليه.', 'الترغيب في إعداد الخيل في سبيل الله، وأن ما ينفقه الإنسان عليها يكون حسنات له، وما يخرج منها يؤجر عليه.
الحَض على الجهاد في سبيل الله تعالى لإعلاء كلمة الله.
المال المكتسب باتخاذ الخيل من خير وجوه الأموال، وأطيبها؛ لأن البركة في نواصيها.
تفضيل الخيل على غيرها من الدَّواب.
جواز وقف الخيل للجهاد في سبيل الله.
المرء يؤجر بنيته الخالصة لله تعالى، والمصدقة بوعده كما يؤجر العامل.
الحث على اقتناء كل ما يُساعد على الجهاد والعناية بكل ما فيه قوة الأمة وهيبتها.
بشرى ببقاء الإسلام وأهله إلى يوم القيامة؛ لأن من لازم استمرار الجهاد بقاء المجاهدين وهم المسلمون.', 'احْتَبَسَ فَرَساً : وقَّفَه على الغُزاة يستعينون به في الجهاد.
بِوَعْدِه : أي بالثواب المترتب على ذلك.
شِبَعَهُ : قَدْر ما يَشبع به.
ريَّه : شُربه وشَبَعه.
ورَوْثَهُ وبَوْلَه : يريد ثواب ذلك لا الأرواث بعينها، والرَّوث: رجيع ذات الحَافِر، أي ما خرج من دبرها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4181', false),
(21331, 2, 212, 1331, 'hadith', 'عن أبي مسعود رضي الله عنه قال: جار رجل إلى النبي صلى الله عليه وسلم بناقة مخطومة فقال: هذه في سبيل الله، فقال رسول الله صلى الله عليه وسلم: «لك بها يوم القيامة سبعمائة ناقة كلها مخطومة».', 'A man came to the Prophet (ﷺ) with a she-camel wearing a nose-string and said: "This is (a gift) in the Cause of Allah." The Messenger of Allah (ﷺ) replied, "You will have in return for it on the Day of Resurrection seven hundred she-camels and every one of them will be wearing a nose-string.".', 'أبي مسعود رضي الله عنه', 'Abu Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1331', 'Riyad as-Salihin 1331', 'ریاض الصالحین 1331', 'رواه مسلم', 'جاء رجل إلى النبي صلى الله عليه وسلم بناقة مَخْطُومَةٌ، أي مَشْدُودةٌ بِحَبل، وهو قريب من الزمام التي تُشَدُّ به الناقة، فقال الرجل: يا رسول الله، هذه في سَبِيلِ الله، أي أوقفها في الجهاد في سبيل الله تعالى ، للغزو بها. 
فقال له -صلى لله عليه وسلم-: "لك بها سَبْعُمائَةِ نَاقة "؛ وذلك لأن الله تعالى يُضاعف الحسنة بعشر أمثالها إلى سَبعمائة ضِعف إلى أضْعَاف كثيرة، كما في قوله تعالى : (مَثَل الذين ينفقون أموالهم في سبيل الله كَمثَلِ حبة أنبتت سبع سنابل في كل سنبلة مائة حبة والله يضاعف لمن يشاء والله واسع عليم).
قوله: "كُلُّهَا مَخْطُومَةٌ " فائدة الخِطام: زيادة تمكن صاحبها من أن يعمل بها ما أراد، وهذا من حسن الجزاء، فكما أن هذا الرجل جاء بناقته إلى النبي -صلى الله عليه وسلم- مَشْدُودٌ عليها بالخِطام، جزاه الله بسبعمائة ناقة كلها مَشْدُودٌ عليها بالخِطام؛ وليعلم من ينفق في الدنيا أن كل زيادة يقدمها سيحزى بها، والخطام له قيمة وجمال وزيادة في الناقة.', 'النفقة في سبيل الله يضاعفها الله سبع مئة ضعف.
حرص الصحابة -رضي الله عنهم- على البذل في سبيل الله.
الجزاء من جنس العمل.
من أساليب الدعوة الترغيب.
الترغيب في التبرع بما يستعان به على القتال من فرس أو ناقة أو غير ذلك، والله يضاعف على ذلك الأجر.', 'بناقة مخطومة : مجعولة في رأسها الخطام، وهو الزمام الذي تُشد به الناقة.
هذه في سبيل الله : أي مجعولة فيه.
لك بها : أي بدلها.
القيامة : هو اليوم الآخر الذي تحاسب فيه الخلائق، وسمي يوم القيامة باليوم الآخر؛ لأنه لا يوم بعده.
سبيل الله : هو الجهاد إذا أطلق في النصوص.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5036', false),
(21332, 2, 212, 1332, 'hadith', 'عن أبي حماد- ويقال: أبو سعاد، ويقال: أبو أسد، ويقال: أبو عامر، ويقال: أبو عمرو، ويقال: أبو الأسود، ويقال: أبو عبس- عقبة بن عامر الجهني، رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم وهو على المنبر يقول: «وأعدوا لهم ما استطعتم من قوة ألا إن القوة الرمي، ألا إن القوة الرمي، ألا إن القوة الرمي».', 'I heard the Messenger of Allah (ﷺ) saying from the pulpit, "Prepare to meet them (the enemy) with as much strength as you can afford. Verily! Strength is in archery, strength is in archery, strength is in archery.".', null, '''Uqbah bin ''Amir Al-Juhani (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1332', 'Riyad as-Salihin 1332', 'ریاض الصالحین 1332', 'رواه مسلم)). وعنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: "ستفتح عليكم أرضون ويكفيكم الله فلا يعجز أحدكم أن يلهو بأسهمه" ((رواه مسلم', 'يخبر النبي صلى الله عليه وسلم أصحابه بأنه سَتُفتح عليهم البلاد من غير اقتتال، فعليهم أن لا يعجِزوا عن تَعَلُّم الرَّمي بالسهام، فإن ذلك من أولى ما يَلهو به المسلمون، -ما لم يُضَيَّع به حقًا واجبًا-؛ لأن ذلك مما يُعينهم على الجهاد في سبيل الله، وذلك من أفضل المقاصد وأسمى الغايات.
وإنما كان التعبير باللهو؛ لأن النُّفوس مَجْبُولة على حُبِّه فعبر به، وإلا فإن المقصود الأعظم من تعلمه، هو: الإعداد في سبيل الله تعالى ، لا مجرد اللعب به.', 'النَّدب إلى الرَّمي والتَّمرن عليه، ولو في غير وقت الحاجة إليه.
دعوة الإسلام إلى الإعداد، والاستعداد، حتى في أوقات السلم؛ تحسباً لكل طارئ.
من دلائل النبوة إخبار الرسول -صلى الله عليه وسلم- بما سيفتح على أمته من البلاد.
الجهاد من أسباب كفاية الناس في معاشهم، وسعة أرزاقهم؛ لأن رزق هذه الأمة تحت رماحها،  وليس في تخلفها وتثقلها إلى الأرض.', 'يكفيكم الله : أي الحرب والقتال لانتصاركم على معظم الأعداء.
فلا يعجز : فلا يقعد ولا يضعف.
يلهو بسهمه : أن يشغل وقت فراغه بالرمي بها تمرناً.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3720', false),
(21333, 2, 212, 1333, 'hadith', 'وعنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «ستفتح عليكم أرضون ويكفيكم الله فلا يعجز أحدكم أن يلهو بأسهمه».', 'I heard the Messenger of Allah (ﷺ) saying, "Lands shall be laid open to you, and Allah will suffice you (against your enemies), but none of you should neglect practicing his skill in archery.".', null, '''Uqbah bin ''Amir Juhani (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1333', 'Riyad as-Salihin 1333', 'ریاض الصالحین 1333', 'رواه مسلم', 'في هذا الحديث حث المسلم على تعلم الرمي، والتمرن عليه ولو في غير وقت الحاجة إليه؛ لأن ذلك من أسباب تحقيق النصر من الله، وحصول الكفاية والرزق للمسلمين.', 'بشارة النبي – صلى الله عليه وسلم – بالفتوحات الإسلامية.
الندب إلى الرمي والتدرب عليه.
الإسلام يحث أتباعه ودعاته على الإعداد والاستعداد في كل الأحوال.', 'يكفيكم الله : أي الحرب والقتال لانتصاركم على معظم الأعداء.
فلا يعجز : فلا يقعد ولا يضعف.
أن يلهو بأسهمه : أن يُشغل وقت فراغه بالرمي بها تمرناً.
أرضون : جمع أرضٍ، وهذا من البشائر النبوية التي تحققت.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6385', false),
(21334, 2, 212, 1334, 'hadith', 'وعنه أنه قال: قال رسول الله صلى الله عليه وسلم : «من عُلم الرمي ثم تركه فليس منا أو فقد عصى».', 'The Messenger of Allah (ﷺ) said, "He who learnt archery and then neglected it, is not from us." (Or said,) "He has been guilty of disobedience (to Messenger of Allah).".', null, '''Uqbah bin ''Amir Al-Juhani (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1334', 'Riyad as-Salihin 1334', 'ریاض الصالحین 1334', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21335, 2, 212, 1335, 'hadith', 'وعنه، رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: "إن الله يدخل بالسهم الواحد ثلاثة نفر الجنة: صانعه يحتسب في صنعته الخير، والرامي به ومنبله. وارموا واركبوا، وأن ترموا أحب إلي من أن تركبوا. ومن ترك الرمي بعد ما علمه رغبة عنه فإنها نعمة تركها" أو قال: "كفرها".', 'I heard the Messenger of Allah (ﷺ) saying, "Allah will admit three persons to Jannah for one arrow; the maker who has a good motive in making it, the one who shoots it, and the one who hands it up for shooting. So shoot and ride, but I like your shooting (more) than your riding. He who gives up archery after becoming adept in it for lack of interest, neglects a (great) blessing." (Or said,) "One who does so is ungrateful.".', null, '''Uqbah bin ''Amir Al-Juhani (May Allah be pleased with him)', null, 'رياض الصالحين 1335', 'Riyad as-Salihin 1335', 'ریاض الصالحین 1335', 'رواه أبو داود', null, null, null, 'sunnah.com', null, false, null, false),
(21336, 2, 212, 1336, 'hadith', 'عن سلمه بن الأكوع، رضي الله عنه قال: مر النبي صلى الله عليه وسلم على نفر ينتضلون، فقال: «ارموا بني إسماعيل فإن أباكم كان راميًا».', 'The Prophet (ﷺ) happened to pass by a group of people who were having a shooting match. (Upon seeing them, he (ﷺ)) said, "Shoot, O sons of (Prophet) Isma''il, for your father was an archer.".', 'سلمه بن الأكوع رضي الله عنه', 'Salamah bin Al-Akwa (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1336', 'Riyad as-Salihin 1336', 'ریاض الصالحین 1336', 'رواه البخاري', 'يخبر سَلَمَة بن الأكْوَع رضي الله عنه أن النبي صلى الله عليه وسلم مرَّ على بعض أصحابه وهم يترامون بالسهام، أيهم يفوز على صاحبه، فأقرهم على ما هم عليه، بل وحَثَّهم بقوله: " ارْمُوا بَنِي إسماعيل" أي داوموا على الرمي وحافظوا عليه، فإنه من نِعَم الله تعالى عليكم يا بني إسماعيل -ويقصد: العرب- أن أباكم إسماعيل بن إبراهيم -عليهما السلام- كان ممن يُجِيد الرمي ويحسنه.', 'الترغيب بالرَّمي لأجل التَّمرن عليه.
الجد الأعلى يُسمى أبا.
حسن خلق النبي -صلى الله عليه وسلم- ومعرفته بأمور الحرب.
استحباب العمل بخصال الآباء المحمودة.
الإمام العادل يرعى أمته، ويحضها على تعلم ما ينفعها، ويشجعها على تعلم فنون الحرب للدفاع عن دينها.', 'نفر : جماعة من الرجال ما بين الثلاثة إلى العشرة.
ينتضلون : يترامون بالسهام للسبق.
بنو إسماعيل : يقصد بهم العرب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3559', false),
(21337, 2, 212, 1337, 'hadith', 'عن عمرو بن عبسة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: من رمى بسهم في سبيل الله فهو له عدل محررة:.', 'I heard the Messenger of Allah (ﷺ) saying: "He who shoots an arrow for the sake of Allah, will have a reward equal to the emancipation of a slave.".', 'عمرو بن عبسة رضي الله عنه', '''Amr bin ''Abasah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1337', 'Riyad as-Salihin 1337', 'ریاض الصالحین 1337', 'رواه أبو داود، والترمذي وقال: حديث حسن صحيح', 'معنى الحديث: أن مَنْ رَمَى بسهم في وجوه أعداء الله تعالى ، فإن له أجر مَنْ أعتق رقبة في سبيل الله تعالى ، سواء أصاب به عدوًا أو لم يُصب، كما هي رواية النسائي: "ومَن رَمَى بسهم في سبيل الله تعالى بَلَغَ العدو أو لم يَبْلُغ".
أما إذا أصاب به عدوا كان له به درجة في الجنة، كما هي رواية أبي داود: "من بلغ بسهم في سبيل الله عز وجل فله درجة.
 "وفي رواية أحمد: "في الجنة".', 'فضل الرَّمي في سَبِيلِ الله -تعالى- وثوابه.
فيه الحث على الجهاد في سبيل الله وتعظيم أمره.', 'عِدْلُ مُحَرَّرَة : أي مِثْل ثواب رقَبَة مُعْتَقة في سبيل الله.
سبيل لله : سبيل الله هو القتال لتكون كلمة الله هي العليا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4194', false),
(21338, 2, 212, 1338, 'hadith', 'عن أبي يحيي خريم بن فاتك رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من أنفق نفقة في سبيل الله كتب له سبعمائة ضعف».', 'The Messenger of Allah (ﷺ) said, "He who makes a contribution in Allah''s way, will have his reward seven hundred times recorded to his credit.".', 'أبي يحيي خريم بن فاتك رضي الله عنه', 'Abu Yahya Khuraim bin Fatik (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1338', 'Riyad as-Salihin 1338', 'ریاض الصالحین 1338', 'رواه الترمذي وقال: حديث حسن', 'من أنْفَقَ نفقة قليلة أو كثيرة في سبيل الله تعالى ، سواء كان في الجهاد في سبيل الله تعالى أو في غيره من وجوه البِّر والطاعات، ضاعف الله له الأجر يوم القيامة إلى سبعمائة ضِعف.', 'مضاعفة الثواب لكل من أنفق نفقة في سبيل الله تعالى يبتغي بها الأجر عند الله -تعالى-.', 'ضِعْفٌ : المِثل فما زاد.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4188', false),
(21339, 2, 212, 1339, 'hadith', 'عن أبي سعيد رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ما من عبد يصوم يومًا في سبيل الله إلا باعد الله بذلك اليوم وجهه عن النار سبعين خريفًا».', 'The Messenger of Allah (ﷺ) said, "Every slave of Allah who observes Saum (fasting) for a day in the Cause of Allah, Allah will keep his face from Hell-fire at a distance of seventy years.".', 'أبي سعيد رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1339', 'Riyad as-Salihin 1339', 'ریاض الصالحین 1339', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21340, 2, 212, 1340, 'hadith', 'عن أبي أمامة، رضي الله عنه عن النبي صلى الله عليه وسلم قال: «من صام يومًا في سبيل الله جعل الله بينه وبين النار خندقًا كما بين السماء والأرض».', 'The Prophet (ﷺ) said, "He who observes Saum (fasting) for a day in the Cause of Allah, Allah will keep his face from Hell-fire at a distance equivalent to that between heaven and the earth.".', 'أبي أمامة رضي الله عنه', 'Abu Umamah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1340', 'Riyad as-Salihin 1340', 'ریاض الصالحین 1340', 'رواه الترمذي وقال: حديث حسن صحيح', 'في هذا الحديث بيان فضل من صام يوما ًخالصاً لوجه الله، حيث ينجيه الله من النار ويبعده عنها كبعد السماء عن الأرض.', 'فضل الصوم ولو كان يوماً واحداً، وأنه يكون وقاية لصاحبه من النار.
فضل الصوم في وقت الجهاد إلا إذا كان يُؤثر على قوة الجنود ونشاطهم؛ فهو غير مستحب.
يؤخذ منه أن العمل الذي يراد به وجه الله يكون له فضل عظيم وتأثير كبير.', 'صام : من الصيام : وهو الإمساك عن المفطرات من الفجر إلى غروب الشمس بنية مخصوصة.
في سبيل الله : أي : للّه ولوجهه
خندقاً : حفرة حول المكان، وأخدود عميق مستطيل يحفر في ميدان القتال ليتقي به الجنود.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6399', false),
(21341, 2, 212, 1341, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من مات ولم يغزُ، ولم يحدث نفسه بالغزو، مات على شعبة من النفاق».', 'The Messenger of Allah (ﷺ) said, "He who dies without having fought in the Cause of Allah or without having thought of doing so, will die with one characteristic of hypocrisy in him.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1341', 'Riyad as-Salihin 1341', 'ریاض الصالحین 1341', 'رواه مسلم', 'كل رجل قادر على الغزو يبلغه الأجل ولم يغز ولم يحدث نفسه بذلك أي لم يكلم بالغزو نفسه، والمعنى لم يعزم على الجهاد ففيه شيء من النفاق، ومن علاماته في الظاهر إعداد آلة الغزو، قال تعالى: (ولو أرادوا الخروج لأعدوا له عدة).
وقوله: (مات على شعبة من نفاق): أي: نوع من أنواع النفاق ، أي: من مات على هذا فقد أشبه المنافقين والمتخلفين عن الجهاد، ومن تشبه بقوم فهو منهم، فيجب على كل مؤمن أن ينوي الجهاد.
وكونه يغزو أي: بشروط الغزو والجهاد، فإذا توفرت عُمل به وإلا بقيت النية موجودة إلى حين توفر دواعي الجهاد.', 'أن من لم يغز ولم يحدث نفسه به فقد أشبه المنافقين في تخلفهم عن الجهاد.
تحديث النفس بالغزو بصدق يرفع العبد إلى مقام أهل الايمان.
حث الإمام رعيته على الاستعداد للجهاد، وعدم تعوّد الجبن والخوف من لقاء العدو.
أقل الجهاد إشغال الفكر والنفس فيه', 'مَنْ لَمْ يَغْزُ : أي لم يباشر القتال في سبيل الله.
لم يُحَدِّث نَفْسَهُ بِالغَزْو : لم ينو الغزو.
شعبة : خصلة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6404', false),
(21342, 2, 212, 1342, 'hadith', 'عن جابر رضي الله عنه قال: كنا مع النبي صلى الله عليه وسلم في غزاة فقال: «إن بالمدينة لرجالا ما سرتم مسيرًا، ولا قطعتم واديًا إلا كانوا معكم حبسهم المرض»', 'We accompanied the Prophet (ﷺ) in an expedition when he (ﷺ) said, "Some people have remained behind us in Al-Madinah, and we never cross a valley but they are with us. They share the reward with us because they have been held back by valid excuse."In another narration the wordings are: "...by any genuine excuse."In another narration the wordings are: "They are your partners in reward.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1342', 'Riyad as-Salihin 1342', 'ریاض الصالحین 1342', null, 'يخبر صلى الله عليه وسلم عن رجال ما حبسهم عن الجهاد في سبيل الله عز وجل إلا المرض ونحوه من الأعذار، فيخبر أنه ما سار الغُزاة سيرا ولا قطعوا واديا ولا شِعبا إلا وكُتِبَ لهؤلاء ثواب ذلك العمل.', 'من حبسه العذر كان كأولي الضرر.
أن من صحت نيته، وعزم على فعل عمل صالح وتركه لعذر، أن له مثل أجر فاعله.
ليس على أولي الضرر كالأعمى والمريض حرج.', 'غزاة : غزوة.
مسيرا : أي: سيرا أو في مكان سير.
قطعتم واديا : سلكتموه.
واديا : الوادي: مفرج ما بين جبال أو تلال أو آكام
حبسهم : منعهم.
شركوكم : شاركوكم.
الأجر : الثواب.
شِعْبًا : الطريق في الجبل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4557', false),
(21343, 2, 212, 1343, 'hadith', 'عن أبي موسى، رضي الله عنه أن أعرابيا أتى النبي صلى الله عليه وسلم فقال: يا رسول الله الرجل يقاتل للمغنم، والرجل يقاتل ليذكر، والرجل يقاتل ليرى مكانه؟ وفي رواية: يقاتل شجاعة، ويقاتل حَمِيّة. وفي رواية: ويقاتل غضبًا، فمن في سبيل الله؟ فقال رسول الله صلى الله عليه وسلم : «من قاتل لتكون كلمة الله هي العليا، فهو في سبيل الله».', 'A bedouin came to the Prophet (ﷺ) and said: "O Messenger of Allah! One man fights for booty, another fights to win fame, and the third fights for show off." Another narration is: "One fights for displaying his valour, another fights out of his family pride." Another narration is: "One fights out of rage." He asked: "Which of them is fighting in the Cause of Allah?" The Messenger of Allah (ﷺ) said, "The one who fights so that Word of Allah (Islam) be exalted, is the one who fights in the Cause of Allah.".', 'أبي موسى رضي الله عنه', 'Abu Musa (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1343', 'Riyad as-Salihin 1343', 'ریاض الصالحین 1343', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21344, 2, 212, 1344, 'hadith', 'عن عبد الله بن عمرو بن العاص، رضي الله عنهما، قال: قال رسول الله صلى الله عليه وسلم: «ما من غازية أو سرية تغزو، فتغنم وتسلم، إلا كانوا قد تعجلوا ثلثي أجورهم، وما من غازية أو سرية تخفق وتصاب إلا تم لهم أجورهم».', 'The Messenger of Allah (ﷺ) said, "A detachment of soldiers, large or small, who fights in the way of Allah, gets its share of booty and returns safe and sound, receives in advance two- thirds of its reward (only one-third remaining to its credit will be received in the Hereafter). And a troop of soldiers, large or small, that returns disappointed and is afflicted by misery, will receive its full reward (in the Hereafter).".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''As (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1344', 'Riyad as-Salihin 1344', 'ریاض الصالحین 1344', 'رواه مسلم', 'للحديث احتمالان:
الأول: أن كل سَرِيَّة قاتلت الأعداء ثم سلمت منهم وغنمت فإن أجرها أقلّ من سرية أخرى لم تَسلم، أو سلمت ولم تَغْنم، كما رجحه النووي رحمه الله.
الثاني: الحديث دليل على حل الغنيمة وليست منقصة للأجر، إنما فيه تعجيل بعض الأجر مع التسوية فيه للغانم وغير الغانم إلا أن الغانم عجل له ثلثا أجره وهما مستويان في جملته وقد عوض الله من لم يغنم في الآخرة بمقدار ما فاته من الغنيمة والله يضاعف لمن يشاء، كما قال ابن عبد البر رحمه الله.', 'فضل المشاركة والخروج للغزو في سبيل الله.
الحث على بذل الجهد والحرص على الشهادة أو النصر.', 'غَازِيَة : صفةٌ لجماعةٍ غازية.
سَرِيَّة : قطعة من الجيش يبلغ أقصاها أربعمائة.
تَغْزُو : تجاهد في سبيل الله.
فَتَغْنَمُ : فتصيب غنيمة وهي ما أُخذ من أموال الحرب.
وَتَسْلَمُ : أي : من الموت.
ثُلُثَىْ أُجُورِهِمْ : وهما السلامة والغنيمة، ويبقى لهم الثلث ينالونه في الآخرة.
تُخْفِقُ	من الإخفاق : أن يغزوا فلا يغنموا شيئاً.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6392', false),
(21345, 2, 212, 1345, 'hadith', 'عن أبي أمامة، رضي الله عنه أن رجلا قال: يا رسول الله ائذن لي في السياحة. فقال النبي صلى الله عليه وسلم : «إن سياحة أمتي الجهاد في سبيل الله، عز وجل».', 'A man sought permission from the Messenger of Allah (ﷺ) to travel in the land. He (ﷺ) said to him, "Travel for my people is Jihad in the Cause of Allah, glory be to Him.".', 'أبي أمامة رضي الله عنه', 'Abu Umamah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1345', 'Riyad as-Salihin 1345', 'ریاض الصالحین 1345', 'رواه أبو داود بإسناد جيد', 'في هذا الحديث بيان أنَّ العبادات توقيفية، وأنَّه لا يجوز للمسلم القيام بها إلا وفق الكيفية التي يحددها له الشرع الحنيف، لذلك بين النبي صلى الله عليه وسلم لهذا الرجل الذي أراد أن يسيح في الأرض لأجل العبادة أنَّ هذا من عمل النصارى وأن السياحة في الأرض هي نشر الإسلام فيها وأن سياحة أهل الاسلام هي الجهاد في سبيل الله لإعلاء دين الله تعالى .', 'أنَّ أفضل أنواع الضرب في الأرض إنما هو السعي فيها للجهاد في سبيل الله.
أنَّ الرحلة في طلب العلم داخلة في معنى السياحة الشرعية.
الإسلام يغير المفاهيم السائدة إلى عنصر بنَّاء، وفضيلة وتعاون على البر والتقوى.
حرص الصحابة -رضي الله عنهم- على استئذان النبي -صلى الله عليه وسلم- في أمورهم.', 'السياحة : الذهاب في الأرض للعبادة.
الجهاد في سبيل الله : قتال الكفار بقصد إعلاء كلمة الله -تعالى-.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5033', false),
(21346, 2, 212, 1346, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «قفلة كغزوة».', 'The Prophet (ﷺ) said, "The return from an expedition is an act as meritorious as fighting.".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''As (May Allah be pleased with them)', null, 'رياض الصالحين 1346', 'Riyad as-Salihin 1346', 'ریاض الصالحین 1346', 'رواه أبو داود بإسناد جيد', null, null, null, 'sunnah.com', null, false, null, false),
(21347, 2, 212, 1347, 'hadith', 'عن السائب بن يزيد، رضي الله عنه قال: لما قدم النبي صلى الله عليه وسلم من غزوة تبوك تلقاه الناس، فلقيته مع الصبيان على ثنية الوداع. (رواه أبو داود بإسناد صحيح بهذا اللفظ) ورواه البخاري قال: ذهبنا نتلقى رسول الله صلى الله عليه وسلم مع الصبيان إلى ثنية الوداع', 'When the Prophet (ﷺ) returned from the battle of Tabuk, people went out from Al-Madinah to meet him and I also met him with other children at Thaniyah-tul-Wada''..', 'السائب بن يزيد رضي الله عنه', 'As-Sa''ib bin Yazid (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1347', 'Riyad as-Salihin 1347', 'ریاض الصالحین 1347', null, 'معنى الحديث: يخبر السَّائب بن يزيد رضي الله عنهما أن النبي صلى الله عليه وسلم عندما قدم من غزوة تبوك خرج الناس -ممن كان قد تخلف عن الغزو من المعذورين وغيرهم- إلى ثنية الوداع وذلك لاستقباله صلى الله عليه وسلم حين عودته.
وخرج السَّائب بن يزيد مع صِبيان المدينة لتلقي النبي صلى الله عليه وسلم .', 'مشروعية استقبال القادمين من حَرب أو سَفر.', 'تلقاه الناس : أي استقبله من كان في المدينة.
الصبيان : الغلمان قبل البلوغ.
ثنية الوداع : ما ارتفع من الأرض، وثنية الوداع: مكان قرب المدينة، سميت بذلك؛ لأن المسافر كان يُودَع عندها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3696', false),
(21348, 2, 212, 1348, 'hadith', 'عن أبي أمامة رضي الله عنه عن النبي صلى الله عليه وسلم قال: من لم يغزُ أو يجهز غازيًا، أو يخلف غازيًا في أهله بخير أصابه الله بقارعة قبل يوم القيامة:.', 'The Prophet (ﷺ) said, "He who neither takes part in fighting nor equips a warrior nor looks after his (the warrior''s) family, will be afflicted by severe calamities before the Day of Resurrection.".', 'أبي أمامة رضي الله عنه', 'Abu Umamah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1348', 'Riyad as-Salihin 1348', 'ریاض الصالحین 1348', 'رواه أبو داود بإسناد صحيح', 'في هذا الحديث الحث على الغزو، وبيان العقوبة الشديدة من الله تعالى في الدنيا قبل الآخرة على من ترك الجهاد في سبيل الله أو ترك إعانة المجاهدين بالمال أو بمساعدتهم في رعاية أهليهم والحفاظ عليهم من بعدهم، فمن ترك القيام بهذه الأمور أصابته المصائب العظام جراء تقصيره في نصرة دين الله تعالى .', 'التحذير من تعجيل العقوبة على ترك الجهاد.
حث النبي –صلى الله عليه وسلم– على المشاركة في الغزو أو تجهيز الغزاة.
المجتمع المسلم مجتمع التكافل والتعاون على البر والتقوى؛ لأنه كالبناء يشد بعضه بعضاً.
وجوب حفظ الجبهة الداخلية للمجتمع المسلم، وحماية أعراض وأهل المجاهدين في سبيل الله.
تحريم ترك الجهاد وتغليظ عقوبة ذلك.
الأمة التي تتخلف عن الجهاد وتركن إلى أعدائها يصيبها الذل والهوان والخزي في الدنيا قبل الآخرة.', 'الغزو : الجهاد في سبيل الله.
مَنْ لَمْ يَغْزُ : أي : بالخروج له.
يُجَهِّزْ غَازِيًا : أي : يُهيء له أسباب سفره.
يَخْلُفْ غَازِيًا في أهله بخير : يقوم بما كان يفعله من قضاء مصالحهم.
بقارعة : بمصيبة أو داهية تقرعه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6403', false),
(21349, 2, 212, 1349, 'hadith', 'عن أنس رضي الله عنه أن النبي صلى الله عليه وسلم قال: «جاهدوا المشركين بأموالكم وأنفسكم وألسنتكم».', 'The Prophet (ﷺ) said, "Fight the polytheists with your wealth, lives and tongues.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1349', 'Riyad as-Salihin 1349', 'ریاض الصالحین 1349', 'رواه أبو داود بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21350, 2, 212, 1350, 'hadith', 'عن أبي عمرو ويقال: أبو حكيم النعمان بن مقرن رضي الله عنه قال: شهدت رسول الله صلى الله عليه وسلم إذا لم يقاتل من أول النهار أخر القتال حتى تزول الشمس وتهب الريح وينزل النصر.', 'I was with the Messenger of Allah (ﷺ) when I witnessed that if he did not begin fighting in the early part of the day, he would postpone fighting till the sun had declined, the blowing of the breeze had blown and the victory from Allah had come..', 'أبي عمرو ويقال: أبو حكيم النعمان بن مقرن رضي الله عنه', 'An-Nu''man bin Muqarrin (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1350', 'Riyad as-Salihin 1350', 'ریاض الصالحین 1350', 'رواه أبو داود، والترمذي، وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21351, 2, 212, 1351, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا تتمنوا لقاء العدو، فإذا لقيتموه فاصبروا».', 'The Messenger of Allah (ﷺ) said, "Do not wish for an encounter with the enemy. Pray to Allah to grant you safety; (but) when you encounter them, show patience.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1351', 'Riyad as-Salihin 1351', 'ریاض الصالحین 1351', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21352, 2, 212, 1352, 'hadith', 'وعنه وعن جابر، رضي الله عنهما أن النبي صلى الله عليه وسلم قال: «الحرب خُدعة».', 'The Prophet (ﷺ) said, "War is deception.".', null, 'Abu Hurairah and Jabir (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1352', 'Riyad as-Salihin 1352', 'ریاض الصالحین 1352', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21353, 2, 212, 1353, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «الشهداء خمسة: المطعون والمبطون، والغريق، وصاحب الهدم والشهيد في سبيل الله».', 'The Messenger of Allah (ﷺ) said, "The martyrs are of five kinds: One who dies of plague; one who dies of disease of his belly; the drowned; one who dies under the debris (of construction, etc.), and one who dies while fighting in the way of Allah."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1353', 'Riyad as-Salihin 1353', 'ریاض الصالحین 1353', 'متفق عليه', 'الشهداء في الجملة خمسة، الذي ضربه الطاعون ومات به وهو وباء فتاك، والذي يموت بمرض البطن، والذي يموت من الغرق وقد ركب البحر ركوبا غير محرم، أو في السيول والمسابح ونحوها، والذي يموت تحت الهدم كأن سقط عليه جدار، والمقتول في سبيل الله تعالى ، وهو أعلى الأنواع، وكذلك من مات في سبيل الله بسبب غير القتال، والشهداء الأربعة الأول شهداء في أحكام الآخرة لا الدنيا فيغسلون ويصلى عليهم، والعدد في الحديث ليس للحصر.', 'فضل الله ورحمته بعباده المؤمنين.
الشهداء قسمان : شهيد الدنيا، وشهيد الآخرة.
تصحيح المفاهيم الخاطئة المستقرة في أذهان المدعوين.
العدد في الحديث ليس للحصر.', 'الشهداء : جمع شهيد : وهم أصحاب درجة عالية في الجنة، والأصل عند الإطلاق أن يراد به المقتول في سبيل الله لإعلاء كلمة الله.
خمسة : أي خمسة أصناف.
المطعون : هو الذي مات بالطاعون.
المبطون : الذي يموت بمرض بطنه.
الغريق : أي من مات بالغرق.
صاحب الهدم : الذي مات تحت الهدم.
ومن مات في سبيل الله : أي في الجهاد بسبب غير القتل كأن سقط من فرسه أو مات حتف أنفه.
في البطن : أي بسبب داءٍ في البطن.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4971', false),
(21354, 2, 212, 1354, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم : "ما تعدون الشهداء فيكم؟ قالوا: يا رسول الله من قتل في سبيل الله فهو شهيد. قال: "إن شهداء أمتي إذًا لقليل!" قالوا: فمن يا رسول الله ؟ قال: "من قتل في سبيل الله فهو شهيد، ومن مات في سبيل الله فهو شهيد، ومن مات في الطاعون فهو شهيد، ومن مات في البطن فهو شهيد، والغريق شهيد".', 'The Messenger of Allah (ﷺ) said, "Whom do you reckon to be martyr amongst you?" The Companions replied: "The one who is killed in Allah''s way." He said, "In that case, the martyrs among my people would be few." The Companions asked: "O Messenger of Allah! Then who are the martyrs?" He replied, "He who is killed in the way of Allah is a martyr; he who dies naturally in the Cause of Allah is a martyr; he who dies of plague is a martyr; and he who dies of a belly disease is a martyr; and he who is drowned is a martyr.".This Hadith shows the care Allah has for this Ummah, which is the best Ummah of mankind. (Editor''s Note)', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1354', 'Riyad as-Salihin 1354', 'ریاض الصالحین 1354', 'رواه مسلم', 'الشهداء في الجملة خمسة، الذي ضربه الطاعون ومات به وهو وباء فتاك، والذي يموت بمرض البطن، والذي يموت من الغرق وقد ركب البحر ركوبا غير محرم، أو في السيول والمسابح ونحوها، والذي يموت تحت الهدم كأن سقط عليه جدار، والمقتول في سبيل الله تعالى ، وهو أعلى الأنواع، وكذلك من مات في سبيل الله بسبب غير القتال، والشهداء الأربعة الأول شهداء في أحكام الآخرة لا الدنيا فيغسلون ويصلى عليهم، والعدد في الحديث ليس للحصر.', 'فضل الله ورحمته بعباده المؤمنين.
الشهداء قسمان : شهيد الدنيا، وشهيد الآخرة.
تصحيح المفاهيم الخاطئة المستقرة في أذهان المدعوين.
العدد في الحديث ليس للحصر.', 'الشهداء : جمع شهيد : وهم أصحاب درجة عالية في الجنة، والأصل عند الإطلاق أن يراد به المقتول في سبيل الله لإعلاء كلمة الله.
خمسة : أي خمسة أصناف.
المطعون : هو الذي مات بالطاعون.
المبطون : الذي يموت بمرض بطنه.
الغريق : أي من مات بالغرق.
صاحب الهدم : الذي مات تحت الهدم.
ومن مات في سبيل الله : أي في الجهاد بسبب غير القتل كأن سقط من فرسه أو مات حتف أنفه.
في البطن : أي بسبب داءٍ في البطن.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4971', false),
(21355, 2, 212, 1355, 'hadith', 'عن عبد الله بن عمرو بن العاص، رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: «من قتل دون ماله فهو شهيد».', 'The Messenger of Allah (ﷺ) said, "He who is killed while defending his property is a martyr.".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''As (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1355', 'Riyad as-Salihin 1355', 'ریاض الصالحین 1355', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21356, 2, 212, 1356, 'hadith', 'عن أبي الأعور سعيد بن زيد بن عمرو بن نفيل، أحد العشرة المشهود لهم بالجنة، رضي الله عنهم، قال: سمعت رسول الله صلى الله عليه وسلم يقول: «من قتل دون ماله فهو شهيد، ومن قتل دون دمه فهو شهيد، ومن قتل دون دينه فهو شهيد، ومن قتل دون عرضه فهو شهيد».', 'I heard the Messenger of Allah (ﷺ) saying: "He who dies while defending his property is a martyr; he who dies in defence of his own life is a martyr; and he who dies on defense of his faith is a martyr, he who dies in defence of his family is a martyr.".', 'أبي الأعور سعيد بن زيد بن عمرو بن نفيل، أحد العشرة المشهود لهم بالجنة رضي الله عنهم', 'Sa''id bin Zaid bin ''Amr bin Nufail (May Allah be pleased with him) reported, one of the ten Companions who were given the glad tidings of entering Jannah', 'صحيح', 'رياض الصالحين 1356', 'Riyad as-Salihin 1356', 'ریاض الصالحین 1356', 'رواه أبو داود والترمذي وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21357, 2, 212, 1357, 'hadith', 'عن أبي هريرة رضي الله عنه قال: جاء رجل إلى رسول الله صلى الله عليه وسلم فقال: يا رسول الله أرأيت إن جاء رجل يريد أخذ مالي؟ قال: "فلا تعطه مالك" قال: أرأيت إن قاتلني؟ قال: "قاتله" قال: أرأيت إن قتلني قال: "فأنت شهيد" قال: أرأيت إن قتلته؟ قال: "هو في النار".', 'A man came to the Messenger of Allah (ﷺ) and asked, "O Messenger of Allah! What shall I do if someone comes to me with the intention of taking away my property?" He replied, "Do not hand over it to him." The man asked, "What shall I do if he fights me?" The Messenger of Allah (ﷺ) said, "Then fight him." "What will be my position in the Hereafter if he has killed me?" The Messenger of Allah (ﷺ) replied, "In that case you are a martyr." The man asked: "What if I killed him?" The Messenger of Allah (ﷺ) replied, "He will be in the Hell- fire.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1357', 'Riyad as-Salihin 1357', 'ریاض الصالحین 1357', 'رواه مسلم', 'جاء رجل إلى النبي صلى الله عليه وسلم، فقال: 

يا رسول الله، أرأيت إن جاء رجل يريد أخذ مالي؟

قال: فلا يلزمك أن تستسلم له وتعطيَه مالَك، قال: 

أرأيت إن قاتلني؟ 

قال: يجوز لك مقاتلته، قال: 

أرأيت إن قتلني؟ 

قال: فأنت شهيد، قال: 

أرأيت إن قتلته؟ 

قال: هو مستحق أن يعاقب في النار يوم القيامة.', 'قال النووي: المدافعة عن الحريم فواجبة بلا خلاف، وفي المدافعة عن النفس بالقتل خلاف في مذهبنا ومذهب غيرنا، والمدافعة عن المال جائزة غير واجبة.
الحديث دليل على أن العلم قبل العمل، حيث سأل هذا الصحابي رسول الله صلى الله عليه وسلم عما يجب عليه قبل عمله.
ينبغي التدرج في دفع الصائل بالوعظ أو الاستغاثة قبل الشروع في قتاله، فإن شرع في قتاله فليكن همه دفعه لا قتله.
دَمُ المسلم وماله وعرضه حرام.
قال النووي: اعلم أن الشهيد ثلاثة أقسام؛ أحدها المقتول في حرب الكفار بسبب من أسباب القتال، فهذا له حكم الشهداء في ثواب الآخرة وفي أحكام الدنيا، وهو أنه لا يغسل ولا يصلى عليه، والثاني شهيد في الثواب دون أحكام الدنيا وهو المبطون، والمطعون، وصاحب الهدم، ومن قتل دون ماله، وغيرهم ممن جاءت الأحاديث الصحيحة بتسميته شهيدًا، فهذا يغسل ويصلى عليه وله في الآخرة ثواب الشهداء، ولا يلزم أن يكون مثل ثواب الأول، والثالث من غل في الغنيمة وشبهه من وردت الآثار بنفي تسميته شهيدًا إذا قتل في حرب الكفار، فهذا له حكم الشهداء في الدنيا فلا يغسل، ولا يصلى عليه، وليس له ثوابهم الكامل في الآخرة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3557', false),
(21358, 2, 212, 1358, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال لي رسول الله صلى الله عليه وسلم : «من أعتق رقبة مسلمة أعتق الله بكل عضو منه عضوًا منه من النار حتى فرجه بفرجه».', 'The Messenger of Allah (ﷺ) said, "He who sets free a Muslim slave, Allah will deliver from the fire of Hell every limb of his body in return for every limb of the slave''s body, even his private parts.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1358', 'Riyad as-Salihin 1358', 'ریاض الصالحین 1358', 'متفق عليه', 'في هذا الحديث بيان فضل تحرير الرقاب المسلمة، وأنَّ من أعتق رقبة فكأنما أعتق كل بدنه من النار، وأنَّ في تحرير الرقاب تحقيقُ العزة للمسلمين بإزالة ذلّ العبودية عنهم.', 'الحث على عتق الرقاب المسلمة.
ينبغي أن يكون العتيق كاملاً ليحصل الاستيعاب.
أنَّ عتق الذَّكر أفضل من الأنثى؛ لأن في عتق الذكر من المعاني العامة ما ليس في الأنثى كصلاحيته للقضاء والجهاد وغير ذلك.', 'أعتق : حرَّر نفساً من الرق.
رقبة : النفس المملوكة.
بكل عضو منه : بدل كل عضو من المعتَق.
عضوا منه : جزءأ من بدن المعتِق.
حتى فرجه بفرجه : حتى يكون خَلاص فرجه من النار بدل فرج المعتَق.
النار : هي دار العذاب والنكال أعدها الله لمن عصاه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6396', false),
(21359, 2, 212, 1359, 'hadith', 'عن أبي ذر رضي الله عنه قال: قلت يا رسول الله أي الأعمال أفضل؟ قال: "الإيمان بالله، والجهاد في سبيل الله" قلت: أي الرقاب أفضل؟ قال: "أنفسها عند أهلها وأكثرها ثمنًا".', 'I asked the Messenger of Allah (ﷺ), "Which deed is most excellent?" He replied, "Faith in Allah and Jihad in His path." I then asked, "Which slaves are most excellent (to set free)?" He replied, "Those who are held in high esteem by their people and whose value is higher.".', 'أبي ذر رضي الله عنه', 'Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1359', 'Riyad as-Salihin 1359', 'ریاض الصالحین 1359', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21360, 2, 212, 1360, 'hadith', 'عن المعرور بن سويد قال: رأيت أبا ذر رضي الله عنه وعليه حلة وعلى غلامه مثلها، فسألته عن ذلك فذكر أنه ساب رجلا على عهد رسول الله صلى الله عليه وسلم فعيره بأمه فقال النبي صلى الله عليه وسلم : "إنك امرؤ فيك جاهلية" : هم إخوانكم، وخولكم جعلهم الله تحت أيديكم فمن كان أخوه تحت يده فليطعمه مما يأكل ويلبسه مما يلبس ولا تكلفوهم ما يغلبهم، فإن كلفتموهم فأعينوهم".', 'I saw Abu Dharr (May Allah be pleased with him) wearing a nice gown, and his slave was also wearing one similar to it. I asked him about it, and he said that he had exchanged harsh words with a person during the lifetime of the Messenger of Allah (ﷺ) and put him to shame by making a reference to his mother. That person came to the Messenger of Allah (ﷺ) and made mention of that to him. Thereupon the Messenger of Allah said, "You are a person who has remnants of the ''Days of Ignorance'' in you. Your slaves are your brothers. Allah has placed them under your authority. He who has his brother under him, should feed him from whatever he eats, and dress him with whatever he wears, and do not burden them (assign burdensome task to them) beyond their capacity; and if you burden them then help them.".', 'المعرور بن سويد قال: رأيت أبا ذر رضي الله عنه', 'Al-Ma''rur bin Suwaid (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1360', 'Riyad as-Salihin 1360', 'ریاض الصالحین 1360', 'متفق عليه', 'في هذا الحديث الحث على معاملة المماليك معاملة حسنة خاصة في الملبس والمأكل، وألا يكلفوهم فوق طاقتهم إلا إذا ساعدوهم في هذا التكليف، وفيه الوعيد الشديد لمن يعيرهم ويحقرهم؛ لأنهم إخوان لنا في الدين.', 'التحذير من التخلق بأخلاق الجاهلية كالعصبية والتفاخر بالأنساب.
تحقيق المساواة في الإسلام وأنَّ الناس جميعاً أخوة، ولا تفاضل بينهم إلا بالتقوى.
بيان أخطاء المدعو وتوجيهه.
الحث على الإحسان إلى الخدم والعمال.
حرص صحابة رسول الله على الاستجابة لمراد رسول الله –صلى الله عليه وسلم-، وتطبيق سنته على أنفسهم ومن يعولونهم.
كل ما كان من أمر الجاهلية فهو مذموم.
أن الرجل -مع فضله وعلمه ودينه- قد يكون فيه بعض هذه الخصال المسماة بجاهلية، ولا يوجب ذلك كفره ولا فسقه.
النهي عن سب الرقيق وتعييرهم بمن ولدهم، والحث على الإحسان والرفق بهم، ويلتحق في الرقيق من في معناهم من أجير وغيره.', 'حُلَّة : ثوب مركب من ظهارة وبطانة من جنس واحد، وهو قطعتان.
غلامه : مملوكه.
مثلها : أي: حلة مثل حلته.
فسألته عن ذلك : أي: عن سبب مساواته مع عبده في اللباس خلافاً لمألوف الناس من التفاوت بينهما.
سابَّ : أي: شاتم.
رجلاً : هو بلال –رضي الله عنه-.
عهد : زمن.
فَعَيَّره بأمه : نسب إليه القبح، حيث قال له : يا ابن السوداء.
فيك جاهلية : أي: خلق من أخلاق الجاهلية.
هُم : أي: الأرقاء.
إِخْوَانُكُمْ : أي: في الدين.
خَوَلُكُمْ : حشم الرجل وأتباعه، ويقع على العبد والأَمة.
جعلهم الله : صيرهم.
تحت أيديكم : تملكون التصرف بهم.
مما يأكل :  من جنس ما يأكل.
تُكَلِّفُوهُمْ : تُلزموهم بما فيه كلفة.
مَا يَغْلِبُهُمْ : ما يعجزون عنه.
فَإِنْ كَلَّفْتُمُوهُمْ : أي: ما يغلبهم.
فَأَعِينُوهُمْ : أي: ليرتفع عنهم بعض التعب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6407', false)
on conflict (id) do update set collection_id = excluded.collection_id, chapter_id = excluded.chapter_id, number_in_book = excluded.number_in_book, kind = excluded.kind, arabic = excluded.arabic, translation_en = excluded.translation_en, narrator_ar = excluded.narrator_ar, narrator_en = excluded.narrator_en, grade_ar = excluded.grade_ar, reference_ar = excluded.reference_ar, reference_en = excluded.reference_en, reference_ur = excluded.reference_ur, full_ref_ar = excluded.full_ref_ar, explanation_ar = excluded.explanation_ar, benefits_ar = excluded.benefits_ar, word_meanings_ar = excluded.word_meanings_ar, source = excluded.source, source_ref = excluded.source_ref, daily_ok = excluded.daily_ok, review_note = excluded.review_note, deleted = false;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21361, 2, 212, 1361, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إذا أتى أحدكم خادمه بطعامه، فإن لم يجلسه معه فليناوله لقمة أو لقمتين أو أُكلة أو أُكلتين فإنه ولي علاجه» ((رواه البخاري)). (9)', 'The Messenger of Allah (ﷺ) said, "When your servant brings food for you and you do not seat him with you, you should at least give him a morsel or two out of it because he has prepared it himself.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1361', 'Riyad as-Salihin 1361', 'ریاض الصالحین 1361', null, 'في هذا الحديث أن الخادم أو المملوك إذا أصلح طعاماً لسيده، فمن المروءة وحسن المعاملة أن يُطعمَه سيده من هذا الطعام ولا يحرمُه منه وقد تعب فيه، وقد أصلحه وأحضره، فلا يليق بالمروءة والكرم وحُسن المعاملة أن هذا المملوك لا يذوق من الطعام، بل يعطيه منه ما يُطيِّبُ نفسَه ويردُّ تطلُّعه.', 'الحث على مكارم الأخلاق, والأمر بالتواضع وترك التكبر على العبد والخادم.
الأفضل لصاحب البيت أن يؤاكل خدمه، ومماليكه، وضيوفه الصغار، ولا يترفَّع، ولا يتكبَّر عن مؤاكلتهم ومؤانستهم، وأن يكون ذلك باحتشام.
الأفضل والأكمل أن يكون طعام المخدوم والخادم واحدًا.
جواز استخدام الغير.
أن الخادم مؤتمن على طعام السيد.', 'خَادِمُه : مَن يقوم بحاجته.
لُقْمَة : واحدة اللُّقَم، واللقم: هي ما يهيئه الإنسان من الطعام للالتقام.
ولي علاجه : أي علاج الطعام عند تحصيل آلاته وتحمل مشقة حرّه ودخانه عند الطبخ وشقّت به نفسه وشم رائحته.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/58192', false),
(21362, 2, 212, 1362, 'hadith', 'عن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «إن العبد إذا نصح لسيده، وأحسن عبادة الله، فله أجره مرتين».', 'I heard the Messenger of Allah (ﷺ) saying, "When a slave is sincere to his master and worships Allah well, He will have a double reward."', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1362', 'Riyad as-Salihin 1362', 'ریاض الصالحین 1362', 'متفق عليه', 'إذا قام العبد بما وجب عليه لسيده من خدمته وطاعته بالمعروف وبذل النصيحة له وقام بحق الله تعالى من أداء ما افترضه الله عليه واجتنب ما نهاه عنه، كان له الأجر مرتين يوم القيامة؛ لأنه مُكَلَّف بأمرين:
الأول: حق السيد، فإذا قام بحق سيده كان له أجر.
والثاني: أجر طاعة ربِّه، فإذا أطاع العبد ربَّه كان له أجر.', 'فضل المملوك الذي يؤدي حق الله وحق مَوَاليه.
نصيحة العَبد لسيده تشمل أداء حقه في الخدمة، والطاعة وحفظ المال؛ لأن العبد رَاعٍ في مال سيده، وهو مسؤول عن رعيته.
من اتصف بذلك، فله أجره مرتين.
مواساة الضعفاء كالعبيد ومن في معناهم، وتطييب خاطرهم وحثهم على الصبر على ما امتحنوا به، وأن يحتسبوا ذلك عند ربهم.', 'نصح لسيده : قام بخدمته قدر طاقته، وحسب استطاعته، وحفظ له ماله.
أحسن عبادة الله : جاء بها مستوفية للأركان والشروط والآداب.
الذي عليه : ما وجب عليه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3607', false),
(21363, 2, 212, 1363, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «للعبد المملوك المصلح أجران، والذي نفس أبي هريرة بيده لولا الجهاد في سبيل الله والحج، وبر أمي لأحببت أن أموت وأنا مملوك».', 'The Messenger of Allah (ﷺ) said, "The faithful and diligent slave will have a double reward." (Abu Hurairah added:) By Him in Whose Hand the soul of Abu Hurairah is! but for Jihad in the Cause of Allah, and Hajj and kindness to my mother, I would have preferred to die as a slave..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1363', 'Riyad as-Salihin 1363', 'ریاض الصالحین 1363', 'متفق عليه', 'قال أبو هريرة رضي الله عنه : قال رسول الله صلى الله عليه وسلم : للعبد المملوك الناصح لسيده والقائم بحق ربه أجران؛ لقيامه بحق الله تعالى من العبادات وقيامه بحق سيده من الخدمة.
ثم أخبر أبو هريرة رضي الله عنه أنه لولا أن المملوك لا جهاد عليه، ولولا قيامه ببر أمه بالنفقة والخدمة، لأحب أن يموت وهو مملوك لما فيه من أجر.', 'فضل المملوك الذي يُؤدي حق الله وحق مواليه.
صلاح العبد يكون بإحسان العبادة والنصح للسيد.
فضل الجهاد والحج والحث على بر الوالدين وخاصة الأم.
العبد المملوك لا جهاد عليه ولا حج في حال العبودية.
فضل أبي هريرة -رضي الله عنه-.
مواساة الضعفاء من العبيد ومن في معناهم وتطييب خاطرهم وحثهم على الصبر على ما امتحنوا به وأن يحتسبوا ذلك عند ربهم -تبارك وتعالى-.', 'المصلح : من الصلاح، وهو إحسان العبادة والنصح للسيد.
لولا الجهاد : لولا فضل القيام بأعمال الجهاد وأنَّ الرقّ يمنع منها.
وأنا مملوك : أي: لأنال الأجر مضاعفاً.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6388', false),
(21364, 2, 212, 1364, 'hadith', 'عن أبي موسى الأشعري قال: قال رسول الله صلى الله عليه وسلم : «المملوك الذي يحسن عبادة ربه ويؤدي إلى سيده الذي عليه من الحق، والنصيحة والطاعة له أجران».', 'The Messenger of Allah (ﷺ) said, "A slave who worships his Rubb (Allah) well and discharges efficiently and faithfully the duties which are assigned to him by his master, will have a double reward.".', null, 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1364', 'Riyad as-Salihin 1364', 'ریاض الصالحین 1364', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21365, 2, 212, 1365, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم : «ثلاثة لهم أجران: رجل من أهل الكتاب آمن بنبيه، وآمن بمحمد، والعبد المملوك إذا أدى حق الله، وحق مواليه، ورجل كانت له أمة فأدبها فأحسن تأديبها وعلمها فأحسن تعليمها، ثم أعتقها فتزوجها فله أجران».', 'The Messenger of Allah (ﷺ) said, "Three kinds of people will have a double reward: A man from the People of the Book who believes in his Prophet and (also) believes in Muhammad; a slave who discharges properly the duties towards Allah and towards his master; and a man who possesses a slave-girl and teaches her manners, educates her well, and frees her and then marries her.".', null, 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1365', 'Riyad as-Salihin 1365', 'ریاض الصالحین 1365', 'متفق عليه', 'ثلاثة أصناف من البشر يُضاعف لهم الأجر مرتين يوم القيامة، ثم ذكرهم بقوله: رجُلٌ من أهل الكتاب، أي من اليهود والنصارى، آمن بِنَبِيِّه الذي أرسل إليه سابقا، وهو موسى أو عيسى عليهما الصلاة والسلام، وذلك قبل بعثة النبي صلى الله عليه وسلم وقبل بلوغ دعوته. فلما بعث النبي صلى الله عليه وسلم ، وبلغته دعوته آمن به، فهذا له أجران، أجر على إيمانه برسوله الذي أرسله إليه أولاً، وأجر على إيمانه بمحمد صلى الله عليه وسلم ، والعَبْد المملوك إذا قام بعبادة الله تعالى وأدى ما يكلفه به سيده على أحسن وجه فله أجران، ورجل كانت عنده جارية مملوكة فربَّاها تربية صالحة، وعلمها أمور دينها من حلال وحرام، ثم حررها من العبودية، ثم تزوجها، فله أجران: 
الأجر الأول: على تعليمها وعتقها.
والأجر الثاني: على إحسانه إليها بعد أن أعتقها لم يضيعها، بل تزوجها وكفَّها وأحصن فرجها', 'فضل العبد المملوك الصالح الناصح، ومضاعفة أجره عند الله لتحمله لما يدخل عليه من المشقة في قيامه بعبادة ربه، واشتغاله بخدمة سيده.
مواساة الضعفاء كالعبيد ومن في معناهم وتطييب خاطرهم وحثهم على الصبر على ما امتحنوا به، وأن يحتسبوا ذلك عند ربهم تبارك وتعالى.
حث المسلمين على العناية بمن في أيديهم من المماليك، وإحسان تربيتهم، وتعليمهم ما ينفعهم.
حث أهل الكتاب للدخول في الإسلام ليكون لهم فضل الإيمان بنبيهم، وفضل الإيمان برسالة محمد -صلى الله عليه وسلم- فيكون أجرهم مضاعفًا.
من تزوج أمته بعد عِتقها؛ فله أجران.', 'مواليه : جمع مولى، وهو المالك للعبد
أَمَة : امرأة مملوكة', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3697', false),
(21366, 2, 212, 1366, 'hadith', 'عن معقل بن يسار رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «العبادة في الهرج كهجرة إلي».', 'The Messenger of Allah (ﷺ) said, "The reward of worship performed at a time of trials is equal in reward to an emigration to me."', 'معقل بن يسار رضي الله عنه', 'Ma''qil bin Yasar (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1366', 'Riyad as-Salihin 1366', 'ریاض الصالحین 1366', 'رواه مسلم', 'معنى الحديث: أن المتمسك بالعبادة في زمن كثرة الفتن واختلاط الأمور والاقتتال فضله كفضل من هاجر إلى النبي صلى الله عليه وسلم قبل فتح مكة؛ لأنه وافقه من حيث أن المهاجر فَرَّ بدينه ممن يَصُدُّه عنه للاعتصام بالنبي صلى الله عليه وسلم وكذا المنقطع في عبادة الله تعالى فَرَّ من الناس بِدِينه إلى الاعتصام بعبادة ربِّه، فهو في الحقيقة قد هاجر إلى ربِّه، وفرَّ من جميع خلقه.', 'الحث على العبادة والإقبال على الله تعالى أيام الفتن.
فضل العبادة زمن الفتن.
ينبغي للمسلم اعتزال مواطن الفتن والغفلة.', 'الهرج : الفتنة واختلاط أمور الناس والقتال.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3592', false),
(21367, 2, 212, 1367, 'hadith', 'عن أبي هريرة رضي الله عنه أن رجلا أتى النبي صلى الله عليه وسلم يتقاضاه فأغلظ له فهم به أصحابه، فقال رسول الله صلى الله عليه وسلم : "دعوه فإن لصاحب الحق مقالا" ثم قال: "أعطوه سنا مثل سنه" قالوا: يا رسول الله لا نجد إلا أمثل من سنه، قال: "أعطوه فإن خيركم أحسنكم قضاء".', 'A man demanded of the Prophet (ﷺ) for repayment of a loan and was harsh to him. His Companions were about to attack him, but he (ﷺ) said, "Leave him, as the creditor is entitled to make a demand. Give him a camel of the same age as the camel that is due to him." They said: "We find a better camel senior to it in age." He (ﷺ) said, "Then buy it and give it to him; verily the best of you is the one who is the best in discharging his obligations (repayment of loans).".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1367', 'Riyad as-Salihin 1367', 'ریاض الصالحین 1367', 'متفق عليه', 'كان لرجل دين على النبي صلى الله عليه وسلم ، وكان النبي صلى الله عليه وسلم قد استقرض من ذلك الرجل ناقة صغيرة، فجاء إلى النبي صلى الله عليه وسلم يطلب منه قضاء دَيْنِه وأغلظ عليه في طلبه، فأراد أصحاب النبي صلى الله عليه وسلم أن يضربوه بسبب غلظته للنبي صلى الله عليه وسلم وسوء أدبه معه، فقال رسول الله صلى الله عليه وسلم : اتركوه يقول ما يشاء ولا تتعرضوا له بشيء؛ فإن صاحب الحق له حق في مطالبة غريمه بقضاء الدين ونحوه، لكن مع التزام أدب المطالبة، أما السَّب والشَّتم والتجريح، فليس من أخلاق المسلمين.
ثم أمَر النبي صلى الله عليه وسلم بعض الصحابة أن يُعطيه بعيرًا مساويا لبعيره في السِّن.
فقالوا: لا نجد إلا بعيرًا أكبر من بعيره. فقال: أعطوه بعيرًا أكبر من بعيره؛ فإن أفضلكم في معاملة الناس، وأكثركم ثوابًا أحسنكم قضاءً للحقوق التي عليه دينًا أو غيره.', 'حسن خلق النبي -صلى الله عليه وسلم- وعظم حلمه وتواضعه وإنْصَافه.
من عليه دين لا ينبغي له مجافاة صاحب الحق.
جواز توكيل الحاضر في البلد بغير عذر.
جواز التوكيل في قضاء الديون، ولا يُعَدُّ ذلك من المماطلة.
الاقتراض في البر والطاعات وكذا في الأمور المباحة لا يُعَاب.
جواز الاقتراض للحاجة.
جواز استقراض الإبل ويلتحق بها جميع الحيوانات.
الحث على حسن المعاملة، واللطف في القول ولو كان الإنسان صاحب حق.
جواز المطالبة بالدَّين إذا حَلَّ أجله.
يستحب لمن كان عليه دين أن يعطي الدائن زيادة على حقه عند وفائه، دون اشتراط الزيادة؛ لأن اشتراطها ربا.', 'يتقاضاه : يطلب منه قضاء دينه.
فهم به أصحابه : أرادوا أن يؤذوه بالقول أو الفعل لكن لم يفعلوا أدبًا مع النبي -صلى الله عليه وسلم-.
مقالًا : صولة الطلب وقوة الحجة، لكن مع مراعاة الأدب المشروع.
سنًّا : جملًا ذا سن.
أمثل : أعلى.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3628', false),
(21368, 2, 212, 1368, 'hadith', 'عن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «رحم الله رجلا سمحًا إذا باع وإذا اشترى وإذا اقتضى».', 'The Messenger of Allah (ﷺ) said, "May Allah show mercy to a man who adopts a kind attitude when he sells, buys and demands for the repayment of loans.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1368', 'Riyad as-Salihin 1368', 'ریاض الصالحین 1368', 'رواه البخاري', 'دعا النبي صلى الله عليه وسلم بالرحمة لكل من كان:

سهلًا جَوَادًا سَخِيًّا في بيعِه، فلا يُشدِّد على المشتري في سعرها ويعامله بخُلُقٍ حَسَن.


سهلًا جوادًا سَخِيًّا إذا اشترى، فلا يَبْخَس ويُقَلِّل من قيمة البِضَاعَة.


سهلًا جوادًا سخيًا إذا طَالَبَ بقضاءِ الدُّيون التي له، فلا يُشدِّد على الفقير والمُحتاج، بل يُطالِبه برفق ولُطف، ويُنْظِر المُعسر.', 'مِن مَقاصد الشريعة الحِفاظ على ما يُصلِحُ العلاقاتِ بين الناس.
الترغيب في استعمال معالي الأخلاق في المعاملات بين الناس من البيع والشراء ونحو ذلك.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3716', false),
(21369, 2, 212, 1369, 'hadith', 'عن أبي قتادة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «من سره أن ينجيه الله من كرب يوم القيامة، فلينفس عن معسر أو يضع عنه».', 'The Messenger of Allah (ﷺ) said, "He who likes Allah to deliver him from the calamities of the Day of Resurrection, let him either give respite to a debtor or grant him remission (of loans) in straitened circumstances.".', 'أبي قتادة رضي الله عنه', 'Abu Qatadah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1369', 'Riyad as-Salihin 1369', 'ریاض الصالحین 1369', 'رواه مسلم', 'كان أبو قتادة الأنصاري رضي الله عنه يبحث عن مَدِيْنٍ له يَخْتَبِئ عنه، فوجده، فقال الغَريم: إني مُعسر، وليس عندي مال لأقضي دينك. 

فاستحلفه أبو قتادة رضي الله عنه بالله أنه لا مال عنده؟ 

فحلف بالله أنه صادق فيما يقول.

فقال أبو قتادة رضي الله عنه إنه سمع النبي صلى الله عليه وسلم يقول: 

مَن سرّه وأفرحه أن ينجيَه الله من كُرب يوم القيامة وشدائدها وأهوالها، فلينفِّس عن معسر، بأن يَمُدَّ ويؤخّر المطالبة بالدَّيْن، أو يُسقط بعض الدين أو كله.', 'استحباب إنظار المُعْسر إلى مَيْسرة، أو وضع الدَّين عنه، كله أو بعضه.
من نَفَّس عن مؤمن من كُرب الدنيا نَفَّس الله عليه من كُرَب يوم القيامة، والجزاء من جِنس العمل.
القاعدة: أن الفرائض أفضل من النوافل، لكن في بعض الأحيان تكون النافلة أفضل من الفريضة، وإسقاط الدين عن المعسر نافلة، والصبر عليه والانتظار وعدم المطالبة هذا فريضة، والنافلة أفضل من الفريضة هنا.
الحديث في حق من كان معسرًا، فهذا معذور، أما المُماطِل الذي عنده مال، فقد جاء عن النبي صلى الله عليه وسلم أنه قال: "مَطْلُ الغني ظُلْم".', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4195', false),
(21370, 2, 212, 1370, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «كان رجل يداين الناس، وكان يقول لفتاه: إذا أتيت معسرا فتجاوز عنه، لعل الله أن يتجاوز عنا فلقي الله فتجاوز عنه».', 'The Messenger of Allah (ﷺ) said, "There was a person who used to loan money to the people and he used to say to his servant: ''When an insolvent person comes to you, show him leniency so that Allah may forbear our faults.'' So when he met Allah (i.e., when he died), Allah forgave him.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1370', 'Riyad as-Salihin 1370', 'ریاض الصالحین 1370', 'متفق عليه', 'يُخبِرُ النبيُّ صلى الله عليه وسلم عن رجُلٍ كان يتعامل مع الناس بالقَرْض، أو يَبِيعُهم بالآجِل، وكان يقول لغلامه الذي يَتَقاضى الدُّيون التي عند الناس: 
إذا أتيتَ مَدِيْنًا ولم يكن عنده ما يقضي به الدَّين الذي عليه لعجزه "فَتَجَاوَزْ عنه"؛ إما بإمهالِه وعدم الإلحاح في المطالبة، أو بقبول ما عنده ولو مع ما فيه مِن نَقْص، وذلك رَغْبةٌ منه وطَمَعٌ في أنْ يتجاوزَ اللهُ عنه ويعفوَ عنه.

فلما ماتَ عفا اللهُ عنه وتجاوزَ عن سيئاتِه.', 'الإحسان في معاملة الناس والعفو عنهم والتجاوز عن معسرهم من أعظم أسباب نجاة العبد يوم القيامة.
الإحسان إلى الخلق والإخلاص لله والرجاء في رحمته من أسباب مغفرة الذنوب.', 'يداين: يكثر من التعامل مع الناس بالدين.
فتاه: غلامه الذي يكلفه بالعمل.
أتيت معسرًا: لمطالبته بما عليه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3753', false),
(21371, 2, 212, 1371, 'hadith', 'عن أبي مسعود البدري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "حوسب رجل ممن كان قبلكم فلم يوجد له من الخير شيء إلا أنه كان يخالط الناس، وكان موسرًا وكان يأمر غلمانه أن يتجاوزوا عن المعسر قال الله عز وجل: "نحن أحق بذلك منه، تجاوزوا عنه".', 'The Messenger of Allah (ﷺ) said, "A person from amongst the people who lived before you was called to account by Allah on the Day of Resurrection. No good deeds were found in his credit except that he being a rich man had (financial) dealings with people and had commanded his servants to show leniency to those who were in straitened circumstances. Upon this Allah, the Exalted, and Majestic said: ''I am more entitled to this attribute, so waive (his faults)."''.', 'أبي مسعود البدري رضي الله عنه', 'Abu Mas''ud Al-Badri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1371', 'Riyad as-Salihin 1371', 'ریاض الصالحین 1371', 'رواه مسلم', '"حُوسِب رجُل" أي حاسبه الله تعالى على أعماله التي قدمها.
"ممن كان قَبْلَكُمْ" من الأمم السابقة، "فلم يُوجد له من الخَيْر شَيء" أي: من الأعمال الصالحة المقربة إلى الله تعالى .
"إلا أنه كان يُخَالط الناس وكان مُوسِرًا" أي يتعامل معهم بالبيوع والمداينة وكان غنياً.
"وكان يأمُر غِلْمَانَه أن يَتَجَاوَزُوا عن المُعْسِر" أي: يأمر غلمانه عند تحصيل الديون التي عند الناس، أن يتسامحوا مع المُعسر الفقير المديون الذي ليس عنده القدرة على القضاء بأن ينظروه إلى الميسرة، أو يَحطوا عنه من الدَّين.
"قال الله عز وجل : نحن أحق بذلك منه؛ تَجَاوزُوا عنه" أي: عفا الله عنه، مكافأة له على إحسانه بالناس، والرفق بهم، والتيسير عليهم.', 'فيه أن التسامح مع المَدِين المُعْسِر وتفريج كُرْبته من أفضل الأعمال.
الحث على مخالطة الناس والتعامل معهم.
شَرعُ من قبلنا شَرْعٌ لنا إذا لم يخالف شرعِنا.
الجزاء من جنس العمل.
الحث على التسامح مع المدين إما بالإنظار أو العفو الكلي.
فضل تيسير مصالح الناس.
جواز التعامل بالدَّين.
صحة تبرع الوكيل إذا كان بإذن المُوَكِّل.', 'حوسب : أي بعد موته في قبره أو أنه إخبار عما سيكون يوم القيامة بصيغة الماضي.
يخالط الناس : يعاملهم بالبيوع والمداينة.
موسرًا : غنيًّا.
غلمانه : جمع غلام والمراد به الخادم.
المعسر : الذي عجز عن قضاء ما عليه من الدين في الحال.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3707', false),
(21372, 2, 212, 1372, 'hadith', 'عن حذيفة رضي الله عنه قال: أتي الله تعالى بعبد من عباده آتاه الله مالا فقال له ماذا عملت في الدنيا؟ قال: ولا يكتمون الله حديثا- قال: يا رب آتيتني مالك فكنت أبايع الناس، وكان من خلقي الجواز فكنت أتيسر على الموسر وأنظر المعسر فقال الله تعالى: " "أنا أحق بذا منك، تجاوزوا عن عبدي" فقال عقبة بن عامر، وأبو مسعود الأنصاري رضي الله عنهما هكذا سمعناه من في رسول الله صلى الله عليه وسلم.', 'The Messenger of Allah (ﷺ) said, "A slave of Allah whom He had endowed with wealth, will be brought before Him. Allah will ask him: ''What did you do in the world?'' (They cannot conceal anything from Allah.) He will say: ''O my Rubb, You endowed me with Your wealth; I used to enter into transactions with people and it was my nature to be lenient to the insolvent ones. I used to give respite to those who were in straitened circumstances.'' Whereupon Allah will say: ''I am more entitled than you to do this. So forgive my slave''." ''Uqbah bin ''Amir and Abu Mas''ud Al- Ansari (May Allah be pleased with them) said, "Thus we heard it from the Messenger of Allah (ﷺ).".', 'حذيفة رضي الله عنه', 'Hudhaifah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1372', 'Riyad as-Salihin 1372', 'ریاض الصالحین 1372', 'رواه مسلم', 'يخبر حذيفة رضي الله عنه أنه يُؤتى برجل من عباد الله تعالى يوم القيامة آتاه الله مالًا، فيسأله ربه عن ماله: ماذا عمل به ؟ قال: أي حذيفة رضي الله عنه : "ولَا يَكْتُمُونَ اللهَ حَدِيثًا" أي: لا يستطيعون إخفاء شيء عن الله تعالى يوم القيامة، كما قال تعالى: (يوم تشهد عليهم ألسنتهم وأيديهم وأرجلهم بما كانوا يعملون). "قال: يا رَبِّ آتَيْتَنِي مَالَك، فكنت أُبَايعُ الناس" أي: أعَامل الناس بالبيوع والمداينة وكان مما اتصفت به من أخلاق: الجواز، ثم فسره بقوله: "فكنت أَتَيَسَّرُ على المُوسِرِ" أي: أُسَهِّل عليه وأقبل منه ما جاء مع نقص يسير. "وأنْظِر المُعْسِر" أي: أصبر على المُعْسِر، فلا أطالبه وأفسح له في الأجل. فقال الله تعالى: "أنا أحَقُّ بِذَا مِنك" أي: فما دمت قد تجاوزت عن عبادي وتخلقت بخلقي، فنحن أحق بالتجاوز والعفو عنك. "تَجَاوزُوا عن عَبْدِي"
أي: عفا الله عنه، وغَفَر له ما كان من سيئاته، بسبب عفوه وسماحته وحسن معاملته لعباد الله تعالى، وهل جزاء الإحسان إلا الإحسان. "فقال عُقْبَة بن عَامر، وأبو مسعود الأنصاري رضي الله عنهما : هكذا سَمِعْنَاه من فِيِّ رسول الله صلى الله عليه وسلم ." والمعنى: أنهما سمعا ما حدث به حذيفة رضي الله عنه من النبي صلى الله عليه وسلم كما حدث به حذيفة رضي الله عنه من غير زيادة ولا نقص.', 'أن الله تعالى لا تخفى عليه خافية.
ضبط حذيفة -رضي الله عنه- للحديث.
أن من فَرَّج على أخيه كُربة من كُرب الدنيا فرَّج الله عنه كُربة من كرب يوم القيامة.
أن الجزاء من جنس العمل  فكما أن الدائن خلص المدين من ضيق الدين في الدنيا خلصه الله يوم القيامة من ضيق وكرب يوم القيامة.', 'لَا يَكْتُمُونَ اللهَ حَدِيثًا : لا يستطيعون أن يخفوا شيئًا عنه.
أُبَايعُ الناس : أتعامل مع الناس بالبيع.
الجَوَاز : أي: الصبر على المُعْسِر وقبول ما جاء به المُوسِر.
أَتَيَسَّرُ على المُوسِرِ : آخذ ما تيسر؛ بأن أقبل ما فيه نقص قليل أو عيب يسير.
أنْظِر : أمْهِل من الإنظار، وهو التأخير والإمْهَال.
المُعْسِر : الذي عجز عن قضاء ما عليه من الدَّين في الحال.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4232', false),
(21373, 2, 212, 1373, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من أنظر معسرًا أو وضع له، أظله الله يوم القيامة تحت ظل عرشه يوم لا ظل إلا ظله».', 'The Messenger of Allah (ﷺ) said, "He who gives respite to someone who is in straitened circumstances, or grants him remission, Allah will shelter him in the shade of His Throne, on the Day of Resurrection, when there will be no shade except its shade.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1373', 'Riyad as-Salihin 1373', 'ریاض الصالحین 1373', 'رواه الترمذي وقال: حديث حسن صحيح', 'أَخبَرَ النبيُّ عليه الصلاة والسلام أنّ مَن أمهل مديونًا أو حطَّ عنه من دَينه، فجزاؤه: أنّ الله يُظلُّه تحت عرشه يوم القيامة الذي تدنو فيه الشمس من رؤوس العباد ويشتدُّ عليهم حرُّها، 
فلا يجد أحدٌ ظِلًّا إلا مَن أَظله الله.', 'فضل التيسير على عباد الله تعالى، وأنه من الأسباب المُنجِيَة من أهوال يوم القيامة.
الجزاء من جنس العمل.', 'عرشه: العرش هو المخلوق العظيم الذي استوى عليه الرحمن، ولا يقدر قدرَه إلا الله عز وجل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4186', false),
(21374, 2, 212, 1374, 'hadith', 'عن جابر، رضي الله عنه أن النبي صلى الله عليه وسلم اشترى منه بعيرًا فوزن له فأرجح.', 'The Prophet (ﷺ) purchased a camel from me and weighed more than its price..', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1374', 'Riyad as-Salihin 1374', 'ریاض الصالحین 1374', 'متفق عليه', 'هذا الحديث له قصة، وهي هنا مختصرة، "أن النبي صلى الله عليه وسلم اشْتَرَى منه بَعِيراً" أي: أن النبي صلى الله عليه وسلم اشترى من جابر رضي الله عنه بعيراً.
"فَوَزَنَ له" أي: أن النبي صلى الله عليه وسلم وَزَن له ثَمن البعير، وهذا من باب التجوز، وإلا فإن حقيقة الوزَّان في هذا الحديث: بلال رضي الله عنه بأمر النبي صلى الله عليه وسلم كما هو في أصل الحديث: "فأمر بلالا أن يَزِن لي أوقية، فوزن لي بلال، فأرجح في الميزان" أي: زاد في الوَزْن أكثر مما يستحقه جابر رضي الله عنه من ثَمن البعير، وكانوا فيما سبق يتعاملون بالنقود وزناً لا عدداً وإن كانوا يتعاملون أيضا بها عدداً لكن الكثير وزناً.', 'جواز الزيادة على الثمن عند الأداء والرُّجْحان في الوزن.
جواز الرُّجْحان في الوزن.
فضل الزيادة غير المشروطة عند الوفاء بالدين.', 'أرْجَح : أعطاه أكثر من حقه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4231', false),
(21375, 2, 212, 1375, 'hadith', 'عن أبي صفوان سويد بن قيس، رضي الله عنه قال: جلبت أنا ومخرمة العبدي بزًا من هجر، فجاءنا النبي صلى الله عليه وسلم فساومنا سراويل، وعندي وزان يزن بالأجر، فقال النبي صلى الله عليه وسلم للوزان «زن وأرجح».', 'Makhramah Al-''Abdi and I procured some drapery from Hajar and brought them to Makkah. The Prophet (ﷺ) came and bargained with us for some trousers and we sold them to him. We had a person who weighed the cloth in order to fix the price. The Prophet (ﷺ) said to him, "Weigh and add a little to it.".', 'أبي صفوان سويد بن قيس رضي الله عنه', 'Abu Safwan Suwaid bin Qais (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1375', 'Riyad as-Salihin 1375', 'ریاض الصالحین 1375', 'رواه أبو داود والترمذي وقال: حديث حسن صحيح', 'أن صفوان بن سُوَيْدِ وَمَخْرَمَةُ العَبْدِيُّ رضي الله عنهما جاءا بثياب من بلدة يقال لها هجر. 
"فجاءنا النبي صلى الله عليه وسلم فَسَاوَمَنَا بسَرَاوِيلَ" أي: أراد النبي -صلى الله عليه وسلم- أن يشتري منهما سراويل، ففاصلهما في السِعر وفي رواية للنسائي: " فاشترى منَّا سراويل" ولم يذكر المفاصلة.
"وعندي وَزَّانٌ يَزِنُ بالأَجْر" أي: يوجد في السوق رجل عنده ميزان، والناس يزنون عنده ويعطونه أجرة على الوزن.
فقال النبي صلى الله عليه وسلم للوَزَّان: "زِنْ وأرْجِح" أي: أمر النبي صلى الله عليه وسلم الوَزَّان أن يزيد في الكِفة التي فيها السلع التي توزن بحيث تميل الكِفة وترجح على الأخرى، وليس معنى ذلك: أنها تميل ميلًا عظيمًا، فهذا قد يكون فيه ضرر على البائع، لكن يميل الميزان ميلاً يسيراً، بحيث يتحقق أن المشتري قد أخذ حقه من غير نقص، وذكر الوزن في هذا الحديث لا علاقة له بشراء السراويل، فإن السراويل لا توزن.', 'جواز المفاصلة شريطة ألا يكون في ذلك ما يُضَجِّر البائع.
يستحب للمشتري أن يتسامح مع البائع ويزيد له شيئا على الثمن المتفق عليه.
يستحب للبائع أن يتنازل عن شيء من الثمن أو يزيد شيئا في السلعة بعد الرضى بها.
جواز اتخاد الوزان وأخذ الأجرة على عمله.
جواز أن يطلب المشتري من البائع أن يرجح في الوَزْن.
بيان ما كان عليه النبي -صلى الله عليه وسلم- من تسامح وحسن معاملة، وكريم خلق.
جواز لبس السراويل.', 'جلبت : جلبه ساقه من موضع إلى آخر.
بزاً : البز : الثياب، أو متاع البيت من الثياب ونحوه.
هجر : اسم بلد قريبة من البحرين.
ساومنا : من المساومة وهي المجاذبة بين البائع والمشتري على السلعة وفصل ثمنها.
سروايل : لباس يغطي ما بين السرة والركبة وله أكمام كالبنطال ونحوه.
وزان يزن بالأجر : يأخذ على وزنه أجرة.
زن وأرجح : زن قدر الثمن المتفق عليه وزد شيئًا عليه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3737', false),
(21376, 2, 213, 1376, 'hadith', 'عن معاوية رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من يرد الله به خيرًا يفقه في الدين».', 'The Messenger of Allah said, "When Allah wishes good for someone, He bestows upon him the understanding of Deen.".', 'معاوية رضي الله عنه', 'Mu''awiyah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1376', 'Riyad as-Salihin 1376', 'ریاض الصالحین 1376', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21377, 2, 213, 1377, 'hadith', 'عن ابن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «لا حسد إلا في اثنتين: رجل آتاه الله مالا فسلطه على هلكته في الحق، ورجل آتاه الله الحكمة فهو يقضي بها ويعلمها».', 'The Prophet (ﷺ) said, "Envy is permitted only in two cases: A man whom Allah gives wealth, and he disposes of it rightfully, and a man to whom Allah gives knowledge which he applies and teaches it.".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1377', 'Riyad as-Salihin 1377', 'ریاض الصالحین 1377', 'متفق عليه', 'يُشير النبي صلى الله عليه وسلم هنا إلى أن الحَسَدَ أنواع مختلفة فمنه حسد مَذْمُوم محرم شرعًا، وهو أن يتمنى المرء زوال النعمة عن أخيه، وحسد مباح وهو أن يرى نعمة دنيوية عند غيره فيتمنى لنفسه مثلها، وحسد محمود مستحب شرعًا، وهو أن يرى نعمة دينية عند غيره فيتمناها لنفسه. وهو ما عناه النبي صلى الله عليه وسلم بقوله: "لا حَسَدَ إلا في اثنتين" أي أن الحسد تختلف أنواعه وأحكامه حسب اختلاف أنواعه ولا يكون محمودًا مستحبًا شرعيًا إلا في أمرين: 
الأمر الأول: أن يكون هناك رجل غني تقي، أعطاه الله مالا حلالا، فينفقه في سبيل الله تعالى، فيتمنى أن يكون مثله، ويَغْبِطَه على هذه النعمة. 
الأمر الثاني: أن يكون هناك رجل عالم، أعطاه الله علما نافعا يعمل به، ويعلمه لغيره، ويحكم به بين الناس، فيتمنى أن يكون مثله.', 'الحَسَدُ داء خطير يجب الابتعاد عنه والحذر منه.
حسد الغِبْطَة محمود إذا كان في وجوه الخير.
فضل الغني الذي لا يبخل بما آتاه الله .
الواجب شكر المُنْعِم على ما أنعم به على العبد وذلك بأن يضعها العبد في موضعها.
استحباب الإنفاق وبذل المال والخروج عنه بالكلية في وجوه الخير ما لم يؤد إلى حرمان الورثة أو سؤال الناس ونحو ذلك مما حَرَّمَه الشرع.
فضل العلم بأحكام الدين وتعليم الناس ودعوتهم إلى التفقه في الدين.', 'الحسد : الغبطة ، وهي: أن يتمنى مثله.
سلطه : مكنه الله من إنفاقه في وجوه الخير.
هلكته : وجوه إنفاقه ومجالات صرفه.
في الحق : في أنواع البر ونواحي الخير.
حكمة : وضع كل شيء في موضعه.
يقضي بها : يحكم ويفتي بين الناس بمقتضاها.
آناء : الآناء: الساعات', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3772', false),
(21378, 2, 213, 1378, 'hadith', 'عن أبي موسى رضي الله عنه قال: قال النبي صلى الله عليه وسلم : «مثل ما بعثني الله به من الهدى والعلم كمثل غيث أصاب أرضًا، فكانت منها طائفة طيبة قبلت الماء فأنبتت الكلأ، والعشب الكثير وكان منها أجادب أمسكت الماء، فنفع الله بها الناس، فشربوا منها وسقوا وزرعوا، وأصاب طائفة منها أخرى إنما هي قيعان لا تمسك ماء ولا تنبت كلأ فذلك مثل من فقه في دين الله ونفعه ما بعثني الله به وعلم، ومثل من لم يرفع بذلك رأسًا ولم يقبل هدى الله الذي أرسلت به».', 'The Messenger of Allah (ﷺ) said, "The guidance and knowledge with which Allah has sent me are like abundant rain which fell on a land. A fertile part of it absorbed the water and brought forth profuse herbage and pasture; and solid ground patches which retained the water by which Allah has benefited people, who drank from it, irrigated their crops and sowed their seeds; and another sandy plane which could neither retain the water nor produce herbage. Such is the similitude of the person who becomes well-versed in the religion of Allah and receives benefit from the Message entrusted to me by Allah, so he himself has learned and taught it to others; such is also the similitude of the person who has stubbornly and ignorantly rejected Allah''s Guidance with which I have been sent."', 'أبي موسى رضي الله عنه', 'Abu Musa (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1378', 'Riyad as-Salihin 1378', 'ریاض الصالحین 1378', 'متفق عليه', 'شَبّه النبي صلى الله عليه وسلم متعجبًا من ينتفع بما جاء به من الدلالة والطريق الذي يوصل للمطلوب، والعلم الشرعي بالأرض التي ينزل عليها المطر الكثير؛ فكانت أقسامًا ثلاثة: 

أولها: أرض نقية طيبة، تقبل ماء الأمطار، فتنبت النبات الكثير رطبًا ويابسًا، فانتفع الناس بها. 

وثانيها: أرض ممسكة للماء لكنها لا تنبت زرعًا، فهي تحفظ الماء لينتفع به الناس؛ فيشربون ويسقون مواشيهم وزروعهم. 

وثالثها: أرض مستوية ملساء لا تمسك ماء ولا تنبت زرعًا، فهي لم تنتفع بذلك الماء في نفسها، ولم ينتفع الناس منها. 

فكذا السامعين لما بُعث به النبي صلى الله عليه وسلم من العلم والهدى. 

فالأول: العالم المتفقه في دين الله، العامل بعلمه، المعلم لغيره؛ فهو بمنزلة الأرض الطيبة شربت فانتفعت في نفسها، وأنبتت فنفعت غيرها. 

والثاني: الحافظ للعلم لكن ليس له فهم واستنباط، فهو جامع للعلم، مستغرق لزمانه في ذلك، غير أنه لم يعمل بنوافله، أو لم يفقه ما جمع؛ فهو أداة لغيره، وهو بمنزلة الأرض التي يستقر فيها الماء فينتفع الناس به. 

والثالث: من يسمع العلم فلا يحفظه، ولا يعمل به، ولا ينقله لغيره؛ فهو بمنزلة الأرض السبخة أو الملساء التي لا نبات فيها ولا تقبل الماء أو تفسده على غيرها.', 'بيان فضل طلب العلم وتعليمه، والتحذير من الإعراض عنهما.
ضرب الأمثال لتقريب المعاني للناس.
قال القرطبي: فكما أن الغيث يحيي البلد الميت فكذا علوم الدين تحيي القلب الميت، ثم شبه السامعين له بالأرض المختلفة التي ينزل بها الغيث.
الناس في الأخذ بالعلم الشرعي مراتب.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4233', false),
(21379, 2, 213, 1379, 'hadith', 'عن سهل بن سعد رضي الله عنه أن النبي صلى الله عليه وسلم قال لعلي رضي الله عنه : «فوالله لأن يهدي الله بك رجلا واحدا خير من حمر النعم».', 'The Prophet (ﷺ) said to ''Ali (May Allah be pleased with him), "By Allah, if a single person is guided by Allah through you, it will be better for you than a whole lot of red camels.".', 'سهل بن سعد رضي الله عنه', 'Sahl bin Sa''d (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1379', 'Riyad as-Salihin 1379', 'ریاض الصالحین 1379', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21380, 2, 213, 1380, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنهما أن النبي صلى الله عليه وسلم قال: «بلغوا عني ولو آية وحدثوا عن بني إسرائيل ولا حرج، ومن كذب علي متعمدًا فليتبوأ مقعده من النار».', 'The Prophet (ﷺ) said, "Convey from me even an Ayah of the Qur''an; relate traditions from Banu Israel, and there is no restriction on that; but he who deliberately forges a lie against me let him have his abode in the Hell.".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''As (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1380', 'Riyad as-Salihin 1380', 'ریاض الصالحین 1380', 'رواه البخاري', 'يأمرُ النبيُّ صلى الله عليه وسلم بتبليغ العلم عنه من كتاب أو سنة، ولو كان الشيء قليلًا كآية من القرآن أو حديث، بشرط أن يكون عالمًا بما يبلِّغُ به ويدعو إليه. 
ثم بيَّن صلى الله عليه وسلم أنه لا بأس بالتحديث عن بني إسرائيل بما وقع لهم من وقائع بما لا يتعارض مع شرعنا. 
ثم حذَّر من الكذب عليه، وأنَّ من كذَب عليه متعمِّدًا فليتخذْ لنفسه مَنزلًا في النار.', 'الترغيب في تبليغ شريعة الله، وأن المرء عليه أنْ يؤديَ ما حفِظَ وفَهِمَ ولو كان يسيرًا.
وجوب طلب العلم الشرعي؛ ليتمكَّن من عبادة الله وتبليغ شريعته بصورة صحيحة.
وجوب التأكد من صحة أي حديث قبل تبليغه أو نشره حذرًا من الدخول في هذا الوعيد الشديد.
الحث على الصدق في الكلام والحيطة في الحديث، حتى لا يقع في الكذب، وخاصة في شرع الله عز وجل.', 'لا حرج: لا إثم ولا ذنب.
بنو إسرائيل: هم بنو يعقوب بن إسحاق بن إبراهيم، فإسرائيل لقب ليعقوب. والمراد أتباع دينهم من اليهود والنصارى.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3686', false),
(21381, 2, 213, 1381, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «ومن سلك طريقًا يلتمس فيه علما سهل الله له به طريقًا إلى الجنة».', 'The Messenger of Allah (ﷺ) said, "Allah makes the way to Jannah easy for him who treads the path in search of knowledge.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1381', 'Riyad as-Salihin 1381', 'ریاض الصالحین 1381', 'رواه مسلم', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ جَزاء المسلم عند الله مِن جِنْس ما يَعمله المسلم مع المسلمين؛ فمَن نفَّس وفرَّج وأزال وكَشَفَ عن مؤمنٍ كُربةً وشدة من كُرَب الدنيا، جازاه الله بأن ينفَّس عنه كربةً من كرب يوم القيامة.

ومَن يَسَّر على معسرٍ وسهَّل عليه وأزال عسرته، يسَّر الله عليه في الدنيا والآخرة. 

ومَن ستر مسلمًا كأن اطّلع منه على ما لا ينبغي إظهاره من الزّلات والعَثَرات، ستره الله في الدنيا والآخرة. 

والله يكون مُعينًا لِعَبدِه، ما كان العبد سائرًا في إعانة أخيه في مصالحه الدينية والدنيوية، والإعانة تكون بالدعاء والبدن والمال وغير ذلك. 

ومن مشى إلى تحصيل علمٍ شرعيٍ، قاصدًا به وجه الله تعالى؛ سهَّل الله له به طريقًا إلى الجنة. 

وما اجتمع قومٌ في بيتٍ من بيوت الله، يتلون كتاب الله ويتدارسونه بينهم، إلا نزلت عليهم الطمأنينة والوقار، وغطتهم وعمَّتهم رحمة الله، وحفَّتْهم الملائكة، وأثنى الله عليهم في المقرَّبين عنده، وكفى شرفًا ذِكرُ اللهِ العبدَ في الملأ الأعلى. 

ومَن كان عمله ناقصًا، لم يُلْحِقْه بمرتبة أصحاب الأعمال، فينبغي ألا يَتَّكل على شرف النسب وفضيلة الآباء ويُقَصّر في العمل.', 'قال ابن دقيق العيد: هذا حديث عظيم، جامع لأنواع من العلوم والقواعد والآداب، فيه فضل قضاء حوائج المسلمين ونفعهم بما يتيسر، مِن علم، أو مال، أو معاونة، أو إشارة بمصلحة، أو نصيحة، أو غير ذلك.
الترغيب في التيسير على المعسر.
الحث على عون العبد المسلم، وأن الله تعالى يُعين المعين حسب إعانته لأخيه.
مِن سِتْر المسلم: عدمُ تتبُّع عوراته، وقد رُوي عن بعض السلف أنه قال: أدركت قومًا لم يكن لهم عيوب، فذكروا عيوبَ الناس، فَذَكَر الناسُ لهم عيوبًا، وأدركت قومًا كانت لهم عيوب، فَكَفُّوا عن عيوب الناس، فنُسِيت عيوبُهم.
ليس من لوازم الستر على الناس ترك المنكر وعدم تغييره، بل يُغَيِّر ويَسْتُر، وهذا في حقِّ مَن لا يُعرَف بالفساد والتَّمَادِيْ في الطغيان، وأما من عُرِف بذلك فإنه لا يُستحب الستر عليه، بل يرفع أمره إلى مَن له الولاية، إذا لم يخَفْ مِن ذلك مفسدة؛ وذلك لأن الستر عليه يُغْرِيْهِ على الفساد، ويُجَرِّئهُ على أذية العباد، ويُجرّئ غيره من أهل الشر والعناد.
الحث على طلب العلم وتلاوة القرآن وتدارسه.
قال النووي: في هذا دليل لفضل الاجتماع على تلاوة القرآن في المسجد... ويلحق بالمسجد في تحصيل هذه الفضيلة الاجتماع في مدرسة ورباط ونحوهما إن شاء الله تعالى.
الجزاء إنما رتَّبَه الله على الأعمال لا على الأنساب.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4801', false),
(21382, 2, 213, 1382, 'hadith', 'وعنه أيضًا رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "من دعا إلى هدى كان له من الأجر مثل أجور من تبعه لا ينقص ذلك من أجورهم شيئًا.', 'The Messenger of Allah (ﷺ) said, "He who calls others to follow the Right Guidance will have a reward equal to the reward of those who follow him, without their reward being diminished in any respect on that account.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1382', 'Riyad as-Salihin 1382', 'ریاض الصالحین 1382', 'رواه مسلم', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ مَن أَرشَدَ وَدَلَّ وحَضَّ الناسَ على طريقٍ فيه حقٌّ وخيرٌ بقولٍ أو فعلٍ كان له مِثْلُ أجرِ مَن تَبِعَه دون أنْ ينقص ذلك من أجر التابع شيئًا. 
ومَن أَرشَدَ ودَلَّ الناسَ إلى طريقِ باطلٍ وشرٍّ فيه ذنب وخطيئة أو أمر لا يَحِلّ، بقول أو فعل، كان عليه مِثْلُ وِزْرِ وإِثمِ مَن تَبِعَه مِن غير أن ينقص ذلك من آثامِهِم شيئًا.', 'فضل الدعوة إلى الهدى، قليلًا كان أو كثيرًا، وأنَّ الدّاعي له مِثلُ أجر العامل، وذلك من عظيم فضل الله وكمال كرمه.
خطورة الدعوة إلى الضلال، قليلًا كان أو كثيرًا، وأنّ الداعي عليه مِثل وِزْر العامل.
الجزاء من جنس العمل، فمن دعا إلى الخير كان له مثل أجر فاعله، ومن دعا إلى الشر كان عليه مثل وزر فاعله.
على المسلم أن يَحذَرَ مَن أن يُقتَدَى به بمجاهرته بالمعصية والناس يَرونه، فإنه يأثم بِمَن قَلَّدَه ولو لم يَحُثَّه على ذلك.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3373', false),
(21383, 2, 213, 1383, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم : «إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية ،أو علم ينتفع به، أو ولد صالح يدعو له».', 'The Messenger of Allah (ﷺ) said, "When a man dies, his deeds come to an end except for three things: Sadaqah Jariyah (ceaseless charity); a knowledge which is beneficial, or a virtuous descendant who prays for him (for the deceased).".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1383', 'Riyad as-Salihin 1383', 'ریاض الصالحین 1383', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21384, 2, 213, 1384, 'hadith', 'وعنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «الدنيا ملعونة ملعون ما فيها إلا ذكر الله تعالى، وما والاه، وعالمًا أو متعلمًا» ((رواه الترمذي وقال: حديث حسن. )). (2)', 'The Messenger of Allah (ﷺ) said, "The world, with all that it contains, is accursed except for the remembrance of Allah that which pleases Allah; and the religious scholars and seekers of knowledge.".', null, 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 1384', 'Riyad as-Salihin 1384', 'ریاض الصالحین 1384', null, null, null, null, 'sunnah.com', null, false, null, false),
(21385, 2, 213, 1385, 'hadith', 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من خرج في طلب العلم، فهو في سبيل الله حتى يرجع» رواه الترمذي وقال: حديث حسن.', 'The Messenger of Allah (ﷺ) said, "He who goes forth in search of knowledge is considered as struggling in the Cause of Allah until he returns.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1385', 'Riyad as-Salihin 1385', 'ریاض الصالحین 1385', null, 'معنى الحديث: أن مَنْ خَرج من بيته أو بلده؛ بَحثا عن العلم الشرعي، فهو في حكم من خرج للجهاد في سبيل الله تعالى ، حتى يعود إلى أهله؛ لأنه كالمجاهد في إحياء الدِّين وإذلال الشيطان وإتعاب النَفْس.', 'أن طلب العلم جهاد في سبيل الله.
لطالب العلم أجْر المجاهد في ميادين القتال؛ لأن كلا منهما يقوم بما يُقَوِّي شريعة الله ويدفع عنها ما ليس منها.
فيه أن من خرج في طلب العلم، فله ثواب ممشاه ذهابا وإيابا إلى أن يرجع إلى أهله.', 'في سَبِيلِ الله : بمثابة المجاهد لإعلاء كلمة الله -تعالى-.
حتى يَرجع : يعود لمكانه الذي خَرَج منه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4191', false),
(21386, 2, 213, 1386, 'hadith', 'عن أبي سعيد الخدري رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: «لن يشبع مؤمن من خير حتى يكون منتهاه الجنة».', 'The Messenger of Allah (ﷺ) said, "A believer never satisfies doing good until he reaches Jannah.".', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1386', 'Riyad as-Salihin 1386', 'ریاض الصالحین 1386', 'رواه الترمذي وقال حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21387, 2, 213, 1387, 'hadith', 'عن أبي أمامة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "فضل العالم على العابد كفضلي على أدناكم" ثم قال رسول الله صلى الله عليه وسلم : "إن الله وملائكته وأهل السماوات والأرض حتى النملة في جحرها وحتى الحوت ليصلون على معلمي الناس الخير".', 'The Messenger of Allah (ﷺ) said, "The superiority of the learned over the devout worshipper is like my superiority over the most inferior amongst you (in good deeds)." He went on to say, "Allah, His angels, the dwellers of the heaven and the earth, and even the ant in its hole and the fish (in water) supplicate in favour of those who teach people knowledge.".', 'أبي أمامة رضي الله عنه', 'Abu Umamah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1387', 'Riyad as-Salihin 1387', 'ریاض الصالحین 1387', 'رواه الترمذي وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21388, 2, 213, 1388, 'hadith', 'عن أبي الدرداء رضي الله عنه قال سمعت رسول الله صلى الله عليه وسلم يقول: «من سلك طريقًا يبتغي فيه علمًا سهل الله له طريقًا إلى الجنة، وإن الملائكة لتضع أجنحتها لطالب العلم رضا بما صنع، وإن العالم ليستغفر له من في السماوات والأرض حتى الحيتان في الماء، وفضل العالم على العابد كفضل القمر على سائر الكواكب، وإن العلماء ورثة الأنبياء وإن الأنبياء لم يورثوا دينارًا ولا درهما وإنما ورثوا العلم. فمن أخذه أخذ بحظ وافر».', 'The Messenger of Allah (ﷺ) said, "He who follows a path in quest of knowledge, Allah will make the path of Jannah easy to him. The angels lower their wings over the seeker of knowledge, being pleased with what he does. The inhabitants of the heavens and the earth and even the fish in the depth of the oceans seek forgiveness for him. The superiority of the learned man over the devout worshipper is like that of the full moon to the rest of the stars (i.e., in brightness). The learned are the heirs of the Prophets who bequeath neither dinar nor dirham but only that of knowledge; and he who acquires it, has in fact acquired an abundant portion.".', 'أبي الدرداء رضي الله عنه', 'Abud-Darda (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1388', 'Riyad as-Salihin 1388', 'ریاض الصالحین 1388', 'رواه أبو داود والترمذي', 'جاء هذا الحديث ليوضح بعض فضائل طلب العلم:
فمنها أن من مشى في طريق يريد بسيره فيه الذهاب لطلب العلم أو بحث عن العلم ولو في بيته جازاه الله سبحانه بأن يسهل له طريقاً إلى الجنة، وسلوكُ طريق العلم يشمل الطريق الحسي الذي يمشي فيه الإنسان برجله، كما يشمل الطريق المعنوي، بأن يلتمس العلم من مجالسة العلماء، ومن بطون الكتب، وذلك أن الذي يراجع الكتب للعثور على حكم مسألة شرعية، أو يجلس إلى شيخ يتعلم منه، فإنه قد سلك طريقًا يلتمس فيه علمًا ولو كان جالسًا.
ومن الفضائل المذكورة في هذا الحديث أن العلماء يستغفر لهم أهل السماء والأرض، حتى الحيتان في البحر، وحتى الدواب في البر.
ومن فضائله أن الملائكة الذين كرمهم الله عز وجل تضع أجنحتها لطالب العلم رضا بما يصنع، تواضعًا وتعظيمًا للعلم وأهله.
ومن الفضائل التي ذكرها النبي صلى الله عليه وسلم في هذا الحديث أن العلماء ورثة الأنبياء، حيث ورثوا منهم العلم والعمل، وورثوا الدعوة إلى الله عز وجل وهداية الخلق ودلالتهم على الله تعالى وعلى دينه.
ومن فضائله أن مزية العالم على العابد كمزية القمر ليلة البدر على بقية الكواكب؛ لأن نور العبادة وكمالها ملازم للعابد لا يتخطاه، فهو كنور الكواكب، أما نور العلم وكماله فهو يتعدى إلى الغير فيستضيء به غير العالم.
وذكر -عليه الصلاة والسلام- أن الأنبياء لم يورثوا لمن بعدهم الدنيا، فلم يورثوا درهمًا ولا دينارًا، وأن أعظم ميراث تركوه هو العلم، فمن أخذه أخذ بنصيب وافر كثير، وهو الإرث الحقيقي النافع.
ولا يظن المسلم أنَّ العالم المفضَّل عارٍ عن العمل، ولا العابد عن العِلم، بل إن علم ذاك غالب على عمله، وعمل هذا غالب على علمه، ولذلك جعل العلماء ورثة الأنبياء الذين فازوا بالحسنيين، العلم والعَمل وحازوا الفضيلتين، الكمال، والتكميل، وهذه طريقة العارفين بالله وسبيل السائرين إلى الله تعالى .', 'فضل العلم، وأنه نور يضيء للناس طريق الخير والحق.
الحث على توقير طلاب العلم، والتواضع والدعاء والاستغفار لهم.
العلم أعظم ثروة وأشرفها، ينبغي لمن حازها أن يحترمها ويكرمها.
إهانة العلماء وإيذاؤهم فسق وضلال؛ لأنهم حملة ميراث النبوة.
من فضائل العلم أن العلماء يستغفر لهم أهل السماء والأرض, حتى الحيتان في البحر, وحتى الدواب في البر.
أن العلماء هم ورثة الأنبياء في العلم والعمل والدعوة وهداية الخلق.
من فضائل العلم وأهله أن الملائكة الكرام تضع أجنحتها لطالب العلم, ووضع الملائكة أجنحتها له تواضعًا له وتوقيرًا وإكرامًا لما يحمله من ميراث النبوة ويطلبه.
أن الأنبياء لا يُورَثون؛ لأنهم لم يورثوا درهمًا ولا دينارًا, وهذا من حكمة الله -عز وجل- لئلا يقول قائل إن النبي إنما ادعى النبوة لأجل الدنيا.
أن فضل العالم على العابد كفضل القمر على سائر الكواكب؛ لأن القمر يضيء الآفاق ويمتد نوره في أقطار العالم وهذه حال العالم, وأما الكوكب فنوره لا يجاوز نفسه أو ما قرب منه وهذه حال العابد الذي يضيء نور عبادته عليه دون غيره، وإن جاوز نور عبادته غيره فإنما يجاوزه غير بعيد.', 'يبتغي : يطلب.
الكواكب : جمع كوكب، وهي الأجرام والنجوم التي تدور في السماء.
بحظ : بنصيب.
وافر : كثير.
علمًا : علمًا شرعيًا أو وسيلةً إليه.
لتضع أجْنِحَتَهَا : أن الملائكة تفرش وتبسط أجنحتها تحت قدمي طالب العلم تواضعًا له, أو تكفُّ أجنحتها عن الطيران وتنزل لسماع العِلم, وذكر الشراح غير هذا من المعاني المجازية, والأصل الحمل على الحقيقة.
فضل : مزية, وما يزيد به العالم على العابد.
دينارًا ولا درهمًا : مالاً وخص الدينار والدرهم بالذكر؛ لأنهما أغلب أنواعه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6267', false),
(21389, 2, 213, 1389, 'hadith', 'عن ابن مسعود رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «نضر الله امرءًا سمع منا شيئًا فبلغه كما سمعه فرب مبلغ أوعي من سامع».', 'I heard the Messenger of Allah (ﷺ) saying, "May Allah freshen the affairs of a person who hears something from us and communicates it to others exactly as he has heard it (i.e., both the meaning and the words),  for it may be that the recipient of knowledge understands it better than the one who has heard it.".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1389', 'Riyad as-Salihin 1389', 'ریاض الصالحین 1389', 'رواه الترمذي وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21390, 2, 213, 1390, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من سئل عن علم فكتمه ألجم يوم القيامة بلجام من نار» ((رواه أبو داود والترمذي، وقال: حديث حسن.', 'The Messenger of Allah (ﷺ) said, "He who is asked about knowledge (of religion) and conceals it, will be bridled with a bridle of fire on the Day of Resurrection.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1390', 'Riyad as-Salihin 1390', 'ریاض الصالحین 1390', null, 'هذا الحديث فيه التحذير الشديد من كتمان العلم، وأن من سُئل عن علم يحتاج إليه السائل في أمر دينه، ويلزم المسؤول عنه بيانه، فلم يبيِّن ذلك العلم بعدم الجواب، أو بمنع الكتاب، عاقبه الله تعالى يوم القيامة بأن يدخل في فمه لجاما من نار؛ مكافأة له حيث ألجم نفسه بالسكوت، والجزاء من جنس العمل، والوعيد في هذا الحديث يلحق من عَلم أن السائل يسأل للاسترشاد، أما إذا علم من السائل أنه يسأل امتحاناً وليس بقصد أن يسترشد فيعلم ويعمل، فالمسؤول بالخيار بين الإجابة وعدمها، ولا يلحقه الوعيد الوارد في الحديث.', 'كتمان العلم من الكبائر التي يستحق عليها الوعيد الشديد.
وجوب تبليغ العلم إذا كان متعينًا، وخاصة في أمور الدين.
أن الجزاء من جنس العمل حيث عوقب من وجب عليه تبليغ العلم, فأمسك فمه عن بيان الحق في الدنيا, بأن يُدخل في فمه لجام من نار يوم القيامة.', 'ألجم : من اللجام، وهو ما يوضع في فم الفرس.
علم : يحتاجه الناس  ويلزمه تعليمه.
كتمه : لم يبينه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6268', false),
(21391, 2, 213, 1391, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم : «من تعلم علمًا مما يبتغى به وجه الله عز وجل لا يتعلمه إلا ليصيب به غرضًا من الدنيا لم يجد عرف الجنة يوم القيامة».', 'The Messenger of Allah(ﷺ) said, "He who does not acquire knowledge with the sole intention of seeking the Pleasure of Allah but for worldly gain, will not smell the fragrance of Jannah on the Day of Resurrection.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1391', 'Riyad as-Salihin 1391', 'ریاض الصالحین 1391', 'يعني ريحها))، ((رواه أبو داود بإسناد صحيح', 'بيَّن النبي صلى الله عليه وسلم أنَ من تعلم العلم الشرعي الذي الأصل فيه أن يراد به رضى الله تعالى لا يتعلمه إلا ليصيب وينال به حظًا ومتاعًا من الدنيا من مالٍ أو جاهٍ لم يجد ريح الجنة يوم القيامة.', 'وجوب الإخلاص في طلب العلم، والحث على ذلك.
التحذير الشديد من اتخاذ العلم الشرعي رياءً أو مطية للدنيا، وأن ذلك من كبائر الذنوب.
أن من طلب العلم لله تعالى وجاءته الدنيا تبعا جاز له أخذها، ولم يضره ذلك.
قال السندي: قوله (عرف الجنة): الرائحة، مبالغة في تحريم الجنة؛ لأن من لا يجد ريح الشيء لا يتناوله.
من تعلم علمًا مما يبتغى به وجه الله من أجل الوظيفة، أو من أجل أغراض أخرى؛ فإن عليه التوبة إلى الله من ذلك، والله يمحو عنه ما حصل من النية الفاسدة وهو ذو الفضل العظيم سبحانه وتعالى.
هذا التحذير لطالب العلم الشرعي، أما من طلب علمًا من علوم الدنيا لأجل متاع الدنيا كالهندسة والكيمياء وغيرهما لأجل الدنيا فله نيته.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6262', false),
(21392, 2, 213, 1392, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنهما قال: سمعت رسول الله صلى الله عليه وسلم يقول: "إن الله لا يقبض العلم انتزاعًا ينتزعه من الناس ولكن يقبض العلم بقبض العلماء حتى إذا لم يبقِ عالمًا، اتخذ الناس رءوسًا جهالا، فسئلوا فأفتوا بغير علم، فضلوا وأضلوا:.', 'I heard the Messenger of Allah (ﷺ) saying: "Verily, Allah does not take away knowledge by snatching it from the people, but He takes it away by taking away (the lives of) the religious scholars till none of the scholars stays alive. Then the people will take ignorant ones as their leaders, who, when asked to deliver religious verdicts, will issue them without knowledge, the result being that they will go astray and will lead others astray.".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''As (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1392', 'Riyad as-Salihin 1392', 'ریاض الصالحین 1392', 'متفق عليه', 'عن عبدالله بن عمرو رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : "إن الله لا يقبض العلم"، المراد به علم الكتاب والسنة وما يتعلق بهما، "انتزاعاً ينتزعه من الناس"، يعني: لا يقبض العلم من الناس بأن يرفعه من بينهم إلى السماء، "ولكن يقبض العلم"، أي: يرفعه، "بقبض العلماء"، أي: بموتهم ورفع أرواحهم، "حتى إذا لم يبق"، أي: الله، "عالماً"، بقبض روحه "اتخذ الناس رؤوساً"، أي: خليفة وقاضياً ومفتياً وإماماً وشيخاً، "جهالاً"، جمع جاهل أي: جهلة، "فسئلوا، فأفتوا"، أي: أجابوا وحكموا، "بغير علم، فضلوا" أي: صاروا ضالين، "وأضلوا"، أي: مضلين لغيرهم، فيعم الجهل العالم، ففي هذا الحديث إشارة إلى أن العلم سيقبض، ولا يبقى في الأرض عالم يرشد الناس إلى دين الله، فتتدهور الأمة وتضل بعد ذلك.', 'الحث على طلب العلم، ليكثر العلماء، ويعم نفع الناس بهم.
موت العلماء مصيبة تحل بالأمة، وثَلْم في الإسلام.
الفتوى هي الرياسة الحقيقية، وذم من يقدم عليها بغير علم.
التحذير من استفتاء الجاهلين، أو الفتوى بغير علم.
الفتوى بالرأي سبيل الضلال والإضلال.
قلة العلم بالدين من علامات قرب القيامة.', 'انتزاعًا : من النزع، وهو الجذب والقلع.
بقبض العلماء : بموتهم.
رؤوساً : جمع رأس، وهو السيد المقدم في الناس.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10118', false),
(21393, 2, 214, 1393, 'hadith', 'عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم أتي ليلة أسري به بقدحين من خمر ولبن، فنظر إليهما فأخذ اللبن، فقال جبريل صلى الله عليه وسلم: «الحمد لله الذي هداك للفطرة لو أخذت الخمر غوت أمتك».', 'On the Night of Al-Isra (the Night of Ascension) the Prophet (ﷺ) was presented with two drinking vessels: one full of wine and the other one full of milk. He looked at them. Then he took the vessel which was full of milk. Thereupon Jibril (Gabriel) said: "Al-hamdu lillah (praise be to Allah) Who has guided you to that, which is in accord with Fitrah (i.e., Islamic Monotheism; pure nature of Islam). Had you selected wine, your people would have gone astray.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1393', 'Riyad as-Salihin 1393', 'ریاض الصالحین 1393', 'رواه مسلم', 'أن النبي صلى الله عليه وسلم أُتِيَ، أي: أتاه جبريل، ليلة أسري به، وهي ليلة المعراج، أتاه بقدحين مملوءين أحدهما من خمر والآخر من لبن، "فنظر إليهما"، أي: كأنه خُيِّرَ بينهما، فأُلهم –صلى الله عليه وسلم- اختيار اللبن، "فأخذ اللبن، فقال جبريل: الحمد لله الذي هداك للفطرة"، أي: اخترت علامة الإسلام والاستقامة، وجعل اللبن علامة على ذلك لكونه سهلاً طيباً طاهراً سائغاً للشاربين، سليم العاقبة، "لو أخذت الخمر غوت أمتك".', 'الإسلام دين الفطرة الذي تتقبله النفوس السليمة، وتدركه الأفهام القويمة.
توفيق الله لنبيه -صلى الله عليه وسلم- باختيار ما يوافق الفطرة.
إثبات الإسراء برسول الله -صلى الله عليه وسلم-.
الحث على حمد الله -تعالى- على ما يوفق إليه من خير وفضل.
أن حمد الله -تعالى- ليس في الأمور الخاصة فحسب، بل على ما يكون من نعم عامة على الأمة أيضًا.
استحباب التفاؤل بالبشائر الحسنة والأمارات السارة.
الخمر أم الخبائث، وتعاطي الأمة لها عنوان الجهل والانحراف، ونذير الذمار والهلاك.
بيان فضيلة اللبن على غيره من الأطعمة.', 'بقدحين : مثنى قَدَح، وهو إناء يشرب فيه الماء ونحوه.
الفطرة : الإسلام والاستقامة.
غوت أمتك : ضلت وانهمكت في الشر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10120', false),
(21394, 2, 214, 1394, 'hadith', 'وعنه عن رسول الله صلى الله عليه وسلم قال: «كل أمر ذي بال لا يبدأ فيه: بالحمد لله فهو أقطع» حديث حسن.', 'The Messenger of Allah (ﷺ) said, "Any matter of importance which is not begun with Al-hamdu lillah (praise be to Allah) remains defective.".', null, 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 1394', 'Riyad as-Salihin 1394', 'ریاض الصالحین 1394', 'رواه أبو داود وغيره', null, null, null, 'sunnah.com', null, false, null, false),
(21395, 2, 214, 1395, 'hadith', 'عن أبي موسى الأشعري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إذا مات ولد العبد قال الله تعالى لملائكته: قبضتم ولد عبدي؟ فَيقولون : نَعَمْ ، فيقول : قَبَضْتُمْ ثَمَرَةَ فُؤادِهِ ؟ فيقولون : نَعَمْ ، فيقول : فماذا قال عبدي؟ فيقولون: حمدك واسترجع، فيقول الله تعالى: ابنوا لعبدي بيتًا في الجنة، وسموه بيت الحمد». رواه الترمذي وقال حديث حسن.', 'The Messenger of Allah (ﷺ) said, "When a slave''s child dies, Allah the Most High asks His angels, ''Have you taken out the life of the child of My slave?" They reply in the affirmative. He then asks, ''Have you taken the fruit of his heart?'' They reply in the affirmative. Thereupon he asks, ''What has My slave said?'' They say: ''He has praised You and said: Inna lillahi wa inna ilaihi raji''un (We belong to Allah and to Him we shall be returned). Allah says: ''Build a house for My slave in Jannah and name it as Bait-ul-Hamd (the House of Praise)."''.', 'أبي موسى الأشعري رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', null, 'رياض الصالحين 1395', 'Riyad as-Salihin 1395', 'ریاض الصالحین 1395', null, null, null, null, 'sunnah.com', null, false, null, false),
(21396, 2, 214, 1396, 'hadith', 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إن الله ليرضى عن العبد يأكل الأكلة فيحمده عليها، ويشرب الشربة، فيحمده عليها».', 'The Messenger of Allah (ﷺ) said, "Allah is pleased with His slave who says: ''Al-hamdu lillah (praise be to Allah)'' when he takes a morsel of food and drinks a draught of water.".', 'أنس رضي الله عنه', 'Anas bin Malik (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1396', 'Riyad as-Salihin 1396', 'ریاض الصالحین 1396', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21397, 2, 215, 1397, 'hadith', 'عن عبد الله بن عمرو بن العاص، رضي الله عنهما أنه سمع رسول الله صلى الله عليه وسلم يقول: «من صلى علي صلاة، صلى الله عليه بها عشرًا».', 'I heard the Messenger of Allah (ﷺ) saying: "Whoever supplicates Allah to exalt my mention, Allah will exalt his mention ten times.".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''As (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1397', 'Riyad as-Salihin 1397', 'ریاض الصالحین 1397', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21398, 2, 215, 1398, 'hadith', 'عن ابن مسعود رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «أولى الناس بي يوم القيامة أكثرهم علي صلاة» رواه الترمذي وقال حديث حسن.', 'The Messenger of Allah (ﷺ) said: "The people who will be nearest to me on the Day of Resurrection will be those who supplicate Allah more often for me.".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', null, 'رياض الصالحين 1398', 'Riyad as-Salihin 1398', 'ریاض الصالحین 1398', null, null, null, null, 'sunnah.com', null, false, null, false),
(21399, 2, 215, 1399, 'hadith', 'عن أوس بن أوس، رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: "إن من أفضل أيامكم يوم الجمعة، فأكثروا على من الصلاة فيه، فإن صلاتكم معروضة علي" فقالوا: يا رسول الله، كيف تعرض صلاتنا عليك وقد أرمت؟ قال: يقول: بلىت، قال: "إن الله عز وجل حرم على الأرض أجساد الأنبياء" رواه أبو داود بإسناد صحيح.', 'The Messenger of Allah (ﷺ) said, "Among the best of your days is Friday; so supplicate Allah more often for me in it , for your supplications will be displayed to me." He was asked: "O Messenger of Allah! How will our blessings be displayed to you when your decayed body will have mixed with the earth?" He (ﷺ) replied, "Allah has prohibited the earth from consuming the bodies of the Prophets.".', 'أوس بن أوس رضي الله عنه', 'Aus bin Aus (May Allah be pleased with him)', null, 'رياض الصالحين 1399', 'Riyad as-Salihin 1399', 'ریاض الصالحین 1399', null, null, null, null, 'sunnah.com', null, false, null, false),
(21400, 2, 215, 1400, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «رغم أنف رجل ذكرت عنده فلم يصلِ علي» رواه الترمذي وقال حديث حسن.', 'The Messenger of Allah (ﷺ) said, "May his nose soil with dust in whose presence mention is made of me and he does not supplicate for me.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 1400', 'Riyad as-Salihin 1400', 'ریاض الصالحین 1400', null, null, null, null, 'sunnah.com', null, false, null, false)
