insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21401, 2, 215, 1401, 'hadith', 'وعنه رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «لا تجعلوا قبري عيدًا وصلوا علي، فإن صلاتكم تبلغني حيث كنتم» رواه أبو داود بإسناد صحيح.', 'The Messenger of Allah (ﷺ) said, "Do not make my grave a place of festivity, and supplicate Allah for me, for your supplication reaches me wherever you are.".', null, 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 1401', 'Riyad as-Salihin 1401', 'ریاض الصالحین 1401', null, null, null, null, 'sunnah.com', null, false, null, false),
(21402, 2, 215, 1402, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال: «ما من أحد يسلم علي إلا رد الله علي روحي حتى أرد عليه السلام».', 'The Messenger of Allah (ﷺ) said, "Whenever someone greets me, Allah returns the soul to my body (in the grave) and I return his greeting.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'إسناده حسن', 'رياض الصالحين 1402', 'Riyad as-Salihin 1402', 'ریاض الصالحین 1402', 'رواه أبو داود بإسناد صحيح', 'يُخْبِرُ النبيُّ صلى الله عليه وسلم أنّه تُرَدُّ إليه رُوحُه ليَرُدَّ السلامَ على كل مَن سلَّم عليه سواء كان قريبًا أو بعيدًا؛ وحياة البَرْزَخ والقبور أمرٌ غيبي، لا يَعلم حقيقتَها إلا الله، وهو على كل شيء قدير.', 'الحث على الإكثار من الصلاة والسلام على النبي صلى الله عليه وسلم.
حياة النبي صلى الله عليه وسلم في قبره هي أكملُ حياة يحياها إنسان في بَرْزَخِه، فلا يَعلم حقيقتها إلا الله تعالى.
الحديث ليس فيه حُجّة لمن يقول بحياة رسول الله صلى الله عليه وسلم حياةً كما نعيشها نحن، حتى لا يَستدِلّ به أهل الشرك على الاستغاثة به عليه الصلاة والسلام، وإنما هي حياة برزخية.', null, 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6222', false),
(21403, 2, 215, 1403, 'hadith', 'عن علي رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: « البخيل من ذكرت عنده، فلم يصلِ علي».', 'The Messenger of Allah (ﷺ) said, "The miser is the one in whose presence I am mentioned but he does not supplicate for me.".', 'علي رضي الله عنه', '''Ali (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1403', 'Riyad as-Salihin 1403', 'ریاض الصالحین 1403', 'رواه الترمذي وقال: حديث حسن صحيح', 'حَذَّرَ النبيُّ صلى الله عليه وسلم مِن تَرْك الصلاة عليه حال سَمَاع اسمه أو كُنْيَتِه أو وصفه، وقال: البَخيل كامل البُخْل مَن ذُكرتُ عنده فلم يُصلِّ عليّ؛ وذلك لأمور: 

الأول: أنه بُخْلٌ بشيءٍ لا يَخْسَر بسببه قليلًا ولا كثيرًا، ولا يَبذُل مالًا، ولا يَبذُل جُهْدًا. 

الثاني: أنه بَخِلَ على نفسه وحَرَمَها أجرَ الصلاة على رسوله صلى الله عليه وسلم؛ لأنه بامتناعه من الصلاة عليه قد شَحَّ وامتنع من أداء حقٍّ يَتَعَيَّنُ عليه أداؤه امتثالًا للأمر وينال به الأجر. 

الثالث: أنَّ الصلاة عليه فيها أداء بعض حقِّ النبي صلى الله عليه وسلم، فهو الذي عَلَّمنا، وهو الذي أرشدَنا، وهو الذي دعانا إلى الله تبارك وتعالى، وجاءنا بهذا الوحي، وهذه الشَّريعة، فهو سبب هدايتنا -بعد الله تبارك وتعالى- ومَن لم يُصلِّ عليه يكون قد بَخِل على نفسه، وبَخِل على نبيِّه صلى الله عليه وسلم بحقٍّ هو من أدنى حقوقه.', 'تَرْك الصلاة على النبي صلى الله عليه وسلم عنوان الشُّحِّ.
الصلاة على النبي صلى الله عليه وسلم من أفضل القُرُبات والطاعات في جميع الأوقات، ويتأكّد حالَ ذِكْرِه.
قال النووي: إذا صلى على النبي صلى الله عليه وسلم فليَجمع بين الصلاة والتسليم، ولا يَقتصر على أحدِهما؛ فلا يَقل: (صلى الله عليه) فقط، ولا: (عليه السلام) فقط.
قال أبو العالية في قوله: (إن الله وملائكته يصلون على النبي) قال: صلاة الله عز وجل على نبيه: ثناؤه عليه، والصلاة من الملائكة والبشر: الدعاء.
قال الحليمي: فمعنى «اللهم صلّ على محمد»: اللهم عظّمه في الدنيا بإعلاء ذِكْرِه، وإظهار دينه، وإبقاء شريعته، وفي الآخِرة: بِتَشْفِيْعِهِ في أُمَّتِهِ، وإِجْزَال أجره ومثوبته، وإبداء فضله للأولين والآخرين بالمقام المحمود، وتقديمه على كافة المقربين الشهود.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5403', false),
(21404, 2, 215, 1404, 'hadith', 'عن فضالة بن عبيد رضي الله عنه قال: سمع رسول الله صلى الله عليه وسلم رجلا يدعو في صلاته لم يمجد الله تعالى، ولم يصلِ على النبي صلى الله عليه وسلم، فقال رسول الله صلى الله عليه وسلم "عجل هذا" ثم دعاه فقال له -أو لغيره: إذا صلى أحدكم فليبدأ بتحميد ربه سبحانه، والثناء عليه، ثم يصلي على النبي صلى الله عليه وسلم ثم يدعو بعد ما شاء" رواه أبو داود والترمذي وقال حديث صحيح.', 'The Messenger of Allah (ﷺ) heard some one supplicating after his prayer without praising Allah and without supplicating Allah for the Prophet (ﷺ). With regard to him, the Messenger of Allah (ﷺ) said, "This man rushed." Then he called him and said, "When any one of you have performed Salat (prayer) and wants to supplicate, let him praise Allah first then glorify Him in the beginning and then he should supplicate Allah for me. Then he may supplicate for whatever he likes.".', 'فضالة بن عبيد رضي الله عنه', 'Fadalah bin ''Ubaid (May Allah be pleased with him)', null, 'رياض الصالحين 1404', 'Riyad as-Salihin 1404', 'ریاض الصالحین 1404', null, null, null, null, 'sunnah.com', null, false, null, false),
(21405, 2, 215, 1405, 'hadith', 'عن أبي محمد كعب بن عجرة رضي الله عنه قال: خرج علينا النبي صلى الله عليه وسلم فقلنا: يا رسول الله، قد علمنا كيف نسلم عليك، فكيف نصلي عليك؟ قال: «قولوا: اللهم صلِ على محمد، وعلى آل محمد، كما صليت على آل إبراهيم، إنك حميد مجيد. اللهم بارك على محمد وعلى آل محمد، كما باركت على آل إبراهيم، إنك حميد مجيد».', 'The Prophet (ﷺ) came to us and we asked him, "O Messenger of Allah, we already know how to greet you (i.e., say As-salamu ''alaikum), but how should we supplicate for you?" He (ﷺ) said, "Say: ''Allahumma salli ''ala Muhammadin, wa ''ala ''ali Muhammadin, kama sallaita ''ala ''ali Ibrahima, innaka Hamidum Majid. Allahumma barik ''ala Muhammadin, wa ''ala ''ali Muhammadin, kama barakta ''ala ''ali Ibrahima, innaka Hamidum Majid .', 'أبي محمد كعب بن عجرة رضي الله عنه', 'Abu Muhammad Ka''b bin ''Ujrah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1405', 'Riyad as-Salihin 1405', 'ریاض الصالحین 1405', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21406, 2, 215, 1406, 'hadith', 'عن أبي مسعود بن عبادة البدري، رضي الله عنه، قال: أتانا رسول الله صلى الله عليه وسلم، ونحن في مجلس سعد بن عبادة رضي الله عنه، فقال له بشير بن سعد: أمرنا الله تعالى أن نصلي عليك يا رسول الله، فكيف نصلي عليك؟ فسكت رسول الله صلى الله عليه وسلم، حتى تمنينا أنه لم يسأله، ثم قال رسول الله صلى الله عليه وسلم: «قولوا اللهم صلِ على محمد وعلى آل محمد كما صليت على آل إبراهيم وبارك على محمد وعلى آل محمد كما باركت على آل إبراهيم إنك حميد مجيد، والسلام كما قد علمتم».', 'We were sitting in the company of Sa''d bin ''Ubadah (May Allah be pleased with him), when the Messenger of Allah (ﷺ) came to us. Bashir bin Sa''d said: "O Messenger of Allah! Allah has commanded us to supplicate for you, but how should we do that?" The Messenger of Allah (ﷺ) kept silent. We were much perturbed over his silence and we wished he did not asked him this question. The Messenger of Allah (ﷺ) said, "Say: ''O Allah, exalt the mention of Muhammad and the family of Muhammad as you exalted the family of Ibrahim. And bless Muhammad and the family of Muhammad as You blessed the family of Ibrahim. You are the Praised, the Glorified,'' and the method of greeting (i.e., Salam) is as you know.".', 'أبي مسعود بن عبادة البدري رضي الله عنه', 'Abu Mas''ud Al-Badri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1406', 'Riyad as-Salihin 1406', 'ریاض الصالحین 1406', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21407, 2, 215, 1407, 'hadith', 'عن أبي حميد الساعدي رضي الله عنه قال: قالوا: يا رسول الله كيف نصلي عليك؟ قال: «قولوا: اللهم صلِ على محمد، وعلى أزواجه وذريته، كما صليت على آل إبراهيم، وبارك على محمد، وعلى أزواجه وذريته، كما باركت على إبراهيم، إنك حميد مجيد».', 'The Companions of the Messenger of Allah (ﷺ) said: "O Messenger of Allah! How should we supplicate for you?" He (ﷺ) replied, "Say: ''Allahumma salli ''ala Muhammadin wa ''ala azwajihi wa dhurriyyatihi, kama sallaita ''ala Ibrahima; wa barik ''ala Muhammadin wa ''ala azwajihi wa dhurriyyatihi, kama barakta ''ala Ibrahima, innaka Hamidum-Majid (O Allah sent Your Salat (O Allah, exalt the mention of Muhammad and his wives and offspring as You exalted the mention of the family of Ibrahim, and bless Muhammad and the wives and the offspring of Muhammad as you blessed the family of Ibrahim. You are the Praised, the Glorious''.".', 'أبي حميد الساعدي رضي الله عنه', 'Abu Humaid As-Sa''idi (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1407', 'Riyad as-Salihin 1407', 'ریاض الصالحین 1407', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21408, 2, 216, 1408, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم».', 'The Messenger of Allah (ﷺ) said, "There are two statements that are light for the tongue to remember, heavy in the Scales and are dear to the Merciful: ''Subhan-Allahi wa bihamdihi, Subhan-Allahil-Azim .', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1408', 'Riyad as-Salihin 1408', 'ریاض الصالحین 1408', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21409, 2, 216, 1409, 'hadith', 'وعنه رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: لأن أقول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، أحب إلي مما طلعت عليه الشمس".', 'The Messenger of Allah (ﷺ) said, "The uttering of the words: "Subhan-Allah (Allah is free from imperfection), Al-hamdu lillah (all praise is due to Allah), La ilaha illallah (there is no true god except Allah) and Allahu Akbar (Allah is the Greatest)'' is dearer to me than anything over which the sun rises.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1409', 'Riyad as-Salihin 1409', 'ریاض الصالحین 1409', 'رواه مسلم', 'يُخْبِرُ النبيُّ صلى الله عليه وسلم أنَّ ذِكْرَ اللهِ تعالى بهذه الكلمات العظيمات خيرٌ من الدنيا وما فيها، وهي: 

"سبحان الله": تنزيه لله عن النقائص.

"الحمد لله": ثناء عليه بصفات الكمال مع محبته وتعظيمه.

"لا إله إلا الله": لا معبود بحق إلا الله.

"الله أكبر": أعظم وأجل من كلِّ شيء.', 'الحث على ذكر الله، وأنه أحب مما طلعت عليه الشمس.
الحض على الإكثار من الذكر؛ لما فيه من الأجر والفضل.
متاع الدنيا قليل وشهواتها زائلة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6211', false),
(21410, 2, 216, 1410, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال: "من قال لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، في يوم مائة مرة كانت له عدل عشر رقاب وكتبت له مائة حسنة، ومحيت عنه مائة سيئة، وكانت له حرزًا من الشيطان يومه ذلك حتى يمسي، ولم يأتِ أحد بأفضل مما جاء به إلا رجل عمل أكثر منه" وقال: "من قال سبحان الله وبحمده، في يوم مائة مرة حطت عنه خطاياه وإن كانت مثل زبد البحر".', 'The Messenger of Allah (ﷺ) said, "He who utters a hundred times in a day these words: ''La ilaha illallahu, wahdahu la sharika lahu, lahul-mulku wa lahul-hamdu, wa Huwa ''ala kulli sha''in Qadir (there is no true god except Allah. He is One and He has no partner with Him; His is the sovereignty and His is the praise, and He is Omnipotent),'' he will have a reward equivalent to that for emancipating ten slaves, a hundred good deeds will be recorded to his credit, hundred of his sins will be blotted out from his scroll, and he will be safeguarded against the devil on that day till the evening; and no one will exceed him in doing more excellent good deeds except someone who has recited these words more often than him. And he who utters: ''Subhan-Allahi wa bihamdihi (Allah is free from imperfection and His is the praise)'' one hundred times a day, his sins will be obliterated even if they are equal to the extent of the foam of the ocean.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1410', 'Riyad as-Salihin 1410', 'ریاض الصالحین 1410', 'متفق عليه', 'أخبرَ النبيُّ صلى الله عليه وسلم أنّ من قال: 

(لا إله) ولا معبود بحق (إلا الله، وحده لا شريك له) في ألوهيته وربوبيته وأسمائه وصفاته، (له الملك) والتصرّف والتدبير كله، (وله الحمد) على جميع ما يَخلقه ويُقدِّره، (وهو على كل شيء قدير) بلا مُمانِع ولا مُدافِع، وما لم يشأ لم يكن. 

فمن قال هذا الذكر في يوم وكَرَّره مائة مرة، كُتب له من الأجر عند الله كمن أَعْتق عشر رقاب من الرَّقِيق، وكُتبت له بهن مائة حسنة ودرجة في الجنة، ومُحِيَتْ عنه وَوُضِعتْ مائةُ سيئة، وكانت له حِرزًا وحفظًا ومَنَعَةً وحِصْنًا من الشيطان وإغوائه وتسلُّطه يومه ذلك حتى يدخل المساء بغروب الشمس، ولم يأتِ أحد يوم القيامة بأفضل مما جاء به إلا أحدٌ عَمِل أكثرَ من ذلك وزاد عليه.', 'فضل كلمة التوحيد وعِظَم أجرها.
سعة فضل الله سبحانه وتعالى على عباده حيث شرع لهم الذكر المَيْسور لكل أحد، ورتَّب عليه الثواب الجزيل.
لو قال هذا التهليل أكثر من مائة مرة في اليوم، كان له هذا الأجر المذكور في الحديث على المائة، ويكون له ثواب آخر على الزيادة، وليس هذا من الحدود التي نُهِيَ عن اعتدائها، ومجاوزة أعدادها، وأن زيادتها لا فضل فيها أو تبطلها.
قال النووي: ظاهر إطلاق الحديث أنه يحصل هذا الأجر المذكور في هذا الحديث من قال هذا التهليل مائة مرة في يومه، سواء قاله متوالية أو متفرقة في مجالس، أو بعضها أول النهار وبعضها آخره، لكن الأفضل أن يأتي بها متوالية في أول النهار، ليكون حرزًا له في جميع نهاره.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65905', false),
(21411, 2, 216, 1411, 'hadith', 'عن أبي أيوب الأنصاري رضي الله عنه عن النبي صلى الله عليه وسلم قال: «من قال لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير، عشر مرات، كان كمن أعتق أربعة أنفس من ولد إسماعيل».', 'The Prophet (ﷺ) said: "He who utters ten times: ''La ilaha illallahu, wahdahu la sharika lahu, lahulmulku wa lahulhamdu, wa Huwa ''ala kulli sha''in Qadir (there is no true god except Allah. He is One and He has no partner with Him. His is the sovereignty and His is the praise, and He is Omnipotent),'' he will have a reward equal to that for freeing four slaves from the progeny of Prophet Isma''il.".', 'أبي أيوب الأنصاري رضي الله عنه', 'Abu Ayyub Al-Ansari (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1411', 'Riyad as-Salihin 1411', 'ریاض الصالحین 1411', 'متفق عليه', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أنَّ مَن قال: «لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير»، ومعناها: لا معبود بحق إلا الله وحده لا شريك له، وأنه سبحانه المُخْتَصُّ بالمُلْكِ التامّ، والمُستحق للثناء والمدح مع المحبة والتعظيم دون من سواه، وأنه قادر لا يُعجزه شيء. 
فمَن كَرَّر هذا الذِّكْرَ العظيم في يوم عشر مرَّات؛ صار له من الأجر مثل أجر من أزال الرِّقِّ عن أربعة مماليك من ذُرِّيَّة إسماعيل بن إبراهيم عليهما الصلاة والسلام، وخَصَّ ذُريةَ إسماعيل عليه السلام؛ لأنهم أشرفُ من غيرهم.', 'فضيلة هذا الذكر المتضمن إفراد الله تعالى بالألوهية، والملك، والحمد، والقدرة التامة.
ينال ثواب هذا الذكر من قاله متواليا أو متفرقا.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5517', false),
(21412, 2, 216, 1412, 'hadith', 'عن أبي ذر رضي الله عنه قال: قال لي رسول صلى الله عليه وسلم: «ألا أخبرك بأحب الكلام إلى الله؟ إن أحب الكلام إلى الله: سبحان الله وبحمده».', 'The Messenger of Allah (ﷺ) said to me, "Shall I tell you the expression that is most loved by Allah?" It is ''Subhan-Allahi wa bihamdihi'' (Allah is free from imperfection and His is the praise)''.".', 'أبي ذر رضي الله عنه', 'Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1412', 'Riyad as-Salihin 1412', 'ریاض الصالحین 1412', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21413, 2, 216, 1413, 'hadith', 'عن أبي مالك الأشعري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «الطهور شطر الإيمان، والحمد لله تملأ الميزان، وسبحان الله، والحمد لله تملآن -أو تملأ- ما بين السماوات والأرض».', 'The Messenger of Allah (ﷺ) said: "Purity is half of iman (faith). ‘Al-hamdu lillah (all praise and gratitude belong to Allah)’ fills the scales, and ‘subhan-Allah (how far is Allah from every imperfection) and ‘Al-hamdulillah (all praise and gratitude belong to Allah)’ fill that which is between heaven and earth."', 'أبي مالك الأشعري رضي الله عنه', 'Abu Malik Al-Ash''ari (may Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1413', 'Riyad as-Salihin 1413', 'ریاض الصالحین 1413', 'رواه مسلم', 'يخبر النبي صلى الله عليه وسلم: أن طهارة الظاهر تكون بالوضوء والغسل وهي شرط في الصلاة. 
وأن قول: " الحمد لله تملا الميزان" وهو الثناء عليه سبحانه، ووصفه بصفات الكمال توزن يوم القيامة فتملأ ميزان الأعمال. 
وأن قول: "سبحان الله والحمد لله" وهو تنزيهه عن كل نَقْصٍ ووصفه بالكمال التام الذي يليق بجلاله مع محبته وتعظيمه تملأ ما بين السموات والأرض. 
وأن "الصلاة نور" للعبد في قلبه، وفي وجهه، وفي قبره، وفي حشره. 
وأن "الصدقة برهان" ودليل على صدق إيمان المؤمن، واختلافه عن المنافق الذي يمتنع منها لكونه لا يصدق بموعودها. 
وأن "الصبر ضياء" -وهو حبس النفس عن الجَزَع والتَّسَخُّط - نور يحصل معه حرارة وإحراق، كضياء الشمس؛ لأنه شاق ويحتاج إلى مجاهدة النفس وحبسها عما تهواه؛ فلا يزال صاحبه مستضيئًا مهتديًا مستمرًّا على الصواب. وهو صبر على طاعة الله، وعن معصيته، وصبر على المصائب وأنواع المكاره في الدنيا. 
وأن "القرآن حجة لك" بتلاوته والعمل به، أو "حجة عليك" بتركه دون عمل أو تلاوة. 
ثم أخبر صلى الله عليه وسلم أن كل الناس يسعون وينتشرون ويقومون من نومهم ويخرجون من بيوتهم لأعمالهم المختلفة، 
فمنهم من يستقيم على طاعة الله فيُعْتِق نفسَه من النار، ومنهم من ينحرف عن ذلك ويقع في المعاصي فيهلكها بدخولها النار.', 'الطهارة طهارتان: طهارة الظاهر تكون بالوضوء والغسل، وطهارة الباطن تكون بالتوحيد والإيمان والعمل الصالح.
أهمية المحافظة على الصلاة فهي نور للعبد في الدنيا ويوم القيامة.
الصدقة دليل على صدق الإيمان.
أهمية العمل بالقرآن وتصديقه ليكون حجة لك لا عليك.
النفس إن لم تشغلها بالطاعة شغلتك بالمعصية.
كل إنسان لا بد أن يعمل؛ فإما أن يعتق نفسه بالطاعة، أو يوبقها بالمعصية.
الصبر يحتاج إلى تَحَمُّلٍ واحتسابٍ وفيه مشقة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65004', false),
(21414, 2, 216, 1414, 'hadith', 'عن سعد بن أبي وقاص رضي الله عنه قال: جاء أعرابي إلى رسول الله صلى الله عليه وسلم فقال: علمني كلامًا أقوله. قال: "قل لا إله إلا الله وحده لا شريك له، الله أكبر كبيرا والحمد لله كثيرا وسبحان الله رب العالمين، ولا حول ولا قوة إلا بالله العزيز الحكيم" قال فهؤلاء لربي، فما لي؟ قال: "قل اللهم اغفر لي، وارحمني، واهدني، وارزقني".', 'A bedouin came to the Messenger of Allah (ﷺ) and said to him, "Teach me a few words to recite frequently." He (ﷺ) said, "Say: "La ilaha illallahu wahdahu la sharika lahu; Allahu Akbar kabiran, wal-hamdu lillahi kathiran, wa subhan-Allahi Rabbil-''alamin; wa la hawla wa la quwwata illa billahil-''Azizil-Hakim (there is no true god except Allah the One and He has no partner with Him; Allah is the Greatest and greatness is for Him. All praise is due to Him. Allah, the Rubb of the worlds is free from imperfection; there is no might and power but that of Allah, the All-Powerful and the All-Wise.)"'' The bedouin said: "All of these for my Rubb. But what is for me?" Thereupon he (Messenger of Allah (ﷺ)) said, "You should say: ''Allahummaghfir li, warhamni, wahdini, warzuqni (O Allah! Grant me pardon, have mercy upon me, direct me to righteousness and provide me subsistence)''.".', 'سعد بن أبي وقاص رضي الله عنه', 'Sa''d bin Abu Waqqas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1414', 'Riyad as-Salihin 1414', 'ریاض الصالحین 1414', 'رواه مسلم', 'سَأَلَ رجلٌ من سُكّانِ الباديةِ رسولَ الله صلى الله عليه وسلم أنْ يُعلِّمه ذكرًا يقوله، 
فقال له عليه الصلاة والسلام: قل: 
"لا إله إلا الله وحده لا شريك له" بدأ بشهادة التوحيد، ومعناها لا معبود بحق إلا الله، 
"الله أكبر كبيرًا" 
أي: الله أكبر من كلِّ شيءٍ وأعظم، 
"والحمد لله كثيرًا" 
أي: حمدًا لله كثيرًا، على صفاته وأفعاله ونعمه التي لا تحصى، 
"سبحان الله رب العالمين" 
أي: تَنَزَّهَ وتَقَدَّسَ عن النقص، 
"لا حول ولا قوة إلا بالله العزيز الحكيم" 
أي: لا تَحَوُّلٌ من حَالٍ إلى حالٍ إلا بالله وإعانتِه وتوفيقِه، 
فقال الرجل: هؤلاء الكلمات لربي لِذِكْرِهِ وتعظيمِه، فما لي من الدعاء لنفسي؟ 
فقال له عليه الصلاة والسلام: قل: 
"اللهم اغفر لي" 
بمحو السيئات وسترها، 
"وارحمني" 
بإيصال المنافع والمصالح الدينية والدنيوية لي، 
"واهدني" 
لأحسن الأحوال وإلى الصراط المستقيم، 
"وارزقني" 
المال الحلال والصحة وكل خير وعافية.', 'الحث على ذكر الله بالتهليل والتكبير والتحميد والتسبيح.
استحباب ذكر الله والثناء عليه قبل الدعاء.
استحباب دعاء الإنسان بأطيب الدعاء، وبما هو مأثور مما فيه جوامع خير الدنيا والآخرة، وله أن يدعو بما يشاء.
ينبغي للعبد الحرص على تَعَلُّم ما ينفعه في الدنيا والآخرة.
الحث على طلب المغفرة والرحمة والرزق، فهي جِمَاع الخير.
شفقته صلى الله عليه وسلم على تعليمِ أمتِهِ ما ينفعهم.
ذُكِرَت الرحمة بعد المغفرة ليتكامل التطهير، فالمغفرة ستر الذنوب ومحوها والزحزحة عن النار، والرحمة إيصال الخيرات ودخول الجنة، وهذا هو الفوز العظيم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6112', false),
(21415, 2, 216, 1415, 'hadith', 'عن ثوبان رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم: إذا انصرف من صلاته استغفر ثلاثا ، وقال : " اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام " قيل للأوزاعي ، وهو أحد رواة الحديث : كيف الاستغفار ؟ قال : يقول : أستغفر الله أستغفر الله ".', 'Whenever the Messenger of Allah (ﷺ) concluded his prayer, he would beg forgiveness from Allah thrice and then would recite: "Allahumma Antas- Salamu, wa minkas-salamu, tabarakta ya Dhal-Jalali wal-Ikram (O Allah, You are the Grantor of security, and security comes from You. You are Blessing, O You Who have majesty and nobility)!" (Imam) Al-Awza''i, one of the narrators of this Hadith, was asked: "How forgiveness is to be sought?" He answered: "The Messenger of Allah (ﷺ) used to say: ''Astaghfirullah! Astaghfirullah! (I beseech Allah for forgiveness, I beseech Allah for forgiveness)''.".', 'ثوبان رضي الله عنه', 'Thauban (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1415', 'Riyad as-Salihin 1415', 'ریاض الصالحین 1415', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21416, 2, 216, 1416, 'hadith', 'عن المغيرة بن شعبة رضي الله عنه أن رسول الله صلى الله عليه وسلم، كان إذا فرغ من الصلاة وسلم قال : «لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير. اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد».', 'Messenger of Allah (ﷺ) used to say at the conclusion of prayer: "La ilaha illallahu wahdahu la sharika lahu, lahul-mulku, wa lahul-hamdu, wa Huwa ''ala kulli shai''in Qadir. Allahumma la mani''a lima a''tayta, wa la mu''tiya lima mana''ta, wa la yanfa''u dhal-jaddi, minkal-jaddu (there is no true god except Allah. He is One and He has no partner with Him, His is the sovereignty and His is the praise, and He is Omnipotent. O Allah! None can deny that which You bestow and none can bestow that which You hold back; and the greatness of the great will be of no avail to them against You).".', 'المغيرة بن شعبة رضي الله عنه', 'Al-Mughirah bin Shu''bah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1416', 'Riyad as-Salihin 1416', 'ریاض الصالحین 1416', 'متفق عليه', 'كان النبيُّ صلى الله عليه وسلم يقول عَقِيب كلِّ صلاةِ فريضة: " لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ".

أي: أُقِرُّ واعترفُ بكلمة التَّوحيد لا إله إلا الله، فالعبادة الحَقَّة أُثْبِتُها لله، وأَنفيها عمّا سواه، فلا معبود بحق إلا الله، ومُقِرٌّ أنَّ المُلْك الحقيقيّ التام لله، وجميع حمد أهل السموات والأرض مُستَحقٌّ لله تعالى، حيث هو قادر على كل شيء، وما قدَّره الله مِن عطاءٍ أو منعٍ لا رادَّ له، وعنده لا ينفع ذا الغنى غِناه، إنما ينفعه العمل الصالح.', 'استحباب هذا الذكر عقيب الصلوات لما اشتمل عليه من ألفاظ التوحيد والحمد.
المبادرة إلى امتثال السنن، وإشاعتها.', 'أملى: ألقى علي لأكتب.
لا ينفع ذا الجد منك الجدّ: لا ينفع ذا الغنى منك غناه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65102', false),
(21417, 2, 216, 1417, 'hadith', 'عن عبد الله ابن الزبير رضي الله عنهما أنه كان يقول دبر كل صلاة، حين يسلم: لا إله إلا الله وحده لا شريك له ، له الملك وله الحمد ، وهو على كل شيء قدير . لا حول ولا قوة إلا بالله ،لا إله إلا الله، ولا نعبد إلا إياه، له النعمة، وله الفضل وله الثناء الحسن. لا إله إلا الله مخلصين له الدين ولو كره الكافرون . قال ابن الزبير: وكان رسول الله صلى الله عليه وسلم، يهلل بهن دبر كل صلاة.', '"La ilaha illallahu wahdahu la sharika lahu, lahul- mulku, wa lahul-hamdu, wa Huwa ''ala kulli shai''in Qadir. La hawla wa la quwwata illa billah. La ilaha illallahu, wa la na''budu illa iyyahu, Lahun-ni''matu, wa lahul-fadlu, wa lahuth-thana''ul-hasan. La ilaha ilallahu, mukhlisina, lahud-dina, wa lau karihal-kafirun (there is no true god except Allah; He is One. To Him belongs the dominion and to Him is all praise, and He is Powerful over all things. There is no power and might except with (the help of) Allah. There is no God but Allah and we worship none except Him, to Him belongs the bounty and to Him belongs the grace, and to Him belongs all excellent praise; there is no deity but Allah. We reserve our devotion exclusively for Him though the disbelievers may detest it)." Ibn Az-Zubair said: The Messenger of Allah (ﷺ) used to celebrate Allah''s Greatness in those terms after every Salat (prayer)..', 'عبد الله ابن الزبير رضي الله عنهما', 'It has been reported that ''Abdullah bin Zubair (May Allah be pleased with them) used to recite after Taslim at the conclusion of every Salat (prayer):', 'صحيح', 'رياض الصالحين 1417', 'Riyad as-Salihin 1417', 'ریاض الصالحین 1417', 'رواه مسلم', 'كان رسولُ الله صلى الله عليه وسلم يُهلِّلُ بعد تسليمِه من كلِّ صلاةٍ مكتوبةٍ بهذا الذكر العظيم، ومعناه: 

"لا إله إلا الله": يعني لا معبود بحق إلا الله. 

"وحده لا شريك له" أي: إنه لا مشارك له في ألوهيته وربوبيته وأسمائه وصفاته. 

"له الملك" أي: له الملك المُطْلَق العام الشامل الواسع، ملك السموات والأرض وما بينهما. 

"وله الحمد" أي: هو المُتصف بالكمال المطلق، المحمود بالكمال محبةً وتعظيمًا على كل حال، في السراء، وفي الضراء. 

"وهو على كل شيء قدير": فقُدرته كاملة وتامَّة من كل وجهٍ، لا يُعجزه شيءٌ، ولا يمتنع عليه أمرٌ من الأمور. 

"لا حول ولا قوة إلا بالله" أي: لا تَحَوُّل من حالٍ إلى حال، ومن معصية الله إلى طاعته، ولا قوة إلا بالله فهو المعين وعليه التُّكْلان. 

"لا إله إلا الله، ولا نعبد إلا إياه": تأكيد على معنى الألوهية ونفي الشرك، وأنه لا يستحق العبادة سواه. 

"له النعمة وله الفضل": فهو الذي يخلق النِّعَم ويملكها، ويتفضَّل بها على من يشاء من عباده.

"وله الثناء الحسن": على ذاته وصفاته وأفعاله ونعمه، وعلى كل حال.

"لا إله إلا الله، مخلصين له الدين": أي موحِّدين لا رياء ولا سمعة في طاعة الله. 

"ولو كره الكافرون"، أي: ثابتين على توحيد الله وعبادته ولو كره الكافرون.', 'استحباب المحافظة على هذا الذكر بعد كل صلاة مكتوبة.
المسلم يَعْتَزُّ بدينِهِ ويُظْهِرُ شعائرَه، ولو كره الكافرون.
إذا وَرَدَتْ في الحديث كلمةُ: "دُبر الصلاة"، فإن كان ما في الحديث ذِكْرًا فالأصل أن يكون بعد السلام، وإن كان دعاءً فيكون قبل السلام من الصلاة.', 'الثناء: تكرار المدح والذكر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6203', false),
(21418, 2, 216, 1418, 'hadith', 'عن أبي هريرة رضي الله عنه أن فقراء المهاجرين أتوا رسول الله صلى الله عليه وسلم فقالوا: "ذهب أهل الدثور بالدرجات العلى، والنعيم المقيم: يصلون كما نصلي، ويصومون كما نصوم، ولهم فضل من أموال: يحجون، ويعتمرون، ويجاهدون، ويتصدقون. فقال: "ألا أعلمكم شيئًا تدركون به من سبقكم، وتسبقون به من بعدكم، ولا يكون أحد أفضل منكم إلا من صنع مثل ما صنعتم؟ قالوا: بلى يا رسول الله، قال: "تسبحون، وتحمدون، وتكبرون، خلف كل صلاة ثلاثًا وثلاثين قال أبو صالح الراوي عن أبي هريرة، لما سئل عن كيفية ذكرهن، قال: يقول: سبحان الله، والحمد لله، والله أكبر، حتى يكون منهن كلهن ثلاثًا وثلاثين. ((متفق عليه)). وزاد مسلم في روايته: فرجع فقراء المهاجرين إلى رسول الله صلى الله عليه وسلم، فقالوا: سمع إخواننا أهل الأموال بما فعلنا، وفعلوا مثله؟ فقال رسول الله: "ذلك فضل الله يؤتيه من يشاء". ((الدثور))جمع دثر- بفتح الدال و اسكان الثاء المثلثة- و هو: المال الكثير.', 'The poor Emigrants came to the Messenger of Allah (ﷺ) and said: "The wealthy have gone with the highest ranks and lasting bliss." He asked: "How is that?" They replied: "They offer Salat (prayer) as we offer it; they observe fast as we do; (and as they are wealthy) they perform Hajj and ''Umrah, and go for Jihad, and they spend in charity but we cannot, and they free the slaves but we are unable to do so." The Messenger of Allah (ﷺ) said, "Shall I not teach you something with which you may overtake those who surpassed you and with which you will surpass those who will come after you? None will excel you unless he who does which you do." They said: "Yes, please do, O Messenger of Allah" He (ﷺ) said, "You should recite: Tasbih (Allah is free from imperfection), Takbir (Allah is Greatest), Tahmid (Praise be to Allah) thirty-three times after each Salat.".Abu Salih, the subnarrator of the Hadith said, when Abu Hurairah (May Allah be pleased with him) was asked about the manner of reciting Tasbih, Tahmid and Takbir, he said, "Recite: "Subhan-Allah, wal-hamdulillah, wallahu Akbar'', till all are recited thirty-three times.', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 1418', 'Riyad as-Salihin 1418', 'ریاض الصالحین 1418', null, null, null, null, 'sunnah.com', null, false, null, false),
(21419, 2, 216, 1419, 'hadith', 'وعنه عن رسول الله صلى الله عليه وسلم قال: «من سبح الله في دبر كل صلاة ثلاثًا وثلاثين، وحمد الله ثلاثًا وثلاثين، وكبر الله ثلاثًا وثلاثين، وقال تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير، غفرت خطاياه وإن كانت مثل زبد البحر».', 'The Messenger of Allah (ﷺ) said, "He who recites after every prayer: Subhan-Allah (Allah is free from imperfection) thirty-three times; Al-hamdu lillah (praise be to Allah) thirty-three times; Allahu Akbar (Allah is Greatest) thirty-three times; and completes the hundred with: La ilaha illallahu, wahdahu la sharika lahu, lahul-mulku wa lahul-hamdu, wa Huwa ''ala kulli shai''in Qadir (there is no true god except Allah. He is One and He has no partner with Him. His is the sovereignty and His is the praise, and He is Omnipotent), will have all his sins pardoned even if they may be as large as the foam on the surface of the sea.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1419', 'Riyad as-Salihin 1419', 'ریاض الصالحین 1419', 'رواه مسلم', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنّ من قال بعد انقضاء الصلاة المفروضة: 

ثلاثًا وثلاثين مرة: "سبحان الله" وهو تنزيه الله عن النقائص. 

وثلاثًا وثلاثين: "الحمد لله" وهو الثناء عليه بصفات الكمال مع محبته وتعظيمه. 

وثلاثًا وثلاثين: "الله أكبر" وهو أن الله أعظم وأجل من كل شيء.

وتكملة العدد مئة بقول: "لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير" ومعناه: لا معبود بحق إلا الله وحده لا شريك له، وأنه سبحانه المختص بالملك التام، والمستحق للثناء والمدح مع المحبة والتعظيم دون من سواه، وأنه قادر لا يعجزه شيء.

فمن قال ذلك مُحِيَتْ خطاياه وغفرت، ولو كانت كثيرة مثل الرغوة البيضاء التي تعلو البحر عند تموُّجِه وهيجانِه.', 'استحباب هذا الذِّكر بعد الصَّلوات المفروضة.
هذا الذكر سبب لغفران الذنوب.
عظيم فضل الله تعالى ورحمته ومغفرته.
هذا الذِّكر سببٌ لمغفرة الذُّنوب، والمراد: تكفير صغائر الذُّنوب، أما الكبائر فلا يُكَفِّرها إلَّا التُّوبة.', 'زَبَدِ البَحْرِ: رغْوَته عند هيَجَانه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/10948', false),
(21420, 2, 216, 1420, 'hadith', 'عن كعب بن عجرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: «معقبات لا يخيب قائلهن -أو فاعلهن- دبر كل صلاة مكتوبة: ثلاثًا وثلاثين تسبيحة وثلاثًا وثلاثين تحميدة، وأربعًا وثلاثين تكبيرة».', 'The Messenger of Allah (ﷺ) said, "There are some words, the reciters of which will never be disappointed. These are: Tasbih', 'كعب بن عجرة رضي الله عنه', 'Ka''b bin ''Ujrah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1420', 'Riyad as-Salihin 1420', 'ریاض الصالحین 1420', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21421, 2, 216, 1421, 'hadith', 'عن سعد بن أبي وقاص رضي الله عنه أن رسول الله صلى الله عليه وسلم كان يتعوذ دبر الصلوات بهؤلاء الكلمات: «اللهم إني أعوذ بك من الجبن والبخل، وأعوذ بك من أن أرد إلى أرذل العمر وأعوذ بك من فتنة الدنيا، وأعوذ بك من فتنة القبر».', 'The Messenger of Allah (ﷺ) used to seek (Allah''s) protection after prayers in these words: "Alla-humma inni a''udhu bika minal-jubni wal- bukhl, wa a''udhu bika min an uradda ila ardhalil-''umur, wa a''udhu bika min fitnatid-dunya, wa a''udhu bika min fitnatil-qabr (O Allah, I seek refuge with You from cowardice, miserliness and from being sent back to a feeble age; and, seek refuge with You from the trials of this life and those of the grave).".', 'سعد بن أبي وقاص رضي الله عنه', 'Sa''d bin Abu Waqqas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1421', 'Riyad as-Salihin 1421', 'ریاض الصالحین 1421', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21422, 2, 216, 1422, 'hadith', 'عن معاذ رضي الله عنه أن رسول الله صلى الله عليه وسلم أخذ بيده وقال: "يا معاذ والله إني لأحبك" فقال: "أوصيك يا معاذ لا تدعن في دبر كل صلاة تقول: اللهم أعني على ذكرك، وشكرك، وحسن عبادتك". رواه أبو داود بإسناد صحيح.', 'The Messenger of Allah (ﷺ) took hold of my hand and said, "O Mu''adh! By Allah I love you, so I advise you to never forget to recite after every prayer: "Allahumma a''inni ala dhikrika, wa shukrika, wa husni ''ibadatika (O Allah, help me remember You, to be grateful to You, and to worship You in an excellent manner).".', 'معاذ رضي الله عنه', 'Mu''adh (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1422', 'Riyad as-Salihin 1422', 'ریاض الصالحین 1422', null, 'أَخَذَ النبيُّ صلى الله عليه وسلَّم بِيَدِ معاذ رضي الله عنه، وقال له: والله إني لَأُحِبُّك، وأُوصيك يا معاذ لا تَدعنَّ أن تقول آخِرَ كلِّ صلاة: 
(اللهم أَعِنّي على ذكرك) في كلِّ قول وعَمَلٍ يُقَرِّبُ إلى طاعة، 
(وشُكْرِك) بِحُصُولِ النِّعَم واندفاع النِّقَم، 
(وحُسْن عبادتك) بالإخلاص لله والمتابعة للنبي صلى الله عليه وسلم.', 'مَشروعيَّة إِخبار الشَّخص بِحُبِّه في الله.
استحباب هذا الدعاء في دُبُرِ كلِّ صلاة مفروضة ونافلة.
في الدعاء بهذه الألفاظ القليلة مطالب الدنيا والآخرة.
من فوائد المحبة في الله التَّواصي بالحق والتناصح والتعاون على البر والتقوى.
قال الطيبي: ذِكْرُ الله مُقدِّمةُ انشراح الصدر، وشُكرُه وسيلةُ النعم المستجابة، وحسن العبادة المطلوب منه التَّجَرُّد عما يَشغله عن الله تعالى.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3518', false),
(21423, 2, 216, 1423, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إذا تشهد أحدكم فليستعذ بالله من أربع، يقول: اللهم إني أعوذ بك من عذاب جهنم، ومن عذاب القبر ومن فتنة المحيا والممات، ومن شر فتنة المسيح الدجال».', 'The Messenger of Allah (ﷺ) said, "When anyone of you has done his Tashahhud during Salat (prayer), he should seek refuge in Allah against four things and say: "Allahumma inni a''udhu bika min ''adhabi jahannam, wa min ''adhabil-qabr, wa min fitnatil-mahya wal-mamat, wa min sharri fitnatil-masihid-dajjal (O Allah! I seek refuge in You from the torment of Hell, from the torment of the grave, from the trials of life and death, and from the mischief of Al-Masih Ad-Dajjal (Antichrist).".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1423', 'Riyad as-Salihin 1423', 'ریاض الصالحین 1423', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21424, 2, 216, 1424, 'hadith', 'عن علي رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم إذا قام إلى الصلاة يكون من آخر ما يقول بين التشهد والتسليم: «اللهم اغفر لي ما قدمت وما أخرت، وما أسررت وما أعلنت، وما أسرفت، وما أنت أعلم به مني، أنت المقدم، وأنت المؤخر، لا إله إلا أنت».', 'When the Messenger of Allah (ﷺ) was in Salat (prayer), he used to supplicate towards the end of prayer after Tashahhud and before the concluding salutations: "Allahum-maghfir li ma qaddamtu wa ma akh-khartu, wa ma asrartu, wa ma a''lantu, wa ma asraftu, wa ma Anta a''lamu bihi minni. Antal-Muqqadimu, wa Antal-Mu''akh-khiru. La ilaha illa Anta (O Allah! Forgive my former and latter sins, which I have done secretly and those which I have done openly, and that I have wronged others, and those defaults of mine about which You have better knowledge than I have. You Alone can send whomever You will to Jannah, and You Alone can send whomever You will to Hell-fire. None has the right to be worshipped but You.".', 'علي رضي الله عنه', '''Ali (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1424', 'Riyad as-Salihin 1424', 'ریاض الصالحین 1424', 'رواه مسلم', 'كان رسول الله صلى الله عليه وسلم إذا قام إلى الصلاة يكون من آخر ما يقول بين التشهد والتسليم: "اللهم اغفر لي ما قدمت"، من سيئة، "وما أخرت"، من عمل، أي: جميع ما فرط مني، "وما أسررت" أي: أخفيت، "وما أعلنت، وما أسرفت"، أي: جاوزت الحد، مبالغة في طلب الغفران بذكر أنواع العصيان، "وما أنت أعلم به مني"، أي: من ذنوبي التي لا أعلمها عدداً وحكماً، "أنت المقدم"، أي: بعض العباد إليك بتوفيق الطاعات، "وأنت المؤخر"، أي: لبعضهم بالخذلان عن النصرة أو أنت المقدم لمن شئت في مراتب الكمال، وأنت المؤخر لمن شئت عن معالي الأمور إلى سفسافها، "لا إله إلا أنت" فلا معبود بحق غيرك.', 'استحباب التقرب إلى الله بهذا الدعاء بين التشهد والتسليم.
الحث على الاستغفار واستشعار الخضوع لمقام الربوبية.
الاستغفار بعد الطاعة مؤذن بأن العبد ينبغي أن يكون بالله لا بعمله، فلا يغتر بما عمل.
الذنب والتقصير أمر لازم للبشر، فينبغي على العبد أن يتوب من ذلك كله.
علم الله محيط بكل الأعمال والأقوال والأفعال والأحوال.
الله سبحانه يرفع من يشاء ويضع من يشاء ولا يسأل سبحانه عما يفعل.', 'أسررت : أخفيت.
أعلنت : أظهرت.
أسرفت : أكثرت.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5471', false),
(21425, 2, 216, 1425, 'hadith', 'عن عائشة رضي الله عنه قالت: كان النبي صلى الله عليه وسلم يكثر أن يقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي".', 'The Prophet (ﷺ) used to recite frequently in his bowing and prostration: "Subhanak- Allahumma, Rabbana wa bihamdika. Allahum-maghfir li (O Allah! You are free from imperfection and I begin with praising You. Forgive my sins).".', 'عائشة رضي الله عنه', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1425', 'Riyad as-Salihin 1425', 'ریاض الصالحین 1425', 'متفق عليه', 'قالت عائشة رضي الله عنها : ما صلى رسول الله صلى الله عليه وسلم صلاةً بعد أن نزلت سورة النصر إلا وقال في ركوعها وسجودها: سبحانك اللهم وبحمدك اللهم اغفر لي، يعمل بما أُمِرَ به في القرآن في قوله (فسبح بحمد ربك واستغفره).
وأخبرت رضي الله عنها أنها سألت النبي صلى الله عليه وسلم عن هذه الكلمات التي أصبح يقولها في الركوع والسجود فأخبرها أن الله تبارك وتعالى أخبره أنه سيرى علامة في أمته، فإذا رآها أكثر من قول: سبحان الله وبحمده أستغفر الله وأتوب إليه.
وهذه العلامة: (إذا جاء نصر الله والفتح –فتح مكة- ورأيت الناس يدخلون في دين الله أفواجاً فسبح بحمد ربك واستغفره إنه كان تواباً).', 'زيادة استغفار رسول الله -صلى الله عليه وسلم- وتضرعه وإقباله على الله -تعالى- قبل موته.
الشكر لله -تعالى- عند حصول النعم.
استحباب الاستغفار والدعوات اقتداء بالرسول -صلى الله عليه وسلم-.
وقوع ما بشر الله به رسوله لأن وعده -سبحانه- حق.', 'سبحانك : تنزيها ًلك عما لا يليق بك من كل نقص.
اللهم : يا الله.
يتأول القرآن : يعمل ما أُمرَ به في القرآن.
رأيتها : أبصرتُها أو عرفتُها.
واستغفره : أي: اطْلُبْ منه المغفرة، والمغفرة: هي التجاوز عن الذنب والستر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4826', false),
(21426, 2, 216, 1426, 'hadith', 'وعنها أن رسول الله صلى الله عليه وسلم كان يقول في ركوعه وسجوده: «سبوح قدوس رب الملائكة والروح».', 'The Messenger of Allah (ﷺ) used to recite in his bowing and prostration: "Subbuhun Quddusun, Rabbul-mala''ikati war-ruh .', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1426', 'Riyad as-Salihin 1426', 'ریاض الصالحین 1426', 'رواه مسلم', 'عن عائشة رضي الله عنها قالت كان النبي صلى الله عليه وسلم يقول في ركوعه وسجوده: "سبوح قدوس رب الملائكة والروح"، يعني: أنت سبوح قدوس، وهذه مبالغة في التنزيه، وأنه جل وعلا سبوح قدوس، "رب الملائكة"، وهم جند الله عز وجل عالم لا نشاهدهم، "والروح"، هو جبريل وهو أفضل الملائكة، فينبغي للإنسان أن يكثر في ركوعه وسجوده، من قوله: "سبوح قدوس رب الملائكة والروح".
القدوس من أسماء الله الحسنى، وهو مأخوذ من قدّس، بمعنى: نزّهه وأبعده عن السوء مع الإجلال والتعظيم.
والسبوح من أسماء الله الحسنى، أي المسبَّح.', 'استحباب قول المصلي ذلك في ركوعه وسجوده.
استحباب دعاء الله بصفاته العليا الدالة على كماله وجلاله.
جواز التسبيح في السجود وليس خاصا بالدعاء.
السبوح القدوس من أسماء الله -تعالى-.', 'سبوح : منزه من الشريك وكل ما لا يليق بالألوهية والربوبية والصفات.
قدوس : المطهر من كل ما لا يليق بالخالق.
الروح : جبريل -عليه السلام-.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6015', false),
(21427, 2, 216, 1427, 'hadith', 'عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: « فأما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم».', 'The Messenger of Allah (ﷺ) said: "Glorify your Lord in Ruku'' (bowing posture) and exert yourself in supplication in prostration. Thus your supplications are liable to be accepted.".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1427', 'Riyad as-Salihin 1427', 'ریاض الصالحین 1427', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21428, 2, 216, 1428, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء».', 'The Messenger of Allah (ﷺ) said, "A slave becomes nearest to his Rubb when he is in prostration. So increase supplications while prostrating.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1428', 'Riyad as-Salihin 1428', 'ریاض الصالحین 1428', 'رواه مسلم', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ أقربَ ما يكون العبد من ربه وهو ساجد؛ وذلك أنّ المصليَ يَضعُ أعلى وأشرف ما في جسده على الأرض خضوعًا وتَذَلُّلًا وتواضعًا لله عز وجل وهو ساجد.

وقد أمر صلى الله عليه وسلم بالإكثار من الدعاء في السجود، فيجتمع في ذلك التَذَلُّلُ لله بالقول والفعل.', 'الطاعة تزيدُ العبدَ قُرْبًا مِن الله سبحانه وتعالى.
استحبابِ كثرةِ الدعاء في السجود؛ لأنه من مواطن الإجابة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5382', false),
(21429, 2, 216, 1429, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم كان يقول في سجوده: «اللهم اغفر لي ذنبي كله دقه وجله، وأوله وآخره، وعلانيته وسره».', 'The Messenger of Allah (ﷺ) used to say in his prostration: Allahum-maghfir li dhanbi kullahu: diqqahu wa jillahu, wa ''awwalahu wa akhirahu, wa alaniyatahu wa sirrahu (O Allah! Forgive all my sins, the small and the great, first and the last, the open and the secret).".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1429', 'Riyad as-Salihin 1429', 'ریاض الصالحین 1429', 'رواه مسلم', 'كَانَ النبيُّ صلى الله عليه وسلم يدعو في سجوده فيقول: 

(اللهم اغفر لي ذنبي) بِستْرِه، وأنْ تَقِيَني تَبِعَتَه؛ فتعفو وتتجاوز وتصفح، (كله)، أعني: (دِقّه) صغيره وقليله، (وجِلّه) كبيره وكثيره، (وأوله) أول ذنب، (وآخره)، وما بينهما، (علانيته وسره) مما لا يعلمه إلا أنت سبحانك.', 'قال ابن القيم: وطلب غفران الذّنوب الصِّغار والكبار، الدَّقيق والجليل، الأوّل والآخر، السّر والعلانية، فهذا التَّعميم وهذا الشُّمول لتأتي التَّوبة على ما عَلِمَه العبدُ من ذنوبه، وما لم يَعْلَمْه.
قيل: إنما قدّم (الدِّق) على (الجِلّ)؛ لأن السائل يتصاعد في مسألته أي يَتَرَقّى، ولأن الكبائر تنشأ غالبًا من الإصرار على الصغائر وعدم المبالاة بها، فكأنها وسائل إلى الكبائر، ومِن حق الوسيلة أنْ تُقَدّم إثباتًا ورفعًا.
التضرع إلى الله تعالى، وطلبه المغفرة من جميع الذنوب، الصغائر والكبائر.
قال النووي: فيه توكيد الدعاء وتكثير ألفاظه وإنْ أَغْنَى بعضُها عن بعض.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5470', false),
(21430, 2, 216, 1430, 'hadith', 'عن عائشة رضي الله عنها قالت: افتقدت النبي صلى الله عليه وسلم ذات ليلة فتحسست، فإذا هو راكع.-أو ساجد- يقول: "سبحانك وبحمدك لا إله إلا أنت" ، وفي رواية: فوقعت يدي على بطن قدميه، وهو في المسجد، وهما منصوبتان، وهو يقول: "اللهم إني أعوذ برضاك من سخطك، وبمعافاتك من عقوبتك، وأعوذ بك منك، لا أحصي ثناء عليك أنت كما أثنيت على نفسك".', 'One night I missed the Messenger of Allah (ﷺ) from his bed. I searched for him. When I found him he was in bowing or prostrating posture and was reciting: Subhanaka wa bi hamdika. La ilaha illa Anta (You are free from imperfection and I begin praising You. There is no true god except You)."Another narration is: My hand fell over his feet while he was in prostration with his feet erect. He was supplicating: "Allahumma inni a''udhu biridaka min sakhatika, wa bi-mu''afatika min ''uqubatika, wa a''udhu bika minka, la uhsi thana''an ''alaika, Anta kama athnaita ''ala Nafsika (O Allah! I seek protection against Your Wrath in Your Pleasure. I seek protection in Your Pardon against Your chastisement, I am not capable of enumerating praise of You. You are as You have lauded Yourself)."', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1430', 'Riyad as-Salihin 1430', 'ریاض الصالحین 1430', 'رواه مسلم', 'قالت عائشة رضي الله عنها: كنت نائمة إلى جنب النبي صلى الله عليه وسلم، ففقدته من الليل، فلمست بيدي الموضع الذي كان يصلي فيه في الحجرة؛ فإذا هو ساجد وقدماه قائمتان، وإذا هو يقول: 

(أعوذ) وأتوسل (برضاك من سخطك) عليّ أو على أمتي، (و) أستعيذ (بمعافاتك) وعفوك الكثير (من عقوبتك)، 
(وأعوذ بك منك) وبصفات جمالك من صفات جلالك، حيث لا يُعيذ منك إلا أنت، فلا مَنْجَى ولا مَلْجَأ من الله إلا إليه، 
(لا أحصي ثناء عليك) لا أطيق ولا أبلغ حصرًا وعددًا لعجزي إحصاء نعمتك وإحسانك كما تستحقه وإن اجتهدت في ذلك، 
(أنت كما أثنيت على نفسك) فأنت الذي أثنيت على ذاتك ثناء يليق بك، فمن يقدر على أداء حق ثنائك؟!', 'استحباب هذه الأدعية في السجود.
 قال ميرك: وفي إحدى روايات النسائي: كان يقول هذا الدعاء إذا فرغ من صلاته وتبوأ مضجعه.
استحباب الثناء على الله بصفاته ودعائه بأسمائه الثابتة في الكتاب والسنة.
فيه تعظيم الخالق في الركوع والسجود.
جواز الاستعاذة بصفات الله، كما يجوز الاستعاذة بذاته -سبحانه وتعالى-.
قال الخطابي: في هذا الكلام معنى لطيف، وهو: أنه قد استعاذ بالله أن يجيره برضاه من سخطه، وبمعافاته من عقوبته، والرضى والسخط ضدان متقابلان، وكذلك المعافاة والمؤاخذة بالعقوبة، فلما صار إلى ذكر ما لا ضد له وهو الله سبحانه وتعالى استعاذ به منه لا غير، ومعنى ذلك: الاستغفار من التقصير من بلوغ الواجب من حق عبادته، والثناء عليه. وقوله: لا أحصي ثناء عليك: أي لا أطيقه ولا أبلغه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3566', false),
(21431, 2, 216, 1431, 'hadith', 'عن سعد بن أبي وقاص رضي الله عنه قال: كنا عند رسول الله صلى الله عليه وسلم فقال: "أيعجز أحدكم أن يكسب في كل يوم ألف حسنة!" فسأله سائل من جلسائه: كيف يكسب ألف حسنة؟ قال: "يسبح مائة تسبيحة، فيكتب له ألف حسنة، أو يحط عنه ألف خطيئة" ((رواه مسلم)). قال الحميدي: كذا هو في كتاب مسلم : ((او يحط)) قال البرقاني: ورواه شعبة و ابو عوانة, و يحيى القطان, عن موسى الذي رواه مسلم من جهته فقالوا:((و يحط)) بغير الف.', 'We were with the Messenger of Allah (ﷺ) when he asked, "Is anyone of you unable to earn a thousand good deeds?" One of those present asked: "How can one earn thousand good deeds in a day?" He (ﷺ) replied, "By saying: Subhan Allah a hundred times, then one thousand good deeds will be recorded for him or one thousand sins will be blotted out from his record.".', 'سعد بن أبي وقاص رضي الله عنه', 'Sa''d bin Abu Waqqas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1431', 'Riyad as-Salihin 1431', 'ریاض الصالحین 1431', null, 'سأل النبي صلى الله عليه وسلم أصحابه: 

ألا يستطيع أحدكم أن يحصل في كل يوم على ألف حسنة؟! 

فقال أحد جُلَسَائِه: كيف يتحصل المرء على ألف حسنة في يوم بسهولة؟ 

قال: يقول: "سبحان الله" مائة مرة؛ فيُكتب له ألف حسنة؛ لأن الحسنة الواحدة بعشر أمثالها، أو تُمْحَى عنه ألف سيئة من سيئاته.', 'الحض على الفضائل؛ لأنها سُلَّم الطاعات.
فضل التسبيح والذكر، وأن هذا العمل اليسير الذي لا يكلف المرء شيئًا، يحصل له به هذا الأجر الكبير.
مبادرة الصحابة إلى فعل الخيرات دون تأخير.
مضاعفة الحسنات إلى عشر أمثالها، وذلك مثل قوله تعالى: (‌مَنْ ‌جَاءَ ‌بِالْحَسَنَةِ ‌فَلَهُ ‌عَشْرُ ‌أَمْثَالِهَا) [الأنعام: 160]، وهذا أقل درجات التضعيف، وإلا فقد ورد إلى سبعمائة ضعف.
جاء في بعض الروايات بدلًا من (أو) جاء (و) في قوله: أو يحط عنه... قال القاري: قد تأتي الواو بمعنى أو فلا منافاة بين الروايتين، وكأن المعنى: أن من قالها يكتب له ألف حسنة، إن لم يكن عليه فيحط بعض ويكتسب بعض، ويمكن أن تكون أو بمعنى الواو أو بمعنى بل فحينئذ يجمع له بينهما وفضل الله أوسع من ذلك انتهى، أي أنه يكتب له ألف حسنة ويحط عنه ألف سيئة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3762', false),
(21432, 2, 216, 1432, 'hadith', 'عن أبي ذر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «يصبح على كل سلامى من أحدكم صدقة: فكل تسبيحة صدقة، وكل تحميدة صدقة، وكل تهليلة صدقة، وكل تكبيرة صدقة، وأمر بالمعروف صدقة، ونهي عن المنكر صدقة، ويجزي من ذلك ركعتان يركعهما من الضحى».', 'The Messenger of Allah (ﷺ) said, "Every morning charity is due from every joint bone of the body of every one of you. Every utterance of Allah''s Glorification (i.e., Subhan-Allah) is an act of charity, and every utterance of praise of Him (i.e., Al-hamdu lillah) is an act of charity, and every utterance of profession of Faith (i.e., La ilaha illallah) is an act of charity, and every utterance of His Greatness (i.e., Allahu Akbar) is an act of charity; and enjoining good is an act of charity and forbidding what is disreputable is an act of charity; and two Rak''ah prayer which one offers in the forenoon (Ad- Duha) will suffice for all this.".', 'أبي ذر رضي الله عنه', 'Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1432', 'Riyad as-Salihin 1432', 'ریاض الصالحین 1432', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21433, 2, 216, 1433, 'hadith', 'عن أم المؤمنيين جويرية بنت الحارث رضي الله عنها أن النبي صلى الله عليه وسلم خرج من عندها بكرة حين صلى الصبح وهي في مسجدها، ثم رجع بعد أن أضحي وهي جالسة، فقال: "مازلت على الحالة التي فارقت عليها؟" قالت: نعم، فقال النبي صلى الله عليه وسلم: "لقد كنت بعدك أربع كلمات ثلاث مرات، لو وزنت بما قلت منذ اليوم لوزنتهن: سبحان الله وبحمده عدد خلقه، ورضا نفسه، وزنة عرشه، ومداد كلماته" ((رواه مسلم)). وفي رواية له: سبحان الله عدد خلقه، سبحان الله رضا نفسه، سبحان الله زنة عرشه، سبحان الله مداد كلماته". وفي رواية الترمذي: ألا أعلمك كلمات تقولينها؟ سبحان الله عدد خلقه، سبحان الله عدد خلقه، سبحان الله عدد خلقه، سبحان الله رضا نفسه، سبحان الله رضا نفسه، سبحان الله رضا نفسه، سبحان الله زنة عرشه، سبحان الله زنة عرشه، سبحان الله زنة عرشه، سبحان الله مداد كلماته، سبحان الله مداد كلماته، سبحان الله مداد كلماته".', 'The Prophet (ﷺ) came out from my apartment in the morning as I was busy in performing the dawn prayer. He came back in the forenoon and found me sitting there. The Prophet (ﷺ) said, "Are you still in the same position as I left you." I replied in the affirmative. Thereupon the Prophet said, "I recited four words three times after I had left you. If these are to be weighed against all you have recited since morning, these will be heavier. These are: Subhan-Allahi wa bihamdihi, `adada khalqihi, wa rida nafsihi, wa zinatah `arshihi, wa midada kalimatihi .', 'أم المؤمنيين جويرية بنت الحارث رضي الله عنها', 'Juwairiyah bint Al-Harith (May Allah be pleased with her), the Mother of the Believers,', 'صحيح', 'رياض الصالحين 1433', 'Riyad as-Salihin 1433', 'ریاض الصالحین 1433', null, 'خرجَ النبيُّ صلى الله عليه وسلم من عند زوجه أم المؤمنين جويرية رضي الله عنها أول النهار حين صلى الصبح، وهي جالسة في موضع صلاتها، ثم رجع بعد أن انتصف النهار وقت الضحى، وهي ما زالت جالسة في مكانها، فقال: 

ما زلتِ على الحال التي فارقتكِ عليها؟ 

قالت: نعم، قال النبي صلى الله عليه وسلم: 

لقد قلت بعدك أربع كلمات، وكررتها ثلاث مرات، لو قُوبِلت من حيث الأجر بما قلت جميع الوقت الذي أنت جالسة فيه لترجَّحت عليها: 

(سبحان الله) وتنزيهه من جميع النقائص، (وبحمده) حيث له الثَّناء الجميل الذي هدى لذلك، (عدد خلقه) الذين لا يحصيهم إلا الله، (ورضا نفسه) بقدر ما يُرضيه عمن رضي الله عنه من عباده وهو شيءٌ لا يُحاط به، (وزنة عرشه) الذي هو أعظم المخلوقات وأثقلها، (ومداد كلماته) وكلمات الله لا تحصر ولا تنفد؛ وهذا يعمّ الأقسام الثلاثة ويشملها؛ فإنَّ مداد كلماته سبحانه لا نهايةَ لقدره، ولا لصفته، ولا لعدده، ولكن المراد: المبالغة به في الكثرة؛ لأنه ذكر أولًا ما يحصره العد الكثير من عدد الخلق، ثم ارتقى إلى ما هو أعظم من ذلك وعبر عنه برضى نفسه، ثم زنة أعظم المخلوقات وهو العرش؛ فالأول للعدِّ والكميّة، والثاني للصِّفة والكيفية، والثالث للعِظَم والثِّقَل.', 'بيان فضل هذه الكلمات، والحث على قولها.
الذِّكْر يتفاضل فبعضه أفضل من بعض.
قال النووي على قوله (سبحان الله وبحمده مداد كلماته): ‌والمراد ‌المبالغة به في الكثرة؛ لأنه ذكر أولًا ما يحصره العد الكثير من عدد الخلق، ثم زنة العرش، ثم ارتقى إلى ما هو أعظم من ذلك وعبر عنه بهذا، أي ما لا يحصيه عد كما لا تحصى.
قال ابن القيم: إنَّ ما يقوم بقلب الذَّاكر حين يقول: سبحان الله وبحمده، عدد خلقه ... إلى آخره من معرفته وتنزيهه وتعظيمه من هذا القدر المذكور من العدد أعظم مما يقوم بقلب القائل: "سبحان الله" فقط.
الإرشاد إلى جوامع الكلم التي تحمل القليل من الألفاظ، ويعطى عليها عظيم الفضل والثواب.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5508', false),
(21434, 2, 216, 1434, 'hadith', 'عن أبي موسى الأشعري رضي الله عنه عن النبي صلى الله عليه وسلم، قال: "مثل الذي يذكر ربه والذي لا يذكره، مثل الحي والميت" ((رواه البخاري)). ورواه مسلم فقال: "مثل البيت الذي يذكر الله فيه، والبيت الذي لا يذكر الله فيه، مثل الحي والميت".', 'The Prophet (ﷺ) said, "The similitude of one who remembers his Rubb and one who does not remember Him, is like that of the living and the dead.".', 'أبي موسى الأشعري رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', null, 'رياض الصالحين 1434', 'Riyad as-Salihin 1434', 'ریاض الصالحین 1434', null, null, null, null, 'sunnah.com', null, false, null, false),
(21435, 2, 216, 1435, 'hadith', 'عن أبي هريرة، رضي الله عنه، أن رسول الله صلى الله عليه وسلم، قال: «يقول الله تعالى: أنا عند ظن عبدي بي، وأنا معه إذا ذكرني، فإن ذكرني في نفسه، ذكرته في نفسي وإن ذكرني في ملإٍ ذكرته في ملإٍ خير منهم».', 'The Messenger of Allah (ﷺ) said, "Allah the Exalted says: ''I am as my slave expects me to be, and I am with him when he remembers Me. If he remembers Me inwardly, I will remember him inwardly, and if he remembers Me in an assembly, I will remember him in a better assembly (i.e., in the assembly of angels).".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1435', 'Riyad as-Salihin 1435', 'ریاض الصالحین 1435', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21436, 2, 216, 1436, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم: "سبق المفردون" قالوا: وما المفردون يا رسول الله؟ قال: "الذاكرون الله كثيرًا والذكرات" ((رواه مسلم)). وروي : (( المفردون )) بتشديد الراء وتخفيفها والمشهور الذي قاله الجمهور : التشديد.', 'The Messenger of Allah (ﷺ) said, "The Mufarridun have gone ahead." He was asked, "Who are the Mufarridun?" He (ﷺ) replied, "Those men and women who frequently celebrate the remembrance of Allah.".', null, 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 1436', 'Riyad as-Salihin 1436', 'ریاض الصالحین 1436', null, null, null, null, 'sunnah.com', null, false, null, false),
(21437, 2, 216, 1437, 'hadith', 'عن جابر رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «أفضل الذكر: لا إله إلا الله». رواه الترمذي وقال حديث حسن.', 'I heard the Messenger of Allah (ﷺ) saying, "The best way to celebrate the remembrance of Allah is to say: La ilaha illallah (there is no true god except Allah).".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', null, 'رياض الصالحين 1437', 'Riyad as-Salihin 1437', 'ریاض الصالحین 1437', null, null, null, null, 'sunnah.com', null, false, null, false),
(21438, 2, 216, 1438, 'hadith', 'عن عبد الله بن بشر رضي الله عنه أن رجلا قال: يا رسول الله، إن شرائع الإسلام قد كثرت علي، فأخبرني بشيء أتشبث به قال: «لا يزال لسانك رطبًا من ذكر الله». رواه الترمذي وقال حديث حسن.', 'One of the Companions said, "O Messenger of Allah. There are many injunctions of Islam for me. So tell me something to which I may hold fast." He said, "Keep your tongue wet with the remembrance of Allah.".', 'عبد الله بن بشر رضي الله عنه', '''Abdullah bin Busr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1438', 'Riyad as-Salihin 1438', 'ریاض الصالحین 1438', null, 'شَكَى رجلٌ إلى النبيِّ صلى الله عليه وسلم بأن نوافل العبادات قد كَثرت عليه حتى عجز عنها لضعفه، ثم سألَ النبيَّ صلى الله عليه وسلم أنْ يَدلَّه على عملٍ يسيرٍ مُسْتجلِبٍ لثواب كثير يتعلق به ويستمسك. 

فأرشده صلى الله عليه وسلم بأن يكون لسانه طَرِيًّا متحركًا من دوام ذكر الله سبحانه وتعالى في كل وقت وحال؛ من تسبيح وتحميد واستغفار ودعاء ونحو ذلك.', 'فضل المداومة على ذكر الله تعالى.
من عظيم فضل الله تيسير أسباب الأجر.
تفاضل العباد في نصيبهم من أبواب البر والخير.
كثرة ذكر الله باللسان تسبيحًا وتحميدًا وتهليلًا وتكبيرًا وغير ذلك مع مواطأة القلب يقوم مقام كثير من نوافل الطاعات.
مراعاته صلى الله عليه وسلم للسائلين بإجابة كلٍّ بما يناسبه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4716', false),
(21439, 2, 216, 1439, 'hadith', 'عن جابر رضي الله عنه، عن النبي صلى الله عليه وسلم قال: «من قال: سبحان الله وبحمده، غرست له نخلة في الجنة». رواه الترمذي وقال حديث حسن.', 'The Prophet (ﷺ) said, "For him who says: ''Subhan-Allahi wa bi hamdihi (Allah is free from imperfection, and I begin with praising Him, and to Him),'' a palm-tree will be planted in Jannah.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1439', 'Riyad as-Salihin 1439', 'ریاض الصالحین 1439', null, 'أخبرَ النبيُّ صلى الله عليه وسلم أنه من قال: (سبحان الله) وأنزهه (العظيم) بذاته وصفاته وأفعاله (وبحمده) مقرونًا بإضافة أوصاف الكمال له سبحانه؛ نُصبت وغرست له نخلة في أرض الجنة بكل مرة يقولها.', 'الحث على الإكثار من ذكر الله تعالى، ومن ذلك: التسبيح مع التحميد.
الجنة واسعة، وأن غراسها التسبيح والتحميد، فضلاً من الله تعالى ونعمة.
خصت النخلة في الحديث دون غيرها من الأشجار؛ لكثرة منافعها وطيب ثمرتها؛ ولذلك ضرب الله تعالى مثل المؤمن وإيمانه بها في القرآن.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4201', false),
(21440, 2, 216, 1440, 'hadith', 'عن ابن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «لقيت إبراهيم صلى الله عليه وسلم ليلة أسري بي، فقال: يا محمد أقرئ أمتك مني السلام، وأخبرهم أن الجنة طيبة التربة، عذبة الماء، وأنها قيعان، وأن غراسها: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر». رواه الترمذي وقال حديث حسن.', 'Messenger of Allah (ﷺ) said, "I met Ibrahim (ﷺ) on the Night of Ascension (Al-Asra), and he said to me: ''O Muhammad, convey my greetings to your Ummah, and tell them that Jannah has a vast plain of pure soil and sweet water. It is a plain levelled land. The plants grow there by uttering: Subhan-Allah, Al-hamdu lillah, La ilaha illallah and Allahu Akbar (Allah is free from imperfection; praise be to Allah; there is no true god except Allah; and Allah is Greatest).".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'حسن بشواهده', 'رياض الصالحين 1440', 'Riyad as-Salihin 1440', 'ریاض الصالحین 1440', null, 'يُخْبِرُ النبيُّ صلى الله عليه وسلم أنَّه لَقِي إبراهيمَ الخليلَ عليه السلام ليلة الإسراء والمعراج، فقال له يا محمد: أَوْصِل أُمتَك مني السلام، وأَعْلِمْهم أنّ الجنة طيبة التُّرْبة، عذبة الماء لا ملوحة فيه، وأن الجنة واسعة مُسْتَوية خالية من الشجر، وغرسها الكلمات الطيبات، وهنَّ الباقيات الصالحات: سُبْحَانَ اللهِ، وَالحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، كلما قالها المُسلم وكَرَّرَها غُرس له غَرْسٌ في الجنة.', 'الحث على مداومة الذِّكر للإكثار من غِرَاس الجنة.
فضل الأمة الإسلامية؛ حيث بَلَّغَها السلامَ إبراهيمُ عليه الصلاة والسلامُ.
ترغيب إبراهيم عليه السلام أمة محمد صلى الله عليه وسلم في الإكثار من ذكر الله تعالى.
قال الطيبي: الجنة قيعان، ثم إن الله تعالى أوجد بفضله فيها أشجارًا وقصورًا بحسب أعمال العاملين؛ لكل عامل ما يختص به بسبب عمله، ثم إنه تعالى لما يَسَّره لما خُلِق له من العمل لِينال بذلك الثواب جعله كالغارس لتلك الأشجار.', null, 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3791', false)
